const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
function indicatorScore(rule,v){if(v===null||v===undefined||!Number.isFinite(v))return null; const rules={growth:()=>50+v*8,inflation:()=>80-Math.abs(v-2)*12,jobs:()=>90-v*6,debt:()=>100-v*.65,interest:()=>100-v*4,current:()=>50+v*6,fdi:()=>50+v*5,reserves:()=>v*12.5};return rules[rule]?clamp(rules[rule](),0,100):null;}
function ageDays(date,now=Date.now()){return Math.max(0,(now-new Date(date).getTime())/86400000);}
function structuralScore(rows,indicators,now=Date.now(),weights={}){let sum=0,used=0,total=0; const pillars={};let latest=null;for(const d of indicators){const w=Number(weights[d.id]??d.weight);total+=w;const row=rows?.[d.id];let s=indicatorScore(d.rule,row?.value);const age=row?.date?ageDays(row.date.length===4?row.date+'-12-31':row.date,now):Infinity;if(age>550)s=null; if(!pillars[d.pillar])pillars[d.pillar]={sum:0,used:0,total:0};pillars[d.pillar].total+=w;if(s!==null){sum+=s*w;used+=w;pillars[d.pillar].sum+=s*w;pillars[d.pillar].used+=w;if(!latest||row.date>latest)latest=row.date;}}
 return {score:used?sum/used:null,coverage:total?used/total*100:0,used,total,latest,pillars:Object.fromEntries(Object.entries(pillars).map(([k,v])=>[k,{score:v.used?v.sum/v.used:null,coverage:v.total?v.used/v.total*100:0}]))};}
function pairAssessment(a,b){const coverage=Math.min(a?.coverage??0,b?.coverage??0);const delta=a?.score!=null&&b?.score!=null?a.score-b.score:null;return {delta,coverage,label:delta===null?'Unrated':Math.abs(delta)<5?'Balanced':delta>0?'Base advantage':'Quote advantage',tactical:'Insufficient timely evidence',ready:false};}
function pearson(a,b){if(a.length!==b.length||a.length<20)return null;const am=a.reduce((s,x)=>s+x,0)/a.length,bm=b.reduce((s,x)=>s+x,0)/b.length;let n=0,x=0,y=0;for(let i=0;i<a.length;i++){n+=(a[i]-am)*(b[i]-bm);x+=(a[i]-am)**2;y+=(b[i]-bm)**2;}return x&&y?n/Math.sqrt(x*y):null;}
function returns(points){const out={};for(let i=1;i<points.length;i++){if(points[i].v>0&&points[i-1].v>0)out[points[i].d]=Math.log(points[i].v/points[i-1].v);}return out;}
function correlate(a,b,window=60,modeA='log',modeB='log'){const today=new Date().toISOString().slice(0,10),ma=Object.fromEntries(a.map(p=>[p.d,p.v])),mb=Object.fromEntries(b.map(p=>[p.d,p.v]));const dates=Object.keys(ma).filter(d=>mb[d]!==undefined&&d<today).sort();const ra=[],rb=[],ends=[];for(let i=1;i<dates.length;i++){const p=dates[i-1],d=dates[i];if((modeA==='log'&&(ma[d]<=0||ma[p]<=0))||(modeB==='log'&&(mb[d]<=0||mb[p]<=0)))continue;ra.push(modeA==='delta'?ma[d]-ma[p]:Math.log(ma[d]/ma[p]));rb.push(modeB==='delta'?mb[d]-mb[p]:Math.log(mb[d]/mb[p]));ends.push(d);}return {r:pearson(ra.slice(-window),rb.slice(-window)),n:Math.min(window,ra.length),from:ends.slice(-window)[0],to:ends.at(-1)};}
function crossHistory(history,base,quote){return (history||[]).flatMap(row=>{const a=base==='USD'?1:row.rates[base],b=quote==='USD'?1:row.rates[quote];return a>0&&b>0?[{d:row.date,v:b/a}]:[];});}
function sixMonthChange(points,now=Date.now()){if(points.length<2)return null;const end=points.at(-1);const target=new Date(new Date(end.d).getTime());target.setUTCMonth(target.getUTCMonth()-6);const targetDate=target.toISOString().slice(0,10);const start=[...points].reverse().find(p=>p.d<=targetDate);if(!start||ageDays(end.d,now)>12||ageDays(start.d,target.getTime())>10)return null;return {value:(end.v/start.v-1)*100,from:start.d,to:end.d};}

