const numeric = value => value!==null && value!==undefined && String(value).trim()!=='' && !['NULL','\\N'].includes(String(value)) && Number.isFinite(Number(value)) ? Number(value) : null;
const day = value => typeof value==='string' && /^\d{4}-\d{2}-\d{2}$/.test(value) && Number.isFinite(Date.parse(value+'T00:00:00Z')) && new Date(value+'T00:00:00Z').toISOString().slice(0,10)===value;
function sortedUnique(points,limit){
 const map=new Map();
 for(const p of points){const existing=map.get(p.d);if(existing&&existing.v!==p.v)throw Error('Conflicting duplicate official observations');map.set(p.d,p);}
 return [...map.values()].sort((a,b)=>a.d.localeCompare(b.d)).slice(-limit);
}

function parseBocAssets(data){
 if(data.seriesDetail?.V36610?.label!=='Total assets')throw Error('Bank of Canada total-assets definition changed');
 const points=sortedUnique((data.observations||[]).flatMap(r=>{const v=numeric(r.V36610?.v);return day(r.d)&&v!==null&&v>=0?[{d:r.d,v}]:[];}),104);
 if(!points.length)throw Error('No Bank of Canada total-assets observations');
 return {points,releaseDate:null};
}

function parseSnbMoney(data){
 if(!Array.isArray(data.timeseries))throw Error('SNB monetary schema changed');
 const series=['GM1','GM2','GM3'].map((code,index)=>{
  const matches=data.timeseries.filter(s=>s.metadata?.key==='EPB@SNB.snbmonagg{B,'+code+'}');
  if(matches.length!==1)throw Error('SNB monetary level key missing or ambiguous');
  const s=matches[0],label='Monetary aggregate M'+(index+1);
  if(s.metadata.frequency!=='P1M'||s.metadata.unit!=='In CHF millions / In percent'||!s.header?.some(h=>h.dim==='Level/change'&&h.dimItem==='Level')||!s.header?.some(h=>h.dim==='Monetary aggregates'&&h.dimItem===label))throw Error('SNB monetary definition or unit changed');
  const points=sortedUnique((s.values||[]).flatMap(p=>{const v=numeric(p.value),d=p.date+'-01';return /^\d{4}-\d{2}$/.test(p.date)&&day(d)&&v!==null&&v>=0?[{d,v,periodLabel:p.date}]:[];}),180);
  if(!points.length)throw Error('No SNB '+label+' observations');
  return {id:code,label,ccy:'CHF',category:'Liquidity',frequency:'Monthly',unit:'Millions CHF',yoy:true,points,note:'Published stock level; any displayed y/y is computed from exact matching months. Swiss definitions differ from other economies.'};
 });
 return {series,releaseDate:null};
}

function parseSmaExpectations(text,parseCSV){
 const rows=parseCSV(text),headers=rows.shift()||[],ix=k=>headers.indexOf(k);
 const required=['survey_prov','vintage','vintage_date','measure','series_key','item','area','frequency','horizon','units','time_stamp','category','value'];
 if(required.some(k=>ix(k)<0)||new Set(headers).size!==headers.length)throw Error('ECB SMA CSV schema changed');
 const projections=[];let vintage=null,vintageDate=null;
 for(const r of rows){
  if(r[ix('survey_prov')]!=='SMA'||r[ix('measure')]!=='MEDIAN'||r[ix('item')]!=='DFR'||r[ix('area')]!=='U2'||r[ix('units')]!=='I'||r[ix('category')]!=='_Z'||r[ix('frequency')]!=='GC')continue;
  const v=numeric(r[ix('value')]),period=r[ix('time_stamp')]?.slice(0,10),horizon=Number(r[ix('horizon')]),rowVintage=r[ix('vintage')],rowVintageDate=r[ix('vintage_date')];
  if(v===null)continue;
  if(!day(period)||!Number.isInteger(horizon)||horizon<1||!day(rowVintageDate?.slice(0,10))||r[ix('series_key')]!=='SMA.'+rowVintage+'.MEDIAN.GC.I.U2._Z.DFR')throw Error('ECB SMA policy-horizon definition changed');
  if(vintage!==null&&(vintage!==rowVintage||vintageDate!==rowVintageDate))throw Error('Mixed ECB SMA survey vintages');
  vintage=rowVintage;vintageDate=rowVintageDate;
  if(projections.some(p=>p.horizon===horizon))throw Error('Duplicate ECB SMA policy horizon');
  projections.push({period,v,horizon,referencePeriod:period,frequency:'GC',actualMeetingDate:null,kind:'survey-median'});
 }
 if(!projections.length)throw Error('No ECB SMA median deposit facility expectations');
 if(projections.length>40)throw Error('Unexpected ECB SMA horizon count');
 return {projections:projections.sort((a,b)=>a.horizon-b.horizon),vintage,vintageDate,publicationDate:null,releaseDate:null,unit:'Percent',note:'ECB monetary analyst survey median deposit facility rate. The vintage date is the survey month, not publication time; reference months are not actual meeting dates. Not an OIS path or policy commitment.'};
}

async function fetchAdditionalContext(def,remote,parseCSV,prior=null){
 const retrievedAt=new Date().toISOString();let result,source=def.source;
 if(def.kind==='boc-assets')result=parseBocAssets(await remote(source));
 else if(def.kind==='snb-money'){
  const updateSource='https://data.snb.ch/api/cube/snbmonagg/lastUpdate',update=await remote(updateSource);
  if(!/^\d{8}_\d{4}$/.test(update?.editionDate)||!/^\d{8}_\d{4}$/.test(update?.publicSinceDate))throw Error('SNB edition metadata missing or changed');
  if(prior?.id===def.id&&prior.source===source&&prior.publisherEdition===update.editionDate&&prior.publisherPublicSince===update.publicSinceDate&&prior.series?.length===3&&prior.retrievedAt){
   // Publisher requires update checks before downloading unchanged full tables.
   return {...prior,checkedAt:retrievedAt,unchanged:true};
  }
  result={...parseSnbMoney(await remote(source)),publisherEdition:update.editionDate,publisherPublicSince:update.publicSinceDate,updateSource,sourceUpdatedAt:null,publisherTimeNote:'Original publisher edition strings retained; timezone is not supplied by this endpoint.'};
 }else if(def.kind==='ecb-sma'){
  const html=await remote(source,false),today=retrievedAt.slice(2,10).replaceAll('-','');
  const paths=[...new Set(html.match(/\/stats\/ecb_surveys\/sma\/shared\/pdf\/ecb\.smar\d{6}_[a-z]+\.en\.csv/g)||[])].filter(p=>p.match(/smar(\d{6})_/)[1]<=today).sort((a,b)=>a.match(/smar(\d{6})_/)[1].localeCompare(b.match(/smar(\d{6})_/)[1]));
  if(!paths.length)throw Error('No available dated ECB SMA CSV link');
  const discoverySource=source;source='https://www.ecb.europa.eu'+paths.at(-1);
  result={...parseSmaExpectations(await remote(source,false),parseCSV),discoverySource};
 }else throw Error('Unknown additional context source');
 return {...def,...result,source,retrievedAt,checkedAt:retrievedAt};
}

