 if(eocd<0)throw Error('ALFRED did not return a ZIP archive');const count=view.getUint16(eocd+10,true);if(count<1||count>8||view.getUint16(eocd+4,true)!==0||view.getUint16(eocd+6,true)!==0)throw Error('Unsupported ALFRED ZIP layout');let offset=view.getUint32(eocd+16,true),total=0;
 for(let i=0;i<count;i++){
  if(offset+46>bytes.length||view.getUint32(offset,true)!==0x02014b50)throw Error('Invalid ALFRED ZIP directory');
  const flags=view.getUint16(offset+8,true),method=view.getUint16(offset+10,true),size=view.getUint32(offset+20,true),plain=view.getUint32(offset+24,true),n=view.getUint16(offset+28,true),extra=view.getUint16(offset+30,true),comment=view.getUint16(offset+32,true),local=view.getUint32(offset+42,true),name=decoder.decode(bytes.subarray(offset+46,offset+46+n));
  if(flags&1||![0,8].includes(method)||plain>2000000||(total+=plain)>4000000||/[\\/]/.test(name)||files[name])throw Error('Unsafe ALFRED ZIP entry');
  if(local+30>bytes.length||view.getUint32(local,true)!==0x04034b50)throw Error('Invalid ALFRED ZIP member');const start=local+30+view.getUint16(local+26,true)+view.getUint16(local+28,true);if(start+size>bytes.length)throw Error('Truncated ALFRED ZIP member');
  const compressed=bytes.slice(start,start+size),raw=method===0?compressed:new Uint8Array(await new Response(new Blob([compressed]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer());
  if(raw.length!==plain)throw Error('ALFRED ZIP size mismatch');let crc=0xffffffff;for(const b of raw){crc^=b;for(let k=0;k<8;k++)crc=(crc>>>1)^((crc&1)?0xedb88320:0);}if(((crc^0xffffffff)>>>0)!==view.getUint32(offset+16,true))throw Error('ALFRED ZIP checksum mismatch');
  files[name]=decoder.decode(raw);offset+=46+n+extra+comment;
 }return files;
