function parseVintageFiles(files,series,parseCSV,now=Date.now()){
 const readme=files['README.txt'],names=Object.keys(files).filter(n=>n.endsWith('.csv'));if(!readme?.includes('Series ID: '+series)||!readme.includes('Output Format: Observations, Initial Release Only')||names.length!==1)throw Error('ALFRED archive identity or output type changed');
 const rows=parseCSV(files[names[0]]),h=rows.shift();if(h?.join(',')!=='period_start_date,'+series+',realtime_start_date')throw Error('ALFRED initial-release columns changed');
 const unitsBlock=readme.match(/(?:^|\r?\n)Units\r?\n([\s\S]*?)(?:\r?\nFrequency\r?\n)/)?.[1]||'',unitHistory=unitsBlock.split(/\r?\n/).map(line=>line.trim().match(/^(.*?)\s{2,}(\d{4}-\d{2}-\d{2})\s+(Current|\d{4}-\d{2}-\d{2})$/)).filter(Boolean).map(m=>({unit:m[1],from:m[2],to:m[3]})),currentUnit=unitHistory.find(u=>u.to==='Current')?.unit||null;
 const today=new Date(now).toISOString().slice(0,10),points=[],seen=new Map();let missing=0;
 for(const r of rows){const[d,raw,release]=r;if(!r.some(x=>x))continue;if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||!/^\d{4}-\d{2}-\d{2}$/.test(release)||!Number.isFinite(Date.parse(d))||!Number.isFinite(Date.parse(release))||release>today||release<d)throw Error('Invalid ALFRED observation/release date');if(raw==='.'||raw===''){missing++;continue;}const v=Number(raw);if(!Number.isFinite(v))throw Error('Invalid ALFRED value');if(seen.has(d)&&seen.get(d)!==v)throw Error('Conflicting ALFRED first releases');if(!seen.has(d))points.push({d,v,initialReleaseDate:release});seen.set(d,v);}
 if(!points.length)throw Error('No ALFRED first-release observations');points.sort((a,b)=>a.d.localeCompare(b.d));for(const p of points)p.originalUnit=unitHistory.find(u=>u.from<=p.initialReleaseDate&&(u.to==='Current'||u.to>=p.initialReleaseDate))?.unit||null;
 const field=name=>readme.match(new RegExp('(?:^|\\r?\\n)'+name+'\\r?\\n([^\\r\\n]+)'))?.[1]?.split(/\s{2,}/)[0]?.trim()||null;
 return{points,missing,unit:currentUnit||'Original published units',unitHistory,publishedFrequency:field('Frequency'),seasonalAdjustment:field('Seasonal Adjustment'),agency:field('Source'),firstObservation:points[0].d,lastObservation:points.at(-1).d,vintageVerified:true,releaseDate:null};
}
async function fetchVintage(def,remote,parseCSV,prior=null){
 const checkedAt=new Date().toISOString(),form=vintageForm(await remote(def.source,false));
 if(prior?.series===def.series&&prior.latestVintage===form.latestVintage&&prior.archiveSchema==='ALFRED-INITIAL-1'&&prior.points?.length&&prior.source===def.source)return{...prior,checkedAt,unchanged:true};
 const body=new URLSearchParams({'form[units]':'lin','form[obs_start_date]':'2015-01-01','form[obs_end_date]':form.end,'form[entered_vintage_dates]':'','form[file_type]':'4','form[file_format]':'csv','form[download_data]':'Download data'});form.dates.forEach(d=>body.append('form[selected_vintage_dates][]',d));
 let bytes;for(let attempt=0;attempt<2;attempt++){try{const r=await fetch(def.source,{method:'POST',body,headers:{'User-Agent':'MacroICEObservatory/1.0 (personal research)'},redirect:'error',signal:AbortSignal.timeout(45000)});if(!r.ok)throw Error('ALFRED download HTTP '+r.status);bytes=new Uint8Array(await r.arrayBuffer());break;}catch(e){if(attempt)throw Error('ALFRED public download failed after retry');}}
 const parsed=parseVintageFiles(await vintageUnzip(bytes),def.series,parseCSV);return{...def,...parsed,archiveSchema:'ALFRED-INITIAL-1',latestVintage:form.latestVintage,selectedVintageCount:form.dates.length,retrievedAt:new Date().toISOString(),checkedAt};
}
function buildVintageView(bundle){return VINTAGE_FEEDS.map(def=>{const f=bundle.feeds[def.id],latest=bundle.feeds[def.latestFeed],status=bundle.status[def.id];return{...def,unit:f?.unit||def.unit,seasonalAdjustment:f?.seasonalAdjustment||null,agency:f?.agency||null,connected:!!f,retrievedAt:f?.retrievedAt||null,checkedAt:f?.checkedAt||null,latestVintage:f?.latestVintage||null,retained:status?.ok===false,status:status||null,missing:f?.missing??null,count:f?.points?.length||0,observations:(f?.points||[]).slice(-180).map(p=>{const revised=latest?.points?.find(q=>q.d===p.d),comparable=!!p.originalUnit&&p.originalUnit===f.unit;return{...p,latestValue:comparable?revised?.v??null:null,revision:revised&&comparable?revised.v-p.v:null,comparisonStatus:comparable?'Same published units':'Vintage units differ or are unverified; comparison withheld',latestRetrievedAt:latest?.retrievedAt||null};})};});}

