 for(const def of NEWS_FEEDS){const feed=feeds[def.id],health=statuses.find(s=>s.id===def.id);for(const n of feed?.news||[]){
  const url=newsCanonical(n.url,def.hosts),title=newsPlainText(n.title),published=Date.parse(n.publishedAt);if(!url||!title||!Number.isFinite(published)||published>now)continue;
  const topics=newsTopics(title);if(!topics.length||!newsMarketRelevant(title))continue;
  const titleKey=title.toLocaleLowerCase('en').replace(/[^\p{L}\p{N}]+/gu,' ').trim(),key=titleKey.length>25?titleKey:null;
  const existing=urlIndex.get(url)||(key?titleIndex.get(key):null),evidence={publisher:def.name,feedId:def.id,url,publishedAt:n.publishedAt,originalPublishedAt:n.originalPublishedAt||null,retrievedAt:feed.retrievedAt||null,retained:health.retained,ageHours:health.ageHours};
  if(existing){if(!existing.evidence.some(e=>e.feedId===def.id&&e.url===url))existing.evidence.push(evidence);for(const topic of topics)if(!existing.topics.includes(topic))existing.topics.push(topic);urlIndex.set(url,existing);if(key)titleIndex.set(key,existing);continue;}
  const story={title,url,publishedAt:n.publishedAt,topics,evidence:[evidence],interpretation:'Deterministic headline keyword relevance only; impact, direction and corroboration unvalidated'};stories.push(story);urlIndex.set(url,story);if(key)titleIndex.set(key,story);
 }}
