 if(!charts.length||charts.length>12)throw Error('Publisher chart images unavailable');return{dataAsOf,charts,attribution:'Central Bank Watch',numericIngestion:false,framingStatus:'Publisher currently sends X-Frame-Options: DENY; use attributed image previews or open source.'};
