 return [...xml.matchAll(/<row\b[^>]*>([\s\S]*?)<\/row>/g)].map(row=>{const out=[];for(const c of row[1].matchAll(/<c\b([^>]*?)(?:\/>|>([\s\S]*?)<\/c>)/g)){const ref=c[1].match(/\br="([A-Z]+)\d+"/)?.[1];if(!ref)continue;let col=0;for(const char of ref)col=col*26+char.charCodeAt(0)-64;const type=c[1].match(/\bt="([^"]+)"/)?.[1],raw=c[2]?.match(/<v\b[^>]*>([\s\S]*?)<\/v>/)?.[1];out[col-1]=type==='s'?shared[Number(raw)]:type==='inlineStr'?[...(c[2]||'').matchAll(/<t\b[^>]*>([\s\S]*?)<\/t>/g)].map(m=>accessibleXML(m[1])).join(''):raw===undefined?'':Number.isFinite(Number(raw))?Number(raw):accessibleXML(raw);}return out;});
