 const index=rows.findIndex(r=>r.some(c=>/^date$/i.test(String(c).trim()))&&r.some(c=>/^(nav|net asset value)$/i.test(String(c).trim())));if(index<0)throw Error('Issuer NAV header changed');
 const h=rows[index],di=h.findIndex(c=>/^date$/i.test(String(c).trim())),ni=h.findIndex(c=>/^(nav|net asset value)$/i.test(String(c).trim())),points=new Map(),today=new Date(now).toISOString().slice(0,10);
