function parseImfOutlook(data,def,catalog){
 const meta=data.indicators?.[def.code],values=data.values?.[def.code],projectionYear=Number(meta?.['projection-year']),edition=meta?.source;
 if(meta?.dataset!=='WEO'||meta?.unit!=='Percent of GDP'||!/^World Economic Outlook \((April|October) 20\d{2}\)$/.test(edition||'')||!Number.isInteger(projectionYear)||!values||!/net lending.*borrowing/i.test(meta.label||''))throw Error('IMF fiscal schema or edition missing');
 const byCurrency={};for(const e of catalog){const country=values[e.iso];if(!country)continue;const points=Object.entries(country).flatMap(([year,value])=>/^\d{4}$/.test(year)&&Number(year)>=projectionYear-5&&Number(year)<=projectionYear+5&&typeof value==='number'&&Number.isFinite(value)?[{d:year+'-01-01',v:value,period:year,classification:Number(year)>=projectionYear?'IMF estimate/projection':'Historical; may include IMF staff estimates'}]:[]).sort((a,b)=>a.d.localeCompare(b.d));if(points.length)byCurrency[e.ccy]=points;}
 if(!Object.keys(byCurrency).length)throw Error('No mapped IMF fiscal observations');return {byCurrency,missingEconomies:catalog.filter(e=>!byCurrency[e.ccy]).map(e=>e.ccy),edition,projectionYear,sourceUpdatedAt:meta['last-modified']||null,referenceScope:'General government; country reporting conventions vary',attribution:'Source: International Monetary Fund, World Economic Outlook. https://data.imf.org/Datasets/WEO',classificationNote:'Projection-year is publisher metadata, not a country-specific final-actual cutoff. Earlier years may contain staff estimates.'};
}
async function fetchAccessibleFeed(def,prior,catalog,now=Date.now()){
 if(prior?.source===def.source&&now-Date.parse(prior.retrievedAt)<12*3600000&&now>=Date.parse(prior.retrievedAt))return {...prior,unchanged:true,checkedAt:new Date(now).toISOString()};
 const response=await fetch(def.source,{redirect:'error',signal:AbortSignal.timeout(45000)});if(!response.ok)throw Error('Public source HTTP '+response.status);let result;
 if(def.kind==='issuer-nav'){const bytes=await response.arrayBuffer();result=parseIssuerNav(await issuerXlsxRows(bytes),def,now);}else result=parseImfOutlook(await response.json(),def,catalog);
 return {...def,...result,retrievedAt:new Date(now).toISOString(),checkedAt:new Date(now).toISOString(),unchanged:false};
}

function validateAccessibleImported(f,def,capturedAt){
 if(f.source!==def.source||f.frequency!==def.frequency||f.unit!==def.unit)throw Error('Accessible source identity changed');
 if(def.kind==='issuer-nav'){
  if(f.ticker!==def.ticker||!Array.isArray(f.points)||f.points.length<60||f.points.some(p=>p.d>capturedAt.slice(0,10)||p.v<=0))throw Error('Invalid issuer NAV observations');
 }else{
  if(!/^World Economic Outlook \((April|October) 20\d{2}\)$/.test(f.edition||'')||!Number.isInteger(f.projectionYear)||!f.byCurrency)throw Error('Invalid IMF outlook metadata');
  for(const points of Object.values(f.byCurrency))for(const p of points){
   const expected=Number(p.period)>=f.projectionYear?'IMF estimate/projection':'Historical; may include IMF staff estimates';
   if(p.period!==p.d.slice(0,4)||Number(p.period)>f.projectionYear+5||Number(p.period)<f.projectionYear-5||p.classification!==expected)throw Error('Invalid IMF fiscal classification');
  }
 }
}

