 if(names.some(n=>!h.includes(n)))throw Error('Fed fitted curve identity changed');const series=names.map(name=>({id:'FED_'+name,name,ccy:'USD',curve:name.startsWith('TIPS')?'Fitted TIPS real zero coupon':name.startsWith('BKEVEN')?'Inflation compensation':name.startsWith('SVENF')?'Fitted nominal instantaneous forward':'Fitted nominal zero coupon',maturity:name.endsWith('5F05')?'5Y5Y':Number(name.slice(-2))+'Y',points:[]}));
 for(const line of lines){if(!/^\d{4}-\d{2}-\d{2},/.test(line))continue;const row=line.trim().split(','),d=row[0];if(d>today||!Number.isFinite(Date.parse(d))||new Date(d).toISOString().slice(0,10)!==d)continue;for(let i=0;i<names.length;i++){const raw=row[h.indexOf(names[i])],v=Number(raw);if(raw&&raw!=='NA'&&Number.isFinite(v)&&v>=-30&&v<=100)series[i].points.push({d,v});}}
