function officialQuarterDate(period){
 const match=/^(\d{4})-Q([1-4])$/.exec(period);
 return match?match[1]+'-'+['01','04','07','10'][Number(match[2])-1]+'-01':null;
}
function officialQuarterPeriod(date){
 const match=/^(\d{4})-(01|04|07|10)-01$/.exec(date);
 return match?match[1]+'-Q'+(['01','04','07','10'].indexOf(match[2])+1):null;
}
function officialQuarterIndex(d){
 return Number(d.slice(0,4))*4+(Number(d.slice(5,7))-1)/3;
}
function officialRows(csv,parse,columns){
 const [header,...rows]=parse(csv);
 if(!header||new Set(header).size!==header.length||columns.some(key=>!header.includes(key)))throw Error('Unexpected official CSV schema');
 if(rows.some(row=>row.length!==header.length))throw Error('Malformed official CSV row');
 return rows.map(row=>Object.fromEntries(header.map((key,i)=>[key,row[i]])));
}
function officialNumber(raw){
 if(!/^-?\d+(?:\.\d+)?(?:e[+-]?\d+)?$/i.test(raw)||!Number.isFinite(Number(raw)))throw Error('Invalid official observation');
 return Number(raw);
}
function parseOfficialMacro(def,csv,parse,metadata){
 if(def.id==='fso_nominal_gdp'){
  const points=officialRows(csv,parse,['PERIOD','VARIABLE','VALUE','STATUS','UNIT_MEAS'])
   .filter(r=>r.VARIABLE==='B1GQ'&&r.UNIT_MEAS==='MCHF'&&r.PERIOD>='1995')
   .map(r=>({d:r.PERIOD+'-01-01',period:r.PERIOD,v:officialNumber(r.VALUE),status:r.STATUS}))
   .sort((a,b)=>a.d.localeCompare(b.d));
  return {byCurrency:{CHF:points},sourceUpdatedAt:def.releaseDate+'T00:00:00Z',edition:'36813569'};
 }
 if(def.id==='seco_real_gdp'){
  if(metadata?.source_name?.en!=='State Secretariat for Economic Affairs (SECO)'||metadata?.labels?.structure?.gdp?.en!=='Gross domestic product at market prices, B1GQ'||metadata?.labels?.seas_adj?.csa?.en!=='Seasonally and calendar adjusted'||!/^Swiss Francs, chain-linked volumes, reference year \d{4}$/.test(metadata?.units?.type?.real?.en||'')||!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(metadata?.updated_utc||''))throw Error('SECO metadata or series definition changed');
  const levels=officialRows(csv,parse,['structure','type','seas_adj','date','value'])
   .filter(r=>r.structure==='gdp'&&r.type==='real'&&r.seas_adj==='csa')
   .map(r=>({d:r.date,v:officialNumber(r.value)})).sort((a,b)=>a.d.localeCompare(b.d));
  if(levels.some((p,i)=>!officialQuarterPeriod(p.d)||p.v<=0||(i&&officialQuarterIndex(p.d)-officialQuarterIndex(levels[i-1].d)!==1)))throw Error('Invalid or duplicate SECO level period');
  const points=levels.slice(1).map((p,i)=>({d:p.d,period:officialQuarterPeriod(p.d),v:100*(p.v/levels[i].v-1),status:null}));
  return {byCurrency:{CHF:points},sourceUpdatedAt:metadata.updated_utc.replace(' ','T')+'Z',metadataSource:secoMetadata};
 }
 const dimensions={DATAFLOW:oecdFlow+'(1.1)',FREQ:'Q',ADJUSTMENT:'Y',SECTOR:'S1',COUNTERPART_SECTOR:'S1',TRANSACTION:'B1GQ',INSTR_ASSET:'_Z',ACTIVITY:'_Z',EXPENDITURE:'_Z',UNIT_MEASURE:'PC',PRICE_BASE:'L',TRANSFORMATION:'G1',TABLE_IDENTIFIER:'T0102',UNIT_MULT:'0',CURRENCY:'_Z',CONF_STATUS:'F'};
 const byCurrency={};
 for(const row of (Array.isArray(csv)?csv:officialRows(csv,parse,[...Object.keys(dimensions),'REF_AREA','TIME_PERIOD','OBS_VALUE','OBS_STATUS']))){
  const ccy=oecdArea[row.REF_AREA],d=officialQuarterDate(row.TIME_PERIOD);
  if(!ccy||!d||Object.entries(dimensions).some(([key,value])=>row[key]!==value)||!['A','P','E'].includes(row.OBS_STATUS))throw Error('Unexpected OECD GDP dimensions or status');
  (byCurrency[ccy]??=[]).push({d,period:row.TIME_PERIOD,v:officialNumber(row.OBS_VALUE),status:row.OBS_STATUS});
 }
 for(const points of Object.values(byCurrency))points.sort((a,b)=>a.d.localeCompare(b.d));
 return {byCurrency,sourceUpdatedAt:null,edition:oecdFlow+'(1.1)'};
}

