function icePair(a,b,model){const delta=a?.score!==null&&b?.score!==null&&a?.score!==undefined&&b?.score!==undefined?a.score-b.score:null;const critical=!!a?.critical&&!!b?.critical;const ratings=[a?.confidenceBreakdown?.robustness,b?.confidenceBreakdown?.robustness];const evidenceRobustness=ratings.every(Boolean)?ratings.includes('Low')?'Low':ratings.includes('Medium')?'Medium':'High':null;return{base:a?.ccy,quote:b?.ccy,delta,bias:critical?iceBias(delta,model.pairThreshold):'Insufficient timely data',confidence:Math.min(a?.confidence??0,b?.confidence??0),evidenceRobustness,coverage:Math.min(a?.coverage??0,b?.coverage??0),critical,horizon:model.horizon,drivers:[...(a?.drivers||[]).slice(0,2).map(d=>a.ccy+': '+d.name+' '+Math.round(d.score)),...(b?.drivers||[]).slice(0,2).map(d=>b.ccy+': '+d.name+' '+Math.round(d.score))],invalidation:'Research bias changes when the differential crosses ±'+model.pairThreshold+' or critical data becomes stale.',executionReady:false};}

// Existing feeds only. National aggregates and offshore credit are explicitly marked when used as substitutes.
const ICE_LIQUIDITY_FEEDS=['M2SL','WALCL','BOGMBASE','boe_m4','boj_monetary_base','snb_money','boc_money','ecb_m3','ecb_assets','rba_money','rba_assets','bis_usd_credit'];
const ICE_LIQUIDITY_INPUTS={
 USD:[['M2SL',null,'Monthly'],['WALCL',null,'Weekly'],['BOGMBASE',null,'Monthly'],['bis_usd_credit',null,'Quarterly','Offshore credit','USD credit to non-bank borrowers outside the United States measures offshore USD liquidity.']],
 EUR:[['ecb_m3',null,'Monthly','Broad money substitute','Euro-area M3 has a broader definition than M2.'],['ecb_assets',null,'Weekly']],
 GBP:[['boe_m4',null,'Monthly','Broad money substitute','UK M4 is the national broad money aggregate.']],
 JPY:[null,null,['boj_monetary_base',null,'Monthly']],
 CAD:[['boc_money',null,'Monthly','Broad money substitute','Canadian M2++ includes non-money-market mutual funds.']],
 CHF:[['snb_money','GM2','Monthly']],
 AUD:[['rba_money','DMABMS','Monthly','Broad money substitute','Australian broad money is used as the available national money aggregate.'],['rba_assets','ARBAATAW','Weekly'],['rba_money','DMAMMB','Monthly']]
};
const ICE_LIQUIDITY_LABELS=['M2 growth','Central bank balance sheet growth','Monetary base growth','Credit growth'];
const ICE_RISK_EXPOSURE={USD:.35,EUR:0,GBP:-.25,JPY:1,CHF:1,CAD:-.5,AUD:-1,NZD:-1};

function iceProxy(type,reason){return {type,reason,confidenceImpact:'Counts toward proxy-dependent evidence weight; reduces composite confidence.'};}
function iceManufacturing(bundle,ccy,now){
 const d=bundle.feeds?.manufacturing?.byCurrency?.[ccy]||{},DAY=86400000,p=d.pmi,o=d.output;
 let ps=null,po=null;
 if(p&&Number.isFinite(p.value)&&p.value>=20&&p.value<=80){
  const rel=Date.parse(p.releaseUtc||''),nxt=Date.parse(p.nextReleaseUtc||''),known=Number.isFinite(rel);
  const fresh=known?(now-rel)/DAY<=45&&(now-rel)/DAY>=-1:Number.isFinite(nxt)&&(nxt-now)/DAY<=35&&(nxt-now)/DAY>=-1;
  if(fresh){const at=new Date(known?rel:nxt-30*DAY);ps=50+4*(p.value-50);po={d:new Date(Date.UTC(at.getUTCFullYear(),at.getUTCMonth()-1,1)).toISOString().slice(0,10),v:p.value};}
 }
 let os=null,oo=null;
 if(o&&Number.isFinite(o.z)&&/^\d{4}-\d{2}$/.test(o.period||'')&&!o.discontinued){
  const age=(now-Date.parse(o.period+'-28T00:00:00Z'))/DAY;
  if(age>=-31&&age<=(o.maxAge||90)){os=50+8*Math.max(-3,Math.min(3,o.z))+(o.trend==='rising'?4:o.trend==='falling'?-4:0);oo={d:o.period+'-01',v:o.z};}
 }
 return iceFactor([
  iceFeature('Manufacturing survey PMI',ps,60,po,'Score = 50 + 4 x (PMI - 50), limited to 0-100; 50 means no change. Only national manufacturing PMIs released within 45 days, or the previous value shown on a release due within 35 days, are used. Ai Group (AUD) is on a different scale and is excluded.','MT5 economic calendar (stored copy)',{frequency:'Monthly',maxLag:60}),
  iceFeature('Manufacturing output momentum',os,40,oo,'Score = 50 + 8 x monthly-change z-score (limited to +/-3) +/-4 for a rising or falling 3-month trend. Only while the official reading is inside its freshness limit; discontinued series are not scored.','Official manufacturing output (stored copy)',{frequency:'Monthly',maxLag:(o&&o.maxAge||90)+3})
 ]);
}
function iceLiquidity(bundle,ccy,now,weight=10,nzdBalanceSheet){
 const features=ICE_LIQUIDITY_LABELS.map((name,i)=>{
  if(ccy==='NZD'&&i===1&&nzdBalanceSheet){
   const {status,last_obs:d,yoy_local_pct:v,source}=nzdBalanceSheet;
   const maxLag=100,age=(now-Date.parse(d))/86400000;
   const observation=Number.isFinite(v)&&Number.isFinite(age)?{d,v}:null;
   const fresh=status==='OK'&&observation!==null&&age>=0&&age<=maxLag;
   return iceFeature(name,fresh?50+2*v:null,25,observation,'50 + 2 × year-over-year stock growth (%), bounded to 0–100. Expansion scores higher.',source,
    {yoy:fresh?v:null,fresh,frequency:'Monthly',maxLag,proxy:null});
  }
  const [id,seriesId,frequency,type,reason]=ICE_LIQUIDITY_INPUTS[ccy]?.[i]||[];
  const feed=bundle.feeds[id],points=(seriesId?feed?.series?.find(s=>s.id===seriesId)?.points:feed?.points)||[];
  const latest=points.at(-1),maxLag={Monthly:95,Weekly:20,Quarterly:180}[frequency];
  const fresh=iceFresh(latest,frequency,maxLag,now)&&bundle.status?.[id]?.ok!==false;
  const prior=latest&&points.find(p=>frequency==='Weekly'
   ? Math.abs(Date.parse(latest.d)-Date.parse(p.d)-364*86400000)<=3*86400000
   : p.d.slice(0,7)===(Number(latest.d.slice(0,4))-1)+latest.d.slice(4,7));
  const yoy=fresh&&latest.v>0&&prior?.v>0?100*(latest.v/prior.v-1):null;
  return iceFeature(name,yoy===null?null:50+yoy*2,25,latest,'50 + 2 × year-over-year stock growth (%), bounded to 0–100. Expansion scores higher.',feed?.source,
   {yoy,fresh,frequency,maxLag,proxy:type?iceProxy(type,reason):null});
 });
 const factor=iceFactor(features),scored=features.filter(f=>Number.isFinite(f.score));
 const freshness=25*features.filter(f=>f.fresh).length;
 const proxyDependence=scored.length?100*scored.filter(f=>f.proxy).length/scored.length:null;
 return {...factor,freshness,confidence:proxyDependence===null?0:Math.round((factor.coverage+freshness+100-proxyDependence)/3),
  contribution:factor.score===null?null:(factor.score-50)*weight*factor.coverage/10000};
}

function iceProxyFor(feature,ccy){
 if(typeof feature.proxy==='object'&&feature.proxy)return feature.proxy;
 const name=feature.name;
 if(name==='Positioning momentum'&&ccy==='USD')return iceProxy('Synthetic positioning','USD momentum uses the inverse average of seven foreign currency futures positions.');
 if(name==='Ex-post policy minus CPI proxy')return iceProxy('Backward-looking real rate','Observed policy rate less reported CPI approximates purchasing-power carry.');
 if(name==='Monthly 10Y yield change'&&ccy==='EUR')return iceProxy('Country substitute','Germany’s sovereign yield is used for EUR.');
 if(feature.proxy)return iceProxy(name,typeof feature.proxy==='string'?feature.proxy:feature.rule);
 return null;
}
function iceConfidence(e,model,check,now){
 let available=0,fresh=0,proxyWeight=0;
 const proxies=[];
 for(const [id,factor] of Object.entries(e.factors)){
  const total=factor.features.reduce((n,f)=>n+f.weight,0);
  for(const feature of factor.features){
   const proxy=iceProxyFor(feature,e.ccy);
   const scored=Number.isFinite(feature.score),weight=model.weights[id]*feature.weight/total;
   if(proxy)proxies.push({...proxy,input:feature.name,used:scored,weight:scored?weight:0});
   if(!scored)continue;
   available+=weight;
   if(proxy)proxyWeight+=weight;
   const date=feature.observation?.d,frequency=feature.frequency||
    (id==='growth'?'Quarterly':id==='inflation'||id==='labour'||feature.name==='Monthly 10Y yield change'?'Monthly':
    id==='external'&&!proxy?'Annual':id==='positioning'?'Weekly':'Daily');
   const limit=feature.maxLag||({Daily:12,Monthly:95,Quarterly:150,Weekly:14,Annual:730}[frequency]);
   const age=(now-Date.parse(icePeriodEnd(date,frequency)))/86400000;
   if(Number.isFinite(age)&&age>=-1&&age<=limit)fresh+=weight;
  }
 }
 const coverage=iceClip(e.coverage),freshness=available?100*fresh/available:0;
 const proxyDependence=available?100*proxyWeight/available:0;
 const validation=check?.blocked?0:check?.independentlyChecked&&check.selected?100:null;
 const composite=Math.round(.35*coverage+.3*freshness+.2*(available?100-proxyDependence:0)+.15*(validation??0));
 const robustness=coverage>=90&&freshness>=90&&proxyDependence<=15?'High':coverage>=75?'Medium':'Low';
 return {coverage,freshness,proxyDependence,validation,composite,robustness,proxies};
}
function iceMedian(values){
 const sorted=values.filter(Number.isFinite).sort((a,b)=>a-b),mid=Math.floor(sorted.length/2);
 return !sorted.length?null:sorted.length%2?sorted[mid]:(sorted[mid-1]+sorted[mid])/2;
}
function iceGlobalRegime(analysis){
 const e=analysis.economies,features=(id,index)=>e.map(row=>row.factors[id].features[index]);
 const median=items=>iceMedian(items.map(f=>Number.isFinite(f?.score)?f.change??f.observation?.v:null));
 const growth=median(features('growth',0)),inflation=median(features('inflation',0)),policy=median(features('rates',1));
 const growthChange=iceMedian(features('growth',1).filter(f=>Number.isFinite(f?.score)).map(f=>f.change));
 const risk=analysis.regime.riskPressure;
 const axes={
  risk:!Number.isFinite(risk)?null:risk<=-3?'Risk On':risk>=3?'Risk Off':'Neutral',
  growth:growth===null?null:growth<=0?'Contraction':growthChange===null?null:growthChange<-.1?'Slowdown':'Expansion',
  inflation:inflation===null?null:inflation<-.2?'Disinflation':inflation>.2?'Inflationary':'Stable',
  policy:policy===null?null:policy<0?'Easing':policy>0?'Tightening':'Neutral'
 };
 const breadth=['growth','inflation','rates'].reduce((sum,id)=>sum+features(id,id==='rates'?1:0).filter(f=>Number.isFinite(f?.score)).length,0);
 return {...axes,label:Object.values(axes).map(v=>v||'Unavailable').join(' | '),
  confidence:Math.round(25*(Number.isFinite(risk)?1:0)+75*breadth/(3*Math.max(1,e.length))),riskPressure:risk,
  proxies:[iceProxy('Market risk proxy','Changes in equity prices and VIX proxy global risk appetite.') ]};
}
function iceOpportunities(analysis){
 const byCurrency=new Map(analysis.economies.map(e=>[e.ccy,e]));
 const diff=(a,b)=>Number.isFinite(a)&&Number.isFinite(b)?a-b:null;
 const ranked=analysis.pairs.flatMap(pair=>{
  if(!Number.isFinite(pair.delta))return [];
  const a=byCurrency.get(pair.base),b=byCurrency.get(pair.quote),risk=analysis.globalRegime.riskPressure;
  const positioning=e=>{
   const f=e.factors.positioning;
   return Number.isFinite(f.score)?f.score*f.coverage/100+(1-f.coverage/100)*50:null;
  };
  const components={
   'Strength differential':pair.delta,
   'Regime alignment':Number.isFinite(risk)?risk*(ICE_RISK_EXPOSURE[a.ccy]-ICE_RISK_EXPOSURE[b.ccy]):null,
   'Liquidity differential':diff(a.factors.liquidity?.contribution,b.factors.liquidity?.contribution),
   'Positioning differential':diff(positioning(a),positioning(b))
  };
  const observed=Object.entries(components).filter(([,v])=>Number.isFinite(v));
  return [{base:a.ccy,quote:b.ccy,score:observed.reduce((sum,[,v])=>sum+v,0),
   confidence:Math.round(Math.min(a.confidence,b.confidence)*observed.length/4*(pair.critical?1:.5)),
   robustness:pair.evidenceRobustness,
   drivers:observed.sort((x,y)=>Math.abs(y[1])-Math.abs(x[1])).slice(0,3).map(([name,value])=>({name,value})),
   missing:[...Object.keys(components).filter(k=>components[k]===null),...(!pair.critical?['Mandatory releases']:[])]}];
 }).sort((a,b)=>b.score-a.score||a.base.localeCompare(b.base)||a.quote.localeCompare(b.quote));
 return {top:ranked.slice(0,10),bottom:ranked.slice(Math.max(10,ranked.length-10)),eligible:ranked.length};
}

