function labReleaseNumber(value){const match=String(value??'').trim().match(/^([+-]?(?:\d+(?:,\d{3})*(?:\.\d+)?|\.\d+))\s*(%|K|M|B)?$/i);if(!match)return null;const suffix=(match[2]||'').toUpperCase();return {value:Number(match[1].replaceAll(',',''))*({K:1e3,M:1e6,B:1e9}[suffix]||1),unit:suffix==='%'?'percent':suffix?'count':'number',original:String(value)};}
