 if(feed&&Number.isFinite(Date.parse(feed.retrievedAt))&&Date.parse(feed.retrievedAt)<=now){for(const e of (feed.events||[]).slice(0,150)){const eventTime=Date.parse(e.date);if(!Number.isFinite(eventTime)||eventTime<=now||Date.parse(feed.retrievedAt)>=eventTime||!labReleaseNumber(e.forecast))continue;const title=String(e.title).slice(0,200),country=String(e.country).slice(0,20),eventId=await labHash(country+'|'+title+'|'+new Date(eventTime).toISOString()),pointer='validation/lab/calendar-latest/'+eventId+'.json',previous=await iceRead(env.BUCKET,pointer);if(previous?.forecast===String(e.forecast))continue;
 const snapshot={eventId,title,country,eventAt:new Date(eventTime).toISOString(),forecast:String(e.forecast),previous:e.previous??null,recordedAt:stamp,sourceRetrievedAt:feed.retrievedAt,source:feed.source||null,sourceType:'Third-party calendar consensus captured before scheduled event; not a central-bank projection'},snapshotId=eventId+'-'+await labHash(stamp+'|'+snapshot.forecast);snapshot.id=snapshotId;
 await labPutOnce(env.BUCKET,'validation/lab/consensus/'+snapshotId+'.json',snapshot);await env.BUCKET.put(pointer,JSON.stringify(snapshot));archived++;}}
