 const releases=[...events.values()].sort((a,b)=>b.eventAt.localeCompare(a.eventAt)).slice(0,100).map(e=>{const actual=active.find(a=>a.eventId===e.eventId),prior=active.filter(a=>a.country===e.country&&a.title===e.title&&a.unit===actual?.unit&&a.eventAt<e.eventAt&&a.recordedAt<e.eventAt);let standardised=null;if(actual&&prior.length>=12){const vals=prior.map(p=>p.surprise),mean=vals.reduce((a,b)=>a+b,0)/vals.length,sd=Math.sqrt(vals.reduce((a,b)=>a+(b-mean)**2,0)/(vals.length-1));if(sd>0)standardised=actual.surprise/sd;}return {...e,actual:actual||null,standardisedSurprise:standardised,priorKnownErrors:prior.length,status:actual?'User-attested actual; independent value verification pending':Date.parse(e.eventAt)>Date.now()?'Pre-release consensus archived':'Actual missing; surprise withheld'};});
 const evaluation=labEvaluate(forecasts.rows,record?.bundle?.feeds?.fx?.history||[],FP,Date.now(),locked.rows.flatMap(g=>g.rows));evaluation.signalComparisons=labSignalComparisons(evaluation.outcomesForArchive,forecasts.rows);evaluation.maturity=labMaturity(evaluation,forecasts.rows);delete evaluation.outcomesForArchive;
 const latestArchivedForecastAt=forecasts.rows.map(row=>row.forecastAt).filter(Boolean).sort().at(-1)||null;
 const firstArchivedForecastAt=forecasts.rows.map(row=>row.forecastAt).filter(Boolean).sort()[0]||null;
 return {rulesVersion:MODEL.version,archive:arch,readOnly:arch,firstArchivedForecastAt,versions:[{id:ICE_MODEL.version,label:ICE_MODEL.version+' (active)',archive:false},{id:'ICE-RULES-1.3',label:'ICE-RULES-1.3 (archive, read-only)',archive:true}],retrospectiveNote:arch?'Archive of the original rules. Nothing here is rewritten, and its figures are never combined with ICE-RULES-1.4.':'Figures cover only forecasts recorded under ICE-RULES-1.4. Any 1.4 result computed for dates before it began recording is a retrospective replay, not a prospective forecast.',latestArchivedForecastAt,checkedAt:new Date().toISOString(),ruleFingerprint:FP,modelVersion:MODEL.version,protocol:LAB_PROTOCOL,ruleArchiveAvailable:!!await env.BUCKET.get('validation/lab/rules/'+FP+'.json'),captureStatus:status?.ruleFingerprint===FP?status:null,savedRunId:record?.runId||null,capturedAt:record?.analysis?.capturedAt||null,sensitivity:arch?null:labSensitivity(record?.analysis,MODEL),evaluation,releases,truncated:{forecasts:forecasts.truncated,consensus:consensus.truncated,actuals:actuals.truncated,outcomes:locked.truncated},boundaries:['Overnight fixings describe realised funding. Publisher policy charts remain separate from numerical forward expectations.','Full global numerical OIS/STIR curves and complete historical consensus remain unconnected. Trial/sandbox feeds are not treated as permanent data.','Automated collection archives available pre-release forecasts. No actual or surprise is invented; actual entry requires official-source provenance and explicit metric confirmation.','Release surprise values are user-attested until independently verified. Standardised surprises require at least 12 prior same-metric errors recorded before that event. They never alter ICE scores.']};
