 const fail=m=>{throw Object.assign(Error(m),{status:400});},text=(v,min,max,name)=>{if(typeof v!=='string'||v.trim().length<min||v.length>max)fail('Provide '+name+' ('+min+'–'+max+' characters).');return v.trim();};
