async function reviewApi(request,env){
 const url=new URL(request.url),respond=(d,status=200)=>Response.json(d,{status,headers:{'Cache-Control':'no-store'}});
 try{
  const latest=await iceRead(env.BUCKET,'ice/latest.json');if(!latest)return respond({error:'No saved baseline'},404);
  if(request.method==='GET'&&url.pathname==='/api/ice/review'){
   const run=url.searchParams.get('run');if(run&&!/^\d{13}$/.test(run))return respond({error:'Invalid run ID'},400);
   const record=run&&run!==latest.runId?await iceRead(env.BUCKET,'ice/runs/'+run+'.json'):latest;if(!record)return respond({error:'Saved run not found'},404);
   const events=await labObjects(env.BUCKET,'review/v1/events/',1000);
   const report=reviewBuild(record,events.rows);
   const verified=policyVerificationFor(await withLatestPolicyVerification(env,record),Date.now());
   const checks=report.inputValidation.checks.map(check=>{
    const value=verified[check.ccy];
    return value&&value.value===check.selected?.v&&value.observationDate===check.selected?.d?{...check,...value}:check;
   });
   return respond({...report,inputValidation:{...report.inputValidation,checks},archiveTruncated:events.truncated});
  }
  if(request.method!=='POST')return respond({error:'Use POST for analyst records'},405);
  if(request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return respond({error:'Cross-origin write rejected'},403);
  if(!request.headers.get('content-type')?.startsWith('application/json'))return respond({error:'Use JSON'},415);
  const body=await request.text();if(body.length>15000)return respond({error:'Record too large'},413);let input;try{input=JSON.parse(body);}catch{return respond({error:'Invalid JSON'},400);}
  const id=crypto.randomUUID(),now=new Date().toISOString();let event;
  if(url.pathname==='/api/ice/review/overrides')event={...reviewValidateOverride(input,latest),kind:'override',id};
  else if(url.pathname==='/api/ice/review/invalidate'){
   if(typeof input.id!=='string'||!/^[a-f0-9-]{36}$/.test(input.id))return respond({error:'Invalid record ID'},400);
   const original=await iceRead(env.BUCKET,'review/v1/by-id/'+input.id+'.json');if(original?.kind!=='override')return respond({error:'Analyst record not found'},404);
   if(typeof input.reason!=='string'||input.reason.trim().length<10||input.reason.length>2000)return respond({error:'Provide an invalidation reason (10–2000 characters)'},400);
   event={id,kind:'revoke',targetId:input.id,reason:input.reason.trim(),createdAt:now};
  }else return respond({error:'Unknown analyst route'},404);
  // Append-only ledger; never write to ice/latest or ice/runs.
  await env.BUCKET.put('review/v1/by-id/'+id+'.json',JSON.stringify(event));
  await env.BUCKET.put('review/v1/events/'+String(9999999999999-Date.parse(now))+'-'+id+'.json',JSON.stringify(event));return respond({record:event},201);
 }catch(e){return respond({error:e.status?e.message:'Could not read or save the analyst review'},e.status||502);}
}

