const XA_PROTOCOL={version:'XA-PROSPECTIVE-1.0',holdingObservations:20,roundTripCostScenariosBps:[0,5,10,25],benchmark:'Long-only same broker contract; 20-observation prior momentum; cash/abstention',minReviewCohorts:20,validated:false};
