export function pipelineInputs(bundle){return PIPELINE_INPUTS.map(def=>{
 const f=bundle.feeds?.[def.feedId],points=(['wb_cpi_annual','imf_fiscal_outlook'].includes(def.feedId)?f?.byCurrency?.USD:f?.points)||[],valid=points.filter(p=>Number.isFinite(p.v)&&pipelineDate(p.d)&&p.d<=bundle.capturedAt?.slice(0,10)).sort((a,b)=>a.d.localeCompare(b.d)),last=valid.at(-1),retained=bundle.status?.[def.feedId]?.ok===false;
 return {...def,status:!def.feedId?'Not connected':!last?'Awaiting extraction':retained?'Retained; refresh failed':'Collected',value:last?.v??null,referencePeriod:last?.period||last?.d||null,frequency:f?.frequency||(def.feedId==='cpi'?'Monthly':null),unit:f?.unit||(def.feedId==='cpi'?'% y/y':def.feedId==='WALCL'?'Millions USD':def.feedId==='SP500'?'Index':null),source:f?.source||null,retrievedAt:f?.retrievedAt||null,points:valid.length,error:bundle.status?.[def.feedId]?.error||null,edition:f?.edition||null,classification:last?.classification||null,attribution:f?.attribution||(def.feedId?.startsWith('nav_')?'Copyright State Street Corporation. Private personal/internal research use.':null)};
 });}

// Strict availability join for future research consumers. A date without a clock
// is insufficient evidence of when a release/vintage became available.
export function pipelineAsOf(observations,asOf,maxAgeDays){
 const t=Date.parse(asOf);if(!Number.isFinite(t)||!Number.isFinite(maxAgeDays)||maxAgeDays<0)throw Error('Invalid availability cutoff');
 const candidates=observations.filter(p=>Number.isFinite(p.v)&&pipelineDate(p.d)&&/T.*(?:Z|[+-]\d{2}:\d{2})$/.test(p.availableAt||'')&&Number.isFinite(Date.parse(p.availableAt))&&Date.parse(p.availableAt)<=t&&Date.parse(p.d)<=t&&t-Date.parse(p.d)<=maxAgeDays*86400000);
 candidates.sort((a,b)=>b.d.localeCompare(a.d)||Date.parse(b.availableAt)-Date.parse(a.availableAt));
 const latest=candidates[0];if(!latest)return null;
 if(candidates.some(p=>p.d===latest.d&&p.availableAt===latest.availableAt&&p.v!==latest.v))throw Error('Conflicting point-in-time vintage');
 return {...latest};
}
export function pipelineReport(record){return {version:'PASTED-PIPELINE-2.0',runId:record.runId,capturedAt:record.analysis.capturedAt,inputs:pipelineInputs(record.bundle),alignment:'Snapshot of latest reported observations at collection; mixed reference periods, not a historical synchronised matrix.',availability:'Original retrieval timestamps retained. Historical reference dates alone never establish publication or vintage availability.',analytics:'Prospective cohorts, fixed reference contracts, arithmetic marked returns, explicit costs and drawdowns use the separate Cross-asset evaluation protocol. No SVAR, impulse responses or risk-parity allocation is claimed.',corrections:['Invalid Yahoo/FRED/World Bank/IMF URLs removed; only verified allowlisted sources are collected.','Missing values remain null; no missing stress observations are replaced with zero.','No unlimited forward-fill or hypothetical daily returns from monthly oil prices.','No allocation rule based solely on SOFR > 4.5%; no unsupported energy-as-cash assumption.','Historical descriptive statistics are not prospective performance or identified structural shocks.']};}
export function pipelineCSV(report){const keys=['field','feedId','name','status','value','referencePeriod','frequency','unit','retrievedAt','source','points','note','error','edition','classification','attribution'];const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"';return [keys,...report.inputs.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\r\n');}

export function pipelineCorrelation(bundle){
 const ids=['SP500','DCOILWTICO'],feeds=ids.map(id=>bundle.feeds?.[id]);
 const unavailable=reason=>({status:reason,observations:0,correlation:null,series:ids,method:'Descriptive arithmetic price returns over identical start/end reference dates; no filling, annualisation or causal identification.'});
 if(feeds.some((f,i)=>!f||bundle.status?.[ids[i]]?.ok===false))return unavailable('Unavailable: missing or failed source');
 const returns=feeds.map(f=>{const map=new Map();for(const p of f.points||[]){if(!pipelineDate(p.d)||!Number.isFinite(p.v)||Date.parse(p.d)>Date.parse(bundle.capturedAt||new Date().toISOString()))continue;if(map.has(p.d)&&map.get(p.d)!==p.v)throw Error('Conflicting price history');map.set(p.d,p.v);}const p=[...map].sort(([a],[b])=>a.localeCompare(b)),out=new Map();for(let i=1;i<p.length;i++){const [a,x]=p[i-1],[b,y]=p[i];if(x>0&&y>0&&Date.parse(b)-Date.parse(a)<=4*86400000)out.set(a+'|'+b,y/x-1);}return out;});
 const pairs=[...returns[0]].filter(([k])=>returns[1].has(k)).map(([k,x])=>({interval:k,x,y:returns[1].get(k)}));if(pairs.length<20)return unavailable('Insufficient matched return intervals (minimum 20)');
 const n=pairs.length,mx=pairs.reduce((s,p)=>s+p.x,0)/n,my=pairs.reduce((s,p)=>s+p.y,0)/n,xx=pairs.reduce((s,p)=>s+(p.x-mx)**2,0),yy=pairs.reduce((s,p)=>s+(p.y-my)**2,0),xy=pairs.reduce((s,p)=>s+(p.x-mx)*(p.y-my),0);
 return {...unavailable('Descriptive only; current-vintage history'),observations:n,correlation:xx>0&&yy>0?xy/Math.sqrt(xx*yy):null,firstInterval:pairs[0].interval,lastInterval:pairs.at(-1).interval,sources:feeds.map(f=>({source:f.source,retrievedAt:f.retrievedAt})),limitations:'S&P 500 price index and daily EIA WTI spot prices have different fixing times. Correlation is contemporaneous, not causal or predictive; no ETF total return, structural shock or prospective result is inferred.'};
}

export function accessibleOutlook(bundle){const f=bundle.feeds?.imf_fiscal_outlook;return {edition:f?.edition||null,projectionYear:f?.projectionYear||null,missingEconomies:f?.missingEconomies||[],source:f?.source||null,retrievedAt:f?.retrievedAt||null,checkedAt:bundle.status?.imf_fiscal_outlook?.checkedAt||null,retained:bundle.status?.imf_fiscal_outlook?.ok===false,attribution:f?.attribution||'Source: International Monetary Fund, World Economic Outlook.',note:f?.classificationNote||'Awaiting publisher edition and projection metadata.',rows:Object.entries(f?.byCurrency||{}).map(([ccy,points])=>({ccy,points:points.filter(p=>Number(p.period)>=f.projectionYear)}))};}

async function xaBrokerFeeds(env){return (await Promise.all(Object.keys(BROKER_FEEDS).map(id=>iceRead(env.BUCKET,'broker/'+id+'.json')))).filter(Boolean);}
async function xaArchiveView(env){const prefix='crossasset/v1/'+XA_FINGERPRINT+'/';const [f,o]=await Promise.all([labObjects(env.BUCKET,prefix+'forecasts/',1000),labObjects(env.BUCKET,prefix+'outcomes/',10000)]);return {prefix,forecasts:f.rows,outcomes:o.rows,truncated:f.truncated||o.truncated};}
async function xaPriceFeeds(env,snapshots,broker,write=false){
 const refs=new Map();for(const s of snapshots)for(const a of s.assets||[])if(a.reference?.ok)refs.set(a.reference.broker+'|'+a.reference.brokerSymbol,a.reference);
 const out=[];for(const [id,ref]of refs){const key='crossasset/v1/prices/'+await labHash(id)+'.json',old=await iceRead(env.BUCKET,key),fresh=xaBars(broker,ref),map=new Map((old?.rows||[]).map(r=>[r.endUTC,r]));if(!fresh.reason)for(const r of fresh.points){const p=map.get(r.endUTC);if(!p||Date.parse(r.retrievedUTC)>Date.parse(p.retrievedUTC))map.set(r.endUTC,r);}
 const rows=[...map.values()].sort((a,b)=>a.endUTC.localeCompare(b.endUTC)).slice(-1000);if(write&&!fresh.reason&&rows.length)await env.BUCKET.put(key,JSON.stringify({broker:ref.broker,brokerSymbol:ref.brokerSymbol,kind:'daily',rows}));out.push({broker:ref.broker,kind:'daily',rows:fresh.reason?[]:rows});}
 return out;
}
async function xaRecord(record,env){
 const now=Date.now();if(!record?.analysis||now-Date.parse(record.analysis.capturedAt)>150*60000)throw Error('Refresh the macro baseline before prospective capture');
 const broker=await xaBrokerFeeds(env),models=buildCrossAssetModels(record,now),snapshot=xaFreeze(record,models,broker,XA_FINGERPRINT,now),prefix='crossasset/v1/'+XA_FINGERPRINT+'/';
 if(!models.some(m=>m.eligible))throw Error('No eligible cross-asset forecasts');
 await labPutOnce(env.BUCKET,prefix+'rules.json',{fingerprint:XA_FINGERPRINT,model:CROSSASSET_MODEL,protocol:XA_PROTOCOL,sources:XA_RULE_SOURCES,registeredAt:new Date(now).toISOString()});
 const created=await labPutOnce(env.BUCKET,prefix+'forecasts/'+snapshot.forecastAt.slice(0,10)+'.json',snapshot),archive=await xaArchiveView(env),prices=await xaPriceFeeds(env,archive.forecasts,broker,true),evaluation=xaEvaluate(archive.forecasts,prices,archive.outcomes,now);
 if(archive.truncated)throw Error('Cross-asset archive limit reached; evaluation incomplete');
 for(const outcome of evaluation.outcomes)await labPutOnce(env.BUCKET,prefix+'outcomes/'+await labHash(outcome.forecastAt+'|'+outcome.id)+'.json',outcome);
 await env.BUCKET.put('crossasset/v1/status.json',JSON.stringify({runId:record.runId,phase:'succeeded',checkedAt:new Date(now).toISOString(),fingerprint:XA_FINGERPRINT,created,recordedDates:evaluation.recordedDates}));
 return {created,forecastAt:snapshot.forecastAt,fingerprint:XA_FINGERPRINT,runId:record.runId,eligible:models.filter(m=>m.eligible).length,recordedDates:evaluation.recordedDates};
}
