  if(request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return Response.json({error:'Cross-origin write rejected'},{status:403,headers});if(!request.headers.get('content-type')?.startsWith('application/json'))return Response.json({error:'Use JSON'},{status:415,headers});const raw=await request.text();if(raw.length>1000)return Response.json({error:'Request too large'},{status:413,headers});const body=JSON.parse(raw);if(body.runId!==record.runId)return Response.json({error:'Baseline advanced; reload before capture'},{status:409,headers});return Response.json(await xaRecord(record,env),{headers});
