const POLICY_VERIFICATION_KEY='ops/policy-verification.json';
const RANK_CURRENT_STATES=['Current','Current - date-level','Confirmed unchanged'];
// Aged-data rule (Batch 33): only for the listed trouble economies. A mandatory row in one of these states still counts for the
// production ranking when the last official value is at most one release behind the schedule (or the schedule is behind the data);
// the dashboard labels it as aged. Every other economy keeps the strict rule.
const RANK_AGED_CURRENCIES=['USD','JPY','CAD','CHF'];
const RANK_AGED_STATES=['Superseded','Fallback - recheck','Latest release verified / next date unknown','Period unverified'];
const RANK_AGED_MAX_MONTHS={Monthly:1,Quarterly:3,'Rolling three-month':1,Annual:12};
function iceRankAged(row){
  const max=RANK_AGED_MAX_MONTHS[row?.frequency];
  if(!row||!max||!RANK_AGED_CURRENCIES.includes(row.ccy)||!RANK_AGED_STATES.includes(row.freshness))return false;
  const a=String(row.period||''),b=String(row.latestVerifiedPeriod||'');
  if(a.length<7||b.length<7)return false;
  const months=(Number(b.slice(0,4))-Number(a.slice(0,4)))*12+Number(b.slice(5,7))-Number(a.slice(5,7));
  return Number.isFinite(months)&&months>=0&&months<=max;
}
function verifyPolicyValues(bundle,previous,now){
 const result={};
 for(const {ccy,id,source} of POLICY_CHECK_FEEDS){
  const status=bundle.status?.[id],feed=bundle.feeds?.[id],point=feed?.points?.at(-1);
  const last=previous?.[id]?.points?.at(-1),raw=bundle.feeds?.policy?.byCurrency?.[ccy]?.at(-1);
  const verified=Date.parse(feed?.retrievedAt);
  if(status?.ok!==true||status.cached||status.retained||feed?.source!==source||
    !Number.isFinite(point?.v)||!Number.isFinite(verified)||verified>now||now-verified>86400000)continue;
  const unchanged=Number.isFinite(last?.v)?last.v===point.v:
    Number.isFinite(raw?.v)&&raw.v===point.v&&Date.parse(raw.d)<verified;
  result[ccy]={value:point.v,observationDate:point.d,lastVerifiedAt:feed.retrievedAt,
   confirmedUnchangedAt:unchanged?feed.retrievedAt:null};
 }
 return result;
}
function policyVerificationFor(record,now){
 return record.bundle.policyVerification??verifyPolicyValues(record.bundle,null,now);
}
async function withLatestPolicyVerification(env,record){
 if(!record)return record;
 const saved=await iceRead(env.BUCKET,POLICY_VERIFICATION_KEY).catch(()=>null);
 if(saved?.runId!==record.runId)return record;
 return {...record,bundle:{...record.bundle,policyVerification:saved.checks}};
}

const CONTEXT_CADENCE={
 yield:{frequency:'Monthly',checkDays:7,source:'https://www.oecd.org/en/about/programmes/oecd-data-collection-programme/short-term-economic-statistics.html'},
 cot:{frequency:'Weekly',checkDays:7,source:'https://www.cftc.gov/MarketReports/CommitmentsofTraders/ReleaseSchedule/index.htm'},
 currentAccount:{frequency:'Annual',checkDays:366,source:'https://data.worldbank.org/indicator/BN.CAB.XOKA.GD.ZS'},
 fdi:{frequency:'Annual',checkDays:366,source:'https://data.worldbank.org/indicator/BX.KLT.DINV.WD.GD.ZS'},
 volatility:{frequency:'Daily close',checkDays:5,source:'https://fred.stlouisfed.org/series/VIXCLS'},
 equities:{frequency:'Daily close',checkDays:5,source:'https://fred.stlouisfed.org/series/SP500'},
};
// CFTC's published 2026 dates include holiday delays. No dates are extrapolated.
const CFTC_RELEASES_2026=['01-05','01-09','01-16','01-23','01-30','02-06','02-13','02-20','02-27','03-06','03-13','03-20','03-27',
 '04-03','04-10','04-17','04-24','05-01','05-08','05-15','05-22','05-29','06-05','06-12','06-22','06-26','07-06','07-10','07-17','07-24','07-31',
 '08-07','08-14','08-21','08-28','09-04','09-11','09-18','09-25','10-02','10-09','10-16','10-23','10-30','11-06','11-16','11-20','11-30',
 '12-04','12-11','12-18','12-28'].map(date=>'2026-'+date);
const US_MARKET_HOLIDAYS={
 2026:new Set(['01-01','01-19','02-16','04-03','05-25','06-19','07-03','09-07','11-26','12-25']),
 2027:new Set(['01-01','01-18','02-15','03-26','05-31','06-18','07-05','09-06','11-25','12-24']),
 2028:new Set(['01-17','02-21','04-14','05-29','06-19','07-04','09-04','11-23','12-25']),
};
function contextCadenceExpectation(indicator,now){
 const day=86400000;
 const date=new Date(now);
 if(indicator==='yield')return {period:iceUtcDay(Date.UTC(date.getUTCFullYear(),date.getUTCMonth()-3,1))};
 if(indicator==='currentAccount'||indicator==='fdi')return {};
 const zone='America/New_York',ny=sessionParts(now,zone);
 const wallDate=Date.UTC(ny.year,ny.month-1,ny.day),today=iceUtcDay(wallDate);
 if(indicator==='cot'){
  if(ny.year!==2026)return {calendarMissing:true};
  const past=ny.hour*60+ny.minute>=930;
  const published=CFTC_RELEASES_2026.filter(d=>d<today||(past&&d===today)).at(-1);
  const next=CFTC_RELEASES_2026.find(d=>d>today||(!past&&d===today));
  if(!published)return {calendarMissing:true};
  const released=new Date(published),back=(released.getUTCDay()+5)%7||7;
  const parts=stamp=>{const [year,month,day]=stamp.split('-').map(Number);return {year,month,day};};
  const time=stamp=>new Date(sessionUtc(parts(stamp),15,zone)+1800000).toISOString();
  return {period:iceUtcDay(+released-back*day),nextDueAt:next?time(next):null};
 }
 if(!US_MARKET_HOLIDAYS[ny.year])return {calendarMissing:true};
 // Allow the following business session for FRED publication of the close.
 let remaining=indicator==='volatility'&&ny.hour<12&&![0,6].includes(new Date(wallDate).getUTCDay())&&
  !US_MARKET_HOLIDAYS[ny.year].has(today.slice(5))?2:1;
 for(let i=1;i<=8;i++){
  const prev=new Date(wallDate-i*day),iso=iceUtcDay(prev);
  if(prev.getUTCDay()!==0&&prev.getUTCDay()!==6&&!US_MARKET_HOLIDAYS[prev.getUTCFullYear()]?.has(iso.slice(5))&&--remaining===0)return {period:iso};
 }
 return {calendarMissing:true};
}
function contextReleaseEvidence({indicator,ccy,feed,def,status,point,latest,now}){
 const config=CONTEXT_CADENCE[indicator];
 if(!config||indicator==='yield'&&!/^IRLTLT01/.test(def?.series||''))return null;
 const window=contextCadenceExpectation(indicator,now);
 const retrieval=Date.parse(feed?.retrievedAt),age=now-retrieval,today=iceUtcDay(now);
 const recent=status?.ok===true&&!status.retained&&Number.isFinite(age)&&age>=0&&age<=config.checkDays*86400000;
 const valid=latest&&governanceDate(latest.d)&&latest.d<=today&&Number.isFinite(latest.v);
 const missingNewer=valid&&point&&point.d<latest.d;
 const observationBehind=valid&&window.period&&latest.d<window.period;
 let freshness='Cadence checked',freshnessReason='Latest observation in the successful source check. '+config.frequency+' cadence.';
 if(!valid){freshness='Unavailable';freshnessReason='No usable observation returned for this series.';}
 else if(!recent){freshness='Source check overdue';freshnessReason='Most recent source check failed, was retained, or is outside the '+config.checkDays+'-day recheck window.';}
 else if(missingNewer){freshness='Superseded';freshnessReason='Saved score uses '+point.d+'; source has '+latest.d+'.';}
 else if(window.calendarMissing){freshness='Calendar needs renewal';freshnessReason='Source checked. No verified market or release calendar covers this date.';}
 else if(observationBehind){freshness='Expected period missing';freshnessReason='Latest source observation '+latest.d+' is older than the cadence reference '+window.period+'.';}
 else if(config.frequency==='Annual'&&Number(latest.d.slice(0,4))<new Date(now).getUTCFullYear()-1){
  freshness='Publisher coverage lag';freshnessReason='The World Bank source still shows '+latest.d.slice(0,4)+' for '+ccy+'. Annual publication varies by economy.';
 }
 if(indicator==='yield'&&ccy==='EUR')freshnessReason+=' German 10-year yield is the EUR proxy.';
 return {frequency:config.frequency,freshness,freshnessReason,scheduleSource:config.source,scheduleLabel:indicator==='cot'?'CFTC release calendar':'Publisher cadence',
  latestVerifiedPeriod:recent&&valid?latest.d:null,expectedPeriod:window.period||null,expectedReleaseAt:window.nextDueAt||null,
  evidence:freshness==='Cadence checked'?'Verified':valid?'Partial':'Unavailable'};
}

function governanceEvidence(record, registry, now = Date.now(), officialReleases = {}) {
  const bundle = record.bundle;
  const feeds = bundle.feeds;
  const analysis = record.analysis;
  const definitions = new Map(registry.map(def => [def.id, def]));
  const policyVerification=policyVerificationFor(record,now);
  const rows = analysis.economies.flatMap(e => {
    const check = e.policyValidation;
    const selectedOfficial = check?.independentlyChecked && check.official
      && check.selected?.d === check.official.d && check.selected?.v === check.official.v;
    const cpi = feeds.cpi_AUD?.points?.at(-1)?.d;
    const cpiId = e.ccy === 'AUD' && cpi && cpi > (feeds.cpi?.byCurrency?.AUD?.at(-1)?.d || '') ? 'cpi_AUD' : 'cpi';
    const ids = {
      policy: selectedOfficial ? 'policy_check_'+e.ccy : 'policy',
      inflation: cpiId,
      growth: analysis.officialGrowthInputs?.[e.ccy]?.feed || 'gdp_'+e.ccy,
      jobs: e.ccy==='GBP'&&e.observations?.jobs?.feedId==='ons_jobs'?'ons_jobs':'jobs_'+e.ccy,
      yield: 'yield_'+e.ccy,
      cot: 'cot',
      currentAccount: 'external_current',
      fdi: 'external_fdi',
      volatility: 'VIXCLS',
      equities: 'SP500',
      oil: 'DCOILBRENTEU'
    };
    return Object.entries(ids).filter(([name]) => name !== 'oil' || e.ccy === 'CAD').map(([indicator, id]) => {
      const feed = feeds[id];
      const def = definitions.get(id);
      const reportedStatus = bundle.status?.[id];
      const status = indicator==='inflation' && id==='cpi' &&
        (reportedStatus?.retained || reportedStatus?.retainedKeys?.includes(e.ccy))
        ? {...reportedStatus,ok:false,retained:true}
        : reportedStatus;
      const checkedFetch = indicator==='jobs'&&e.ccy==='CHF'&&id==='jobs_CHF'||
        indicator==='inflation'&&e.ccy==='CAD'&&id==='cpi'||
        indicator==='growth'&&e.ccy==='JPY'&&['gdp_JPY','oecd_real_gdp'].includes(id);
      const scoredPoint = e.observations?.[indicator];
      const constituents=indicator==='cot'&&e.ccy==='USD'?ICE_CORE.filter(ccy=>ccy!=='USD').map(ccy=>feed?.byCurrency?.[ccy]||[]):null;
      const latestCommon=constituents?.[0]?.findLast(p=>constituents.every(history=>history.some(q=>q.d===p.d)));
      const feedPoint = constituents?latestCommon:feed?.byCurrency?.[e.ccy]?.at(-1) ?? feed?.rows?.[e.ccy] ?? feed?.points?.at(-1);
      const point = checkedFetch ? feedPoint : scoredPoint ?? feedPoint;
      const differsFromScore = checkedFetch && point && (point.d!==scoredPoint?.d || point.v!==scoredPoint?.v);
      const proxy = (indicator === 'cot' && e.ccy === 'USD') || (indicator === 'yield' && !!def?.proxy);
      const mandatory = ['policy','inflation','growth','jobs'].includes(indicator);
      const release = officialReleases[e.ccy+'/'+id];
      const exactRelease = release?.seriesId === (def?.series || id)
        && release?.economy === e.ccy && /^https:\/\//i.test(release?.source || '') ? release : null;

      const dateLevel = exactRelease?.precision === 'date';
      const dateFreshness = () => {
        const pub=exactRelease.publishedDate,next=exactRelease.nextReleaseDate,today=new Date(now).toISOString().slice(0,10);
        if(!/^\d{4}-\d{2}-\d{2}$/.test(pub||'')||!/^\d{4}-\d{2}-\d{2}$/.test(next||'')||!governanceDate(pub)||!governanceDate(next)||pub>=next)return 'Schedule unverified';
        if(today>=next)return 'Release due - recheck';
        if(!point||!Number.isFinite(point.v)||Date.parse(point.d)>now)return 'Unavailable';
        if(Number.isFinite(exactRelease.confirmedPolicyValue)){
          if(!selectedOfficial||point.v!==exactRelease.confirmedPolicyValue||check.selected.v!==point.v)return 'Policy differs from last verified decision';
        }else if(point.d!==exactRelease.period)return point.d<exactRelease.period?'Superseded':'Period unverified';
        if(status?.ok!==true||!governanceDate(feed?.retrievedAt)||Date.parse(feed.retrievedAt)>now||feed.retrievedAt.slice(0,10)<=pub)return 'Cached / collection unverified';
        return 'Current - date-level';
      };
      const baseFreshness = exactRelease?.publisherCrossCheck&&point?.d===exactRelease.period&&
        (!Number.isFinite(point.v)||Math.abs(point.v-exactRelease.publishedRoundedValue)>=0.05)
        ? 'Publisher value mismatch'
        : checkedFetch && status?.retained ? 'Cached / collection unverified'
        : differsFromScore ? 'Saved score uses a different observation'
        : mandatory && !e.observations?.[indicator] ? 'Unavailable'
        : dateLevel ? dateFreshness() : selectedOfficial && indicator === 'policy' && !exactRelease && status?.ok === true
          && Date.parse(check.retrievedAt) <= now && now-Date.parse(check.retrievedAt) <= 86400000
          ? 'Official level confirmed / next date unknown' : indicatorFreshness(point, feed, exactRelease, status, now);
      const verified=indicator==='policy'&&selectedOfficial?policyVerification[e.ccy]:null;
      const checkedAt=Date.parse(verified?.lastVerifiedAt);
      const matchingCheck=verified&&point?.v===verified.value&&check.selected.d===verified.observationDate&&
        checkedAt<=now&&now-checkedAt<=86400000;
      const unchanged=matchingCheck&&verified.confirmedUnchangedAt===verified.lastVerifiedAt;
      const freshness=unchanged&&RANK_CURRENT_STATES.includes(baseFreshness)?'Confirmed unchanged':baseFreshness;
      return {
        ccy:e.ccy, indicator, feedId:id, seriesId:def?.series || (id==='cpi' && e.ccy==='USD' ? 'WS_LONG_CPI/M.US.771' : id==='policy' && e.ccy==='USD' ? 'WS_CBPOL/D.US' : id),
        source:feed?.source || def?.source || null,
        period:point?.d || null, frequency:feed?.frequencyByCurrency?.[e.ccy] || feed?.frequency || def?.frequency || null,
        publishedAt:governanceDate(point?.publishedAt) || ((point?.d === exactRelease?.period || (Number.isFinite(exactRelease?.confirmedPolicyValue) && point?.v === exactRelease.confirmedPolicyValue))
          ? governanceDate(exactRelease?.publishedAt) : null),
        retrievedAt:governanceDate(feed?.retrievedAt),
        expectedReleaseAt:governanceDate(exactRelease?.nextDueAt),
        latestVerifiedPeriod:exactRelease?.period || null,
        scheduleSource:exactRelease?.calendarSource || exactRelease?.source || null,
        vintage:point?.vintage ?? point?.realtimeStart ?? null,
        collection:status?.ok === true ? 'Fetched' : status?.ok === false ? 'Failed' : 'Unavailable',
        publishedDate:dateLevel?exactRelease.publishedDate:null, nextReleaseDate:dateLevel?exactRelease.nextReleaseDate:null,
        freshness, mandatory,
        ...(matchingCheck?verified:{}),
        ...(freshness==='Confirmed unchanged'?{freshnessReason:verified.value.toFixed(2)+'% · Confirmed unchanged · last verified '+verified.lastVerifiedAt.slice(0,10)+' UTC · effective observation '+verified.observationDate}:{}),
        ...(indicator==='growth'&&exactRelease?.publisherCrossCheck&&RANK_CURRENT_STATES.includes(freshness)
          ?{freshnessReason:exactRelease.publisherCrossCheck}:{}),
        ...(checkedFetch&&!(indicator==='growth'&&exactRelease?.publisherCrossCheck&&RANK_CURRENT_STATES.includes(freshness))?{freshnessReason:differsFromScore&&!status?.retained
          ? 'Fetched '+point.d+' ('+point.v+'); saved score uses '+(scoredPoint?scoredPoint.d+' ('+scoredPoint.v+')':'no observation')
          : freshness==='Superseded'?'Period lagging: saved '+point.d+'; released '+exactRelease.period
          : freshness==='Latest release verified / next date unknown'?'Fetched '+point.d+'; next official release date is unverified'
          : freshness==='Schedule unverified'&&e.ccy==='JPY'&&id==='oecd_real_gdp'
            ? 'OECD observation '+point.d+'; '+(status?.ok===true?'fetched successfully, but ':'latest fetch failed or is missing, and ')+'the selected OECD series has no verified release schedule'
          : freshness==='Cached / collection unverified'?'Latest saved fetch is retained, failed, or predates the verified release'
          : freshness==='Unavailable'?'No usable observation in the saved fetch'
          : RANK_CURRENT_STATES.includes(freshness)?null:freshness}:{}),
        ...(e.ccy==='CHF'&&id==='jobs_CHF'&&Number.isFinite(exactRelease?.publisherSeasonallyAdjustedRate)
          &&(!point||point.d<=exactRelease.period)&&!exactRelease.nextDueAt ? {
          freshnessReason:'FSO release verified · '+exactRelease.period+' · '+exactRelease.publisherSeasonallyAdjustedRate.toFixed(1)+'% seasonally adjusted · next date unconfirmed'
            +(scoredPoint?' · saved scoring observation '+scoredPoint.d:''),
          publisherObservation:{period:exactRelease.period,value:exactRelease.publisherSeasonallyAdjustedRate,publishedAt:exactRelease.publishedAt,source:exactRelease.source}
        }:{}),
        inputType:proxy ? 'Proxy' : indicator === 'growth' && def?.transform === 'level' ? 'Calculated' : 'Observed',
        evidence:point && RANK_CURRENT_STATES.includes(freshness) ? 'Verified' : point ? 'Partial' : 'Unavailable',
        ...(!mandatory?contextReleaseEvidence({indicator,ccy:e.ccy,feed,def,status,point,latest:feedPoint,now}):null)
      };
    });
  });
  const crossAssetInputs = [
    ['XAU / XAG','US 10Y real yield','DFII10',feeds.DFII10?.points?.at(-1)],
    ...['XAU','XAG'].map(asset => [asset,'Managed-money futures positioning','metals_cot',feeds.metals_cot?.byCurrency?.[asset]?.at(-1)])
  ];
  for (const [ccy,indicator,id,point] of crossAssetInputs) {
    const feed = feeds[id], def = definitions.get(id), status = bundle.status?.[id];
    rows.push({
      ccy, indicator, feedId:id, seriesId:def?.series || id, source:feed?.source || def?.source || null,
      period:point?.d || null, frequency:feed?.frequency || def?.frequency || null,
      publishedAt:governanceDate(point?.publishedAt), retrievedAt:governanceDate(feed?.retrievedAt),
      expectedReleaseAt:null, latestVerifiedPeriod:null, scheduleSource:null,
      vintage:point?.vintage ?? point?.realtimeStart ?? null,
      collection:status?.ok === true ? 'Fetched' : status?.ok === false ? 'Failed' : 'Unavailable',
      freshness:indicatorFreshness(point,feed,null,status,now), mandatory:false, inputType:'Observed',
      evidence:point ? 'Partial' : 'Unavailable'
    });
  }
  return rows.map(row => ({
    ...row,
    freshnessReason:row.freshnessReason??(row.freshness==='Current'?'Verified release: latest period '+row.period+(row.publishedAt?', published '+String(row.publishedAt).slice(0,10):'')+(row.nextReleaseDate?'; next release '+row.nextReleaseDate:'')+'.':
      row.freshness==='Superseded'?'Period lagging: saved '+row.period+'; released '+row.latestVerifiedPeriod:
      'Schedule missing: '+(ICE_RELEASE_SCHEDULE_REASONS[row.ccy+'/'+row.feedId]||
        'Exact series publication and next release schedule not verified')+
        (row.scheduleSource?' Official calendar: '+row.scheduleSource:'')),
    expectedPeriodReason:row.expectedPeriod?null:(['Current','Current - date-level','Confirmed unchanged'].includes(row.freshness)?'Not applicable: the verified release calendar already confirms this period':row.freshness==='Cadence checked'?'Not applicable: annual or irregular series with no fixed expected period':row.freshness==='Unavailable'?'No usable observation, so no period to expect':'Not set: no verified release schedule for this series'),
    peerPeriods:[...new Set(rows.filter(other => other.ccy !== row.ccy
      && other.indicator === row.indicator && other.frequency === row.frequency
      && other.period).map(other => other.period))].sort().reverse()
  }));
}

function iceRankEligibility(entry, evidence) {
  if (!entry || !Number.isFinite(entry.score)) return 'No production score';
  if ((entry.legacyCoverage??entry.coverage) + 1e-9 < ICE_RANK_MIN_COVERAGE) return 'Below 85% coverage on core factors';
  if (!entry.critical) return 'Mandatory production input unavailable';
  const mandatory = evidence.filter(row => row.ccy === entry.ccy && row.mandatory);
  if (mandatory.length !== 4 || mandatory.some(row => !RANK_CURRENT_STATES.includes(row.freshness) && !iceRankAged(row))) {
    return 'Mandatory release freshness unverified';
  }
  return null;
}

