const USDX_COT_SOURCE = 'https://publicreporting.cftc.gov/resource/gpe5-46if.json?' + new URLSearchParams({
  $where:"cftc_contract_market_code='098662'",
  $select:'cftc_contract_market_code,market_and_exchange_names,report_date_as_yyyy_mm_dd,lev_money_positions_long,lev_money_positions_short,open_interest_all',
  $order:'report_date_as_yyyy_mm_dd DESC', $limit:'160'
});
const USDX_COT_FEED = {id:'usdx_cot_tff',kind:'usdx-tff',name:'CFTC ICE USD Index futures-only leveraged funds',source:USDX_COT_SOURCE,frequency:'Weekly'};
const B2_DAY = 86400000;
const B2_WEEK = 7*B2_DAY;

function b2Date(date) {
  return typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date)
    && Number.isFinite(Date.parse(date)) && new Date(date).toISOString().slice(0,10) === date;
}

function b2Count(value) {
  return (typeof value === 'number' || (typeof value === 'string' && /^\d+$/.test(value)))
    && Number.isSafeInteger(Number(value)) && Number(value)>=0 ? Number(value) : null;
}

function b2Counts(long,short,oi) {
  return long !== null && short !== null && oi > 0 && long <= oi && short <= oi;
}

function parseUsdxCot(rows, now = Date.now()) {
  if (!Array.isArray(rows) || !rows.length || rows.length>160) throw Error('Invalid CFTC USDX payload');
  const dates = new Set();
  return rows.map(row => {
    const d = row.report_date_as_yyyy_mm_dd?.slice(0,10);
    const long = b2Count(row.lev_money_positions_long), short = b2Count(row.lev_money_positions_short);
    const oi = b2Count(row.open_interest_all);
    if (row.cftc_contract_market_code !== '098662' || !/^USD INDEX\s*-\s*ICE FUTURES U\.S\.?$/i.test(row.market_and_exchange_names?.trim() || '')
      || !b2Date(d) || Date.parse(d)>now || dates.has(d) || !b2Counts(long,short,oi)) throw Error('Unexpected CFTC USDX contract or observations');
    dates.add(d);
    return {d,long,short,oi,net:long-short,v:100*(long-short)/oi};
  }).sort((a,b)=>a.d.localeCompare(b.d));
}

function validateUsdxCot(feed, capturedAt, previous) {
  const capture = Date.parse(capturedAt), retrieved = Date.parse(feed?.retrievedAt);
  if (feed?.source !== USDX_COT_SOURCE || feed.contract !== '098662' || feed.report !== 'TFF futures only'
    || !Number.isFinite(retrieved) || Math.abs(capture-retrieved)>B2_DAY || !Array.isArray(feed.points)) throw Error('Invalid USDX source provenance');
  const raw = feed.points.map(p=>({cftc_contract_market_code:feed.contract,market_and_exchange_names:feed.market,
    report_date_as_yyyy_mm_dd:p.d,lev_money_positions_long:p.long,lev_money_positions_short:p.short,open_interest_all:p.oi}));
  const points = parseUsdxCot(raw,capture);
  if (previous?.points?.at(-1)?.d > points.at(-1).d) throw Error('USDX history regressed');
  return {...USDX_COT_FEED,contract:'098662',report:'TFF futures only',market:'USD INDEX - ICE FUTURES U.S.',
    retrievedAt:feed.retrievedAt,points};
}

function b2Week(d) {
  return Math.floor((Date.parse(d)+3*B2_DAY)/B2_WEEK);
}

function batch2aPositioning(points,feed,status,now,context={}) {
  const dated = new Map();
  for (const p of points || []) {
    if (!b2Date(p.d) || Date.parse(p.d)>now) continue;
    const week = b2Week(p.d);
    dated.set(week,dated.has(week) ? null : p);
  }
  const last = Math.max(...dated.keys());
  const current = dated.get(last), prior = dated.get(last-1);
  const valid = p => p && b2Counts(b2Count(p.long),b2Count(p.short),b2Count(p.oi));
  const reportDate = current?.d || null;
  const provenance = {reportDate,retrievedAt:feed?.retrievedAt || null,source:feed?.source || null,...context};
  if (!valid(current) || !Number.isFinite(Date.parse(feed?.retrievedAt)) || Date.parse(feed.retrievedAt)>now) {
    return {...provenance,status:'Unavailable',net:null,netPct:null};
  }
  const net = current.long-current.short, netPct = 100*net/current.oi;
  const fresh = status?.ok === true && now-Date.parse(current.d)<=10*B2_DAY;
  const priorNet = valid(prior) ? prior.long-prior.short : null;
  const weeklyNet = priorNet === null ? null : net-priorNet;
  const weeklyOi = priorNet === null ? null : current.oi-prior.oi;
  const weeklyPct = priorNet === null ? null : netPct-100*priorNet/prior.oi;
  const window = Array.from({length:52},(_,i)=>dated.get(last-i)).filter(valid);
  const history = window.map(p=>100*(p.long-p.short)/p.oi);
  const percentile = window.length===52 ? 100*(history.filter(v=>v<netPct).length+.5*history.filter(v=>v===netPct).length)/52 : null;
  const crowding = fresh && percentile!==null
    ? net>0 && percentile>=90 ? 'Crowded long' : net<0 && percentile<=10 ? 'Crowded short' : 'No extreme percentile'
    : null;
  const squeeze = crowding==='Crowded short' ? 'Conditional short-squeeze vulnerability'
    : crowding==='Crowded long' ? 'Conditional long-liquidation vulnerability' : null;
  const dynamics = !fresh || weeklyNet===null ? null : Math.sign(net)!==Math.sign(priorNet) && net!==0 && priorNet!==0 ? 'Net sign reversal / possible regime change'
    : net!==0 && Math.abs(net)>Math.abs(priorNet) && weeklyOi>0 ? 'Directional positioning building as open interest rises'
    : Math.abs(net)<Math.abs(priorNet) && weeklyOi<0 ? 'Possible position liquidation'
    : net===0 ? 'Flat net positioning' : 'Established '+(net>0?'long':'short')+' positioning';
  return {...provenance,status:fresh?'Current at capture':'Stale or retained at capture',
    long:current.long,short:current.short,oi:current.oi,net,netPct,weeklyNet,weeklyPct,weeklyOi,percentile,
    percentileWeeks:window.length,crowding,squeeze,dynamics};
}

ICE_FEEDS.push(USDX_COT_FEED);
function b2MarketContext(bundle,id,now,lag,periods) {
  const f = bundle.feeds[id];
  const rows = (f?.points || []).filter(p=>b2Date(p.d) && Date.parse(p.d)<=now && Number.isFinite(p.v))
    .sort((a,b)=>a.d.localeCompare(b.d));
  const latest = rows.at(-1);
  if (!latest || !Number.isFinite(Date.parse(f.retrievedAt)) || Date.parse(f.retrievedAt)>now) return null;
  const previous = rows.at(-1-periods);
  const current = bundle.status?.[id]?.ok===true && now-Date.parse(latest.d)<lag*B2_DAY;
  return {latest,previous:previous || null,retrievedAt:f.retrievedAt,source:f.source,current,
    change:current && previous ? latest.v-previous.v : null};
}

function batch2aGold(record) {
  const now = Date.parse(record.analysis.generatedAt), b = record.bundle;
  const asset = record.analysis.assets.find(a=>a.id==='XAU');
  const real = asset?.features.find(f=>f.name==='US real-yield pressure');
  const history = b.feeds.DFII10?.points || [];
  const position = real?.observation ? history.findLastIndex(p=>p.d===real.observation.d && p.v===real.observation.v) : -1;
  const prior5 = position>=5 ? history[position-5] : null;
  const prior20 = position>=20 ? history[position-20] : null;
  const real20 = prior20 ? real.observation.v-prior20.v : null;
  const expected = real20===null || real?.score==null ? null : Math.min(100,Math.max(0,50-50*real20));
  const fed = b.feeds.fed_projections;
  const survey = fed?.projections?.length && Date.parse(fed.retrievedAt)<=now && Date.parse(fed.publicationDate)<=now
    ? {publicationDate:fed.publicationDate,retrievedAt:fed.retrievedAt,source:fed.source,projections:fed.projections.slice(0,5)} : null;
  const vix = b2MarketContext(b,'VIXCLS',now,10,5);
  return {score:asset?.score ?? null,coverage:asset?.coverage ?? null,realYield:{
      latest:real?.observation || null,prior5,prior20,delta5:prior5?real.observation.v-prior5.v:null,delta20:real20,
      score:real?.score ?? null,expected,weight:real?.weight ?? null,
      contribution:real?.score!=null && asset.coverage>0?(real.score-50)*real.weight/asset.coverage:null,
      source:real?.source || null,retrievedAt:b.feeds.DFII10?.retrievedAt || null},
    dollar:{fundamentalProxy:record.analysis.assets.find(a=>a.id==='DXY')?.score ?? null,
      broadDollar:b2MarketContext(b,'DTWEXBGS',now,12,20),iceDxyCash:null},
    liquidity:{fedAssets:b2MarketContext(b,'WALCL',now,20,4),m2:b2MarketContext(b,'M2SL',now,75,3)},
    expectations:survey,vix,regime:vix?.current ? vix.latest.v<15?'Low volatility':vix.latest.v<25?'Intermediate volatility':'High volatility':'Unverified'};
}

const BATCH2A_VERSION = 'ICE-SHADOW-2A.1';
const BATCH2A_MIN_START = Date.parse('2026-11-09T02:00:00Z');
const BATCH2A_ONS = 'https://www.ons.gov.uk/employmentandlabourmarket/peoplenotinwork/unemployment/timeseries/mgsx/lms/data';
const BATCH2A_POLICY_DECISIONS = {
  GBP:{period:'2026-11-05',verifiedBy:'2026-11-06T00:00:00Z',nextDueAt:'2026-12-17T00:00:00Z',
    value:4,source:'https://www.bankofengland.co.uk/monetary-policy-summary-and-minutes/2026/november-2026',
    calendarSource:'https://www.bankofengland.co.uk/monetary-policy/upcoming-mpc-dates'},
  AUD:{period:'2026-11-04',verifiedBy:'2026-11-04T00:00:00Z',nextDueAt:'2026-12-08T00:00:00Z',
    value:4.85,source:'https://www.rba.gov.au/statistics/cash-rate/'},
  CHF:{period:'2026-09-24',verifiedBy:'2026-09-25T00:00:00Z',nextDueAt:'2026-12-10T08:30:00Z',
    value:0,source:'https://www.snb.ch/en/publications/communication/press-releases-restricted/pre_20260924',
    calendarSource:'https://www.snb.ch/en/services-events/digital-services/event-schedule'}
};

function b2OnsRelease(record, now) {
  const f = record.bundle.feeds.ons_jobs;
  if (f?.series !== 'MGSX' || f.source !== BATCH2A_ONS || f.frequency !== 'Rolling three-month') return null;
  const release = Date.parse(f.releaseDate), retrieved = Date.parse(f.retrievedAt);
  const next = /^\d{1,2} [A-Za-z]+ \d{4}$/.test(f.nextRelease || '') ? Date.parse(f.nextRelease+' 00:00 UTC') : NaN;
  const points = (f.points || []).filter(p => b2Date(p.d) && Date.parse(p.d)<=now && Number.isFinite(p.v) && p.v>=0 && p.v<=100)
    .sort((a,b)=>a.d.localeCompare(b.d));
  const latest = points.at(-1);
  if (!latest || new Set(points.map(p=>p.d)).size !== points.length || !(release<=retrieved && retrieved<=now && next>release)) return null;
  // Date-only ONS calendar values are conservative cutoffs, not exact release timestamps.
  const nextCutoff = next-3600000;
  return {feed:f,points,latest,releaseDate:f.releaseDate,retrievedAt:f.retrievedAt,
    nextRelease:f.nextRelease,current:record.bundle.status?.ons_jobs?.ok===true && now<nextCutoff};
}

function b2WeightFactor(factor, excluded) {
  const features = factor.features.map((f,i)=>excluded.has(i) ? {...f,score:null} : f);
  const all = features.reduce((n,f)=>n+f.weight,0);
  const available = features.filter(f=>Number.isFinite(f.score));
  const weight = available.reduce((n,f)=>n+f.weight,0);
  return {features,coverage:all ? 100*weight/all : 0,score:weight ? available.reduce((n,f)=>n+f.score*f.weight,0)/weight : null};
}

function b2FreshnessEvidence(record, registry, releases, now, ons) {
  const evidence = nationalEvidence(record,registry,now,releases).filter(row=>row.mandatory);
  return evidence.map(row => {
    let freshness = row.freshness;
    if (row.ccy==='GBP' && row.indicator==='jobs' && ons) {
      if (ons.current) return {...row,feedId:'ons_jobs',seriesId:'MGSX',source:ons.feed.source,
        period:ons.latest.d,frequency:'Rolling three-month',latestVerifiedPeriod:ons.latest.d,
        retrievedAt:ons.retrievedAt,releaseEdition:ons.releaseDate,nextRelease:ons.nextRelease,freshness:'Current',evidence:'Verified'};
      if (row.period && row.period<ons.latest.d) freshness='Superseded';
    }
    const decision = BATCH2A_POLICY_DECISIONS[row.ccy];
    if (decision && row.indicator==='policy' && now>=Date.parse(decision.verifiedBy) && now<Date.parse(decision.nextDueAt)) {
      const incumbent = record.analysis.economies.find(e=>e.ccy===row.ccy)?.observations?.policy;
      const collected = Date.parse(row.retrievedAt);
      if (incumbent && collected<=now) {
        freshness = Math.abs(incumbent.v-decision.value)>1e-8 ? 'Policy differs from last verified decision'
          : collected>=Date.parse(decision.period) && row.collection==='Fetched' ? 'Current' : freshness;
      }
      return {...row,freshness,officialPolicy:decision};
    }
    return {...row,freshness};
  });
}

function b2PolicyEvidence(record, evidence, releases, now) {
  return record.analysis.economies.map(e=>{
    const row = evidence.find(r=>r.ccy===e.ccy && r.indicator==='policy');
    const independent = e.policyValidation?.independentlyChecked ? e.policyValidation : null;
    const release = releases[e.ccy+'/policy'];
    const confirmed = Number.isFinite(release?.confirmedPolicyValue) && Date.parse(release.publishedAt)<=now
      && now<Date.parse(release.nextDueAt) ? {value:release.confirmedPolicyValue,period:release.period,source:release.source} : null;
    const official = row.officialPolicy || (independent?.official ? {value:independent.official.v,
      period:independent.official.d,source:independent.source,retrievedAt:independent.retrievedAt} : confirmed);
    return {ccy:e.ccy,point:e.observations?.policy || null,official,freshness:row.freshness,
      verification:row.officialPolicy ? 'Verified central-bank decision' : independent?.status || (row.scheduleSource ? 'Publisher release calendar' : 'Independent check unavailable')};
  });
}

function b2Comparability(row, rows) {
  const peers = [...new Set(rows.filter(other=>other.ccy!==row.ccy && other.indicator===row.indicator
    && other.frequency && other.frequency===row.frequency && other.period).map(other=>other.period))].sort();
  return {peerPeriods:peers,comparability:!row.period || !peers.length ? 'Unverified / no like-frequency peer'
    : peers.every(period=>period===row.period) ? 'Matched period' : 'Mixed periods'};
}

function buildBatch2a(record, registry, releases, model, onsLabour) {
  const now = Date.parse(record.analysis.generatedAt);
  const ons = b2OnsRelease(record,now);
  const evidence = b2FreshnessEvidence(record,registry,releases,now,ons);
  const revisedLabour = ons?.current ? onsLabour(ons,now) : null;
  const currencies = record.analysis.economies.map(e=>{
    const rows = evidence.filter(r=>r.ccy===e.ccy);
    const invalid = new Set(rows.filter(r=>['Superseded','Policy differs from last verified decision','Observation date invalid'].includes(r.freshness)).map(r=>r.indicator));
    const remove = {
      rates:new Set([...(invalid.has('policy')?[0,1,2]:[]),...(invalid.has('inflation')?[2]:[])]),
      inflation:new Set(invalid.has('inflation')?[0,1]:[]),
      growth:new Set(invalid.has('growth')?[0,1,2]:[]),
      labour:new Set(invalid.has('jobs')?[0,1]:[])
    };
    let weighted=0, coverage=0;
    const replaced = e.ccy==='GBP' && revisedLabour;
    for (const [id,factor] of Object.entries(e.factors)) {
      const current = id==='labour' && replaced ? replaced : remove[id]?.size ? b2WeightFactor(factor,remove[id]) : factor;
      if (!Number.isFinite(current.score)) continue;
      const weight=model.weights[id]*current.coverage/100;
      coverage+=weight;
      weighted+=current.score*weight;
    }
    const verified = rows.filter(r=>r.freshness==='Current').length;
    const required={policy:'Current policy rate',inflation:'Timely CPI',growth:'Timely quarterly GDP',jobs:'Timely employment'};
    const critical = rows.length===4 && verified===4
      && Object.entries(required).every(([id,gap])=>(id==='jobs' && replaced)
        || (Number.isFinite(e.observations?.[id]?.v) && !e.gaps.includes(gap)));
    const eligible = critical && coverage>=ICE_RANK_MIN_COVERAGE;
    return {ccy:e.ccy,productionScore:e.score,candidateScore:coverage?weighted/coverage:null,coverage,
      eligible,verifiedMandatory:verified,excludedInputs:[...invalid],onsLabour:!!replaced,
      evidence:rows.map(r=>({...r,...b2Comparability(r,evidence)}))};
  });
  const pairs = record.analysis.pairs.map(p=>{
    const base = currencies.find(e=>e.ccy===p.base), quote = currencies.find(e=>e.ccy===p.quote);
    const eligible = !!(base?.eligible && quote?.eligible);
    const delta = Number.isFinite(base?.candidateScore) && Number.isFinite(quote?.candidateScore) ? base.candidateScore-quote.candidateScore : null;
    return {base:p.base,quote:p.quote,productionDelta:p.delta,productionBias:p.bias,candidateDelta:delta,eligible,
      candidateBias:eligible?iceBias(delta,model.pairThreshold):'Insufficient verified evidence'};
  });
  const b = record.bundle;
  const cot = b.feeds.cot, usdx = b.feeds[USDX_COT_FEED.id];
  const positioning = [
    ...currencies.filter(row=>row.ccy!=='USD').map(row=>batch2aPositioning(cot?.byCurrency?.[row.ccy],cot,b.status?.cot,now,
      {label:row.ccy,scope:'CFTC TFF futures-only leveraged funds, native currency orientation'})),
    ...['XAU','XAG'].map(asset=>batch2aPositioning(b.feeds.metals_cot?.byCurrency?.[asset],b.feeds.metals_cot,b.status?.metals_cot,now,
      {label:asset,scope:'CFTC disaggregated futures-only managed money'})),
    batch2aPositioning(usdx?.points,usdx,b.status?.[USDX_COT_FEED.id],now,
      {label:'ICE USDX',scope:'CFTC TFF futures-only leveraged funds, contract 098662'})
  ];
  const usd = record.analysis.economies.find(e=>e.ccy==='USD')?.observations?.cot;
  const legacy = b.feeds.legacy_cot;
  const speculative = (legacy?.series || []).filter(({ccy})=>currencies.some(e=>e.ccy===ccy) || ['XAU','XAG'].includes(ccy))
    .map(({ccy,points})=>batch2aPositioning(points,legacy,b.status?.legacy_cot,now,{label:ccy,scope:'CFTC legacy futures-only non-commercial'}));
  const historic = now<BATCH2A_MIN_START;
  return {version:BATCH2A_VERSION,modelVersion:record.analysis.modelVersion,runId:record.runId,asOf:record.analysis.generatedAt,
    historic,validated:false,currencies,pairs,positioning,speculative,policy:b2PolicyEvidence(record,evidence,releases,now),
    labour:{incumbent:record.analysis.economies.find(e=>e.ccy==='GBP')?.observations?.jobs || null,
      source:BATCH2A_ONS,official:ons?.latest || null,releaseEdition:ons?.releaseDate || null,nextRelease:ons?.nextRelease || null,
      retrievedAt:ons?.retrievedAt || null,eligible:!!revisedLabour},
    syntheticUsd:{reportDate:usd?.d || null,netPct:usd?.v ?? null,retrievedAt:cot?.retrievedAt || null,
      scope:'Inverse equal-weight average of seven native leveraged net/OI ratios on common report dates'},
    gold:batch2aGold(record)};
}

const BATCH2A_FINGERPRINT="0612c41719d60f82a71a952a62960d070ec3b6325c9fa77315021fc02f5a8bb0";
function batch2aForRecord(record) {
  return {...buildBatch2a(record,ICE_FEEDS,ICE_OFFICIAL_RELEASES,ICE_MODEL,(ons,now)=>{
    const jobs = {...ons.feed,points:ons.points,frequency:'Monthly'};
    const series = ICE_SERIES.map(def=>def.id==='jobs_GBP'?{...def,source:ons.feed.source}:def);
    const bundle = {...record.bundle,feeds:{...record.bundle.feeds,jobs_GBP:jobs}};
    return evaluateIce(bundle,ICE_MODEL,ICE_CORE,series,now).economies.find(e=>e.ccy==='GBP').factors.labour;
  }),fingerprint:BATCH2A_FINGERPRINT};
}

async function batch2aArchive(record,env) {
  if (!record.batch2a || record.batch2a.historic) return;
  const day=record.batch2a.asOf.slice(0,10);
  await labPutOnce(env.BUCKET,'validation/shadow-2a/'+BATCH2A_FINGERPRINT+'/'+day+'.json',record.batch2a);
}

async function batch2aApi(request,env) {
  const headers={'Cache-Control':'no-store'};
  if (request.method!=='GET') return Response.json({error:'Use GET'},{status:405,headers});
  if (!env.BUCKET) return Response.json({error:'Saved evidence unavailable'},{status:503,headers});
  const record=await iceRead(env.BUCKET,'ice/latest.json');
  if (!record) return Response.json({version:BATCH2A_VERSION,status:'No saved run'}, {headers});
  const recorded=record.batch2a?.fingerprint===BATCH2A_FINGERPRINT;
  const data=recorded?record.batch2a:batch2aForRecord(record);
  return Response.json({...data,recorded,status:recorded?'Recorded shadow diagnostics':'Diagnostic reconstructed from archived inputs'}, {headers});
}

const B2B_TRADE_REPORTERS = {36:'AUD',124:'CAD',392:'JPY',554:'NZD',756:'CHF',826:'GBP',842:'USD'};
const B2B_TRADE_PRODUCTS = ['TOTAL','2709','271111','271121'];
const B2B_TRADE_FEED = {id:'b2b_energy_trade',kind:'b2b-comtrade',name:'UN Comtrade reported oil, gas and total merchandise trade',frequency:'Annual'};
const B2B_GAS_FEED={id:'DHHNGSP',kind:'fred',name:'Henry Hub natural gas spot',series:'DHHNGSP',frequency:'Daily',unit:'USD/MMBtu',source:'https://fred.stlouisfed.org/series/DHHNGSP'};
const B2B_WDI_FEEDS = [
  ['b2b_tot','TT.PRI.MRCH.XD.WD','Merchandise terms of trade','2015 = 100'],
  ['b2b_gdp_usd','NY.GDP.MKTP.CD','Nominal GDP','Current USD'],
  ['b2b_money_gdp','FM.LBL.BMNY.GD.ZS','Broad money level','% GDP'],
  ['b2b_money_growth','FM.LBL.BMNY.ZG','Broad money growth','Annual %'],
  ['b2b_portfolio','BN.KLT.PTXL.CD','Net portfolio investment (BoP, publisher sign)','Current USD'],
  ['b2b_trade_exports','TX.VAL.MRCH.CD.WT','Total merchandise exports','Current USD'],
  ['b2b_trade_imports','TM.VAL.MRCH.CD.WT','Total merchandise imports','Current USD']
].map(([id,code,name,unit])=>({id,code,name,unit,kind:'worldbank-history',frequency:'Annual',category:'Batch 2B context'}));

function b2bTradeUrl(now) {
  const lastYear=new Date(now).getUTCFullYear()-1;
  return 'https://comtradeapi.un.org/public/v1/preview/C/A/HS?'+new URLSearchParams({
    period:[lastYear-1,lastYear].join(','),reporterCode:Object.keys(B2B_TRADE_REPORTERS).join(','),
    partnerCode:'0',partner2Code:'0',flowCode:'M,X',cmdCode:B2B_TRADE_PRODUCTS.join(','),
    customsCode:'C00',motCode:'0',maxRecords:'500'
  });
}

function b2bTradeKey(row){return [row.reporterCode,row.period,row.cmdCode,row.flowCode].join('/');}

function parseBatch2bTrade(data,now=Date.now()) {
  const raw=data?.data;
  if(!Array.isArray(raw)||!raw.length||raw.length>=500)throw Error('Incomplete UN Comtrade preview');
  const lastYear=new Date(now).getUTCFullYear()-1;
  const observations=new Map();
  for(const row of raw){
    if(!Object.hasOwn(B2B_TRADE_REPORTERS,row.reporterCode)||![lastYear,lastYear-1].includes(Number(row.period))
      || !B2B_TRADE_PRODUCTS.includes(row.cmdCode)||!['M','X'].includes(row.flowCode)
      || Number(row.partnerCode)!==0||Number(row.partner2Code)!==0||row.customsCode!=='C00'||Number(row.motCode)!==0
      || row.freqCode!=='A'||row.typeCode!=='C'||row.classificationSearchCode!=='HS'
      || row.isReported!==true|| !Number.isFinite(row.primaryValue)||row.primaryValue<0)continue;
    const key=b2bTradeKey(row);
    if(observations.has(key))throw Error('Ambiguous UN Comtrade reported observations');
    observations.set(key,{reporterCode:Number(row.reporterCode),period:Number(row.period),cmdCode:row.cmdCode,
      flowCode:row.flowCode,primaryValue:row.primaryValue});
  }
  if(!observations.size)throw Error('No verified UN Comtrade observations');
  return [...observations.values()].sort((a,b)=>b2bTradeKey(a).localeCompare(b2bTradeKey(b)));
}

function b2bTradePacket(data,now) {
  return {...B2B_TRADE_FEED,source:b2bTradeUrl(now),retrievedAt:new Date(now).toISOString(),rows:parseBatch2bTrade(data,now)};
}

function b2bValidateTrade(feed,now) {
  if(feed?.source!==b2bTradeUrl(now)||!Array.isArray(feed.rows)||Math.abs(now-Date.parse(feed.retrievedAt))>86400000
    || !Number.isFinite(Date.parse(feed.retrievedAt)))throw Error('Invalid UN Comtrade provenance');
  const normalized=feed.rows.map(row=>({...row,partnerCode:0,partner2Code:0,customsCode:'C00',motCode:0,
    freqCode:'A',typeCode:'C',classificationSearchCode:'HS',isReported:true}));
  return {...B2B_TRADE_FEED,source:feed.source,retrievedAt:feed.retrievedAt,rows:parseBatch2bTrade({data:normalized},now)};
}

EXTRA_FEEDS.push(...B2B_WDI_FEEDS); ICE_FEEDS.push(...B2B_WDI_FEEDS,B2B_TRADE_FEED,B2B_GAS_FEED);
const B2B_TRAIN = ['2026-05-08','2026-09-11'];
const B2B_CHECK = ['2026-09-14','2026-10-30'];
const B2B_STRESS = [0,-1,2,-.1];
const B2B_RISK_IDS = ['SP500','VIXCLS','DGS10'];

const b2bDot = (a,b) => a.reduce((sum,v,i)=>sum+v*b[i],0);
const b2bMean = a => a.reduce((sum,v)=>sum+v,0)/a.length;

function b2bInverse(matrix) {
  const n=matrix.length;
  const rows=matrix.map((r,i)=>[...r,...Array.from({length:n},(_,j)=>+(i===j))]);
  for(let i=0;i<n;i++){
    let pivot=i;
    for(let j=i+1;j<n;j++) if(Math.abs(rows[j][i])>Math.abs(rows[pivot][i])) pivot=j;
    if(Math.abs(rows[pivot][i])<1e-10)return null;
    [rows[i],rows[pivot]]=[rows[pivot],rows[i]];
    const scale=rows[i][i];
    rows[i]=rows[i].map(v=>v/scale);
    for(let j=0;j<n;j++)if(j!==i){
      const multiplier=rows[j][i];
      rows[j]=rows[j].map((v,k)=>v-multiplier*rows[i][k]);
    }
  }
  return rows.map(row=>row.slice(n));
}

function b2bFit(rows,ccy) {
  const scale=[1,...[1,2,3].map(i=>Math.sqrt(b2bMean(rows.map(r=>r.x[i]**2))))];
  if(scale.some(s=>!(s>1e-12)))return null;
  const x=rows.map(r=>r.x.map((v,i)=>v/scale[i]));
  const y=rows.map(r=>r.returns[ccy]);
  const cols=x[0].map((_,i)=>x.map(r=>r[i]));
  const inverse=b2bInverse(cols.map(a=>cols.map(b=>b2bDot(a,b))));
  if(!inverse)return null;
  const rhs=cols.map(c=>b2bDot(c,y));
  const fitted=inverse.map(r=>b2bDot(r,rhs));
  const residual=y.map((v,i)=>v-b2bDot(x[i],fitted));
  const contrast=B2B_STRESS.map((v,i)=>v/scale[i]);
  const influence=inverse.map(r=>b2bDot(r,contrast));
  const errors=residual.map((e,i)=>e*b2bDot(x[i],influence));
  // Newey–West variance of the single preregistered stress contrast.
  let variance=b2bDot(errors,errors);
  for(let lag=1;lag<=5;lag++)variance+=2*(1-lag/6)*b2bDot(errors.slice(lag),errors.slice(0,-lag));
  return {coefficients:fitted.map((v,i)=>v/scale[i]),stress:b2bDot(fitted,contrast),
    standardError:Math.sqrt(Math.max(0,variance)),mean:b2bMean(y)};
}

function b2bCorrelation(rows,ccy) {
  const x=rows.map(r=>r.x[1]), y=rows.map(r=>r.returns[ccy]);
  const mx=b2bMean(x), my=b2bMean(y);
  const a=x.map(v=>v-mx), b=y.map(v=>v-my);
  const den=Math.sqrt(b2bDot(a,a)*b2bDot(b,b));
  return den>0 ? b2bDot(a,b)/den : null;
}

function b2bUniqueDated(rows,dateOf,available) {
  const out=new Map();
  for(const row of rows||[]){
    const date=dateOf(row);
    if(!b2Date(date)||Date.parse(date)>available)continue;
    out.set(date,out.has(date)?null:row);
  }
  return out;
}

function b2bPanel(bundle,core,now,window) {
  const market=B2B_RISK_IDS.map(id=>{
    const f=bundle.feeds[id];
    return b2bUniqueDated(Date.parse(f?.retrievedAt)<=now?f.points:[],p=>p.d,now);
  });
  const feed=bundle.feeds.fx;
  const fx=b2bUniqueDated(Date.parse(feed?.retrievedAt)<=now?feed.history:[],p=>p.date,now);
  const days=[...fx.keys()].filter(d=>d>=window[0]&&d<=window[1]&&fx.get(d)
    && market.every(m=>Number.isFinite(m.get(d)?.v))).sort();
  return days.slice(1).flatMap((d,i)=>{
    const previous=days[i];
    if((Date.parse(d)-Date.parse(previous))/86400000>4)return [];
    const returns=core.map(ccy=>{
      if(ccy==='USD')return 0;
      const a=fx.get(previous).rates?.[ccy],b=fx.get(d).rates?.[ccy];
      return a>0&&b>0 ? 100*Math.log(a/b) : null;
    });
    if(returns.some(r=>r===null))return [];
    const [sp,vix,yield10]=market.map(m=>[m.get(previous).v,m.get(d).v]);
    if(sp.some(v=>v<=0))return [];
    const sum=returns.reduce((n,v)=>n+v,0);
    return [{d,x:[1,100*Math.log(sp[1]/sp[0]),vix[1]-vix[0],yield10[1]-yield10[0]],
      returns:Object.fromEntries(core.map((ccy,j)=>[ccy,(returns[j]*core.length-sum)/(core.length-1)])),
      regime:vix[0]<15?'Low':vix[0]<25?'Intermediate':'High'}];
  });
}

function batch2bRisk(record,core) {
  const now=Date.parse(record.analysis.generatedAt);
  const train=b2bPanel(record.bundle,core,now,B2B_TRAIN),check=b2bPanel(record.bundle,core,now,B2B_CHECK);
  return {trainWindow:B2B_TRAIN,checkWindow:B2B_CHECK,trainRows:train.length,checkRows:check.length,
    series:['FX reference history','S&P 500','VIX','US Treasury 10Y'],fxSource:record.bundle.feeds.fx?.source||null,retainedFx:record.bundle.status?.fx?.ok===false,
    rows:core.map(ccy=>{
      const e=record.analysis.economies.find(x=>x.ccy===ccy);
      const incumbent=e?.factors.external.features.find(f=>f.name==='Global risk exposure proxy')?.sensitivity ?? null;
      const result={ccy,incumbent,applied:incumbent,eligible:false};
      if(train.length<75||check.length<25)return {...result,reason:'Insufficient aligned history'};
      const fit=b2bFit(train,ccy),validation=b2bFit(check,ccy);
      if(!fit||!validation)return {...result,reason:'Singular exposure fit'};
      const rmse=rows=>Math.sqrt(b2bMean(rows.map(r=>(r.returns[ccy]-b2bDot(fit.coefficients,r.x))**2)));
      const modelRmse=rmse(check),meanRmse=Math.sqrt(b2bMean(check.map(r=>(r.returns[ccy]-fit.mean)**2)));
      const eligible=Math.sign(fit.stress)===Math.sign(validation.stress)&&fit.standardError>0
        && Math.abs(fit.stress)>1.96*fit.standardError&&modelRmse<meanRmse;
      return {...result,eligible,applied:eligible?Math.max(-1,Math.min(1,fit.stress/.25)):incumbent,
        coefficients:fit.coefficients,stress:fit.stress,stressSE:fit.standardError,checkStress:validation.stress,
        modelRmse,meanRmse,trainEquityCorrelation:b2bCorrelation(train,ccy),checkEquityCorrelation:b2bCorrelation(check,ccy),
        regimes:['Low','Intermediate','High'].map(regime=>{
          const group=check.filter(r=>r.regime===regime);
          return {regime,n:group.length,rmse:group.length>=10?rmse(group):null};
        }),reason:eligible?'Sensitivity passed diagnostic gate':'Retained fixed sensitivity'};
    })};
}

function b2bSeen(bundle,id,now){
  const f=bundle.feeds[id];
  return f?.source && Date.parse(f.retrievedAt)<=now ? f : null;
}

function b2bLast(points,now){
  return (points||[]).filter(p=>b2Date(p.d)&&Date.parse(p.d)<=now&&Number.isFinite(p.v))
    .sort((a,b)=>a.d.localeCompare(b.d)).at(-1)||null;
}

function b2bMetric(bundle,id,now,points,unit,maxAge=900){
  const feed=b2bSeen(bundle,id,now);
  if(!feed)return null;
  const point=b2bLast(points??feed.points,now);
  if(!point)return null;
  const annual=feed.frequency==='Annual'||feed.kind==='worldbank-history'||B2B_WDI_FEEDS.some(f=>f.id===id);
  const referenceEnd=Date.parse(annual?point.d.slice(0,4)+'-12-31':point.d);
  return {...point,unit:unit||feed.unit||null,source:feed.source,retrievedAt:feed.retrievedAt,
    current:bundle.status?.[id]?.ok===true&&now>=referenceEnd&&now-referenceEnd<=maxAge*86400000};
}

function b2bPeriodChange(points,point,years,percent){
  if(!point)return null;
  const target=String(Number(point.d.slice(0,4))-years)+point.d.slice(4);
  const previous=points?.find(p=>p.d===target&&Number.isFinite(p.v));
  return previous && (!percent||previous.v>0) ? percent ? 100*(point.v/previous.v-1) : point.v-previous.v : null;
}

function b2bCurrencyMetric(bundle,id,ccy,now){
  return b2bMetric(bundle,id,now,bundle.feeds[id]?.byCurrency?.[ccy]||[]);
}

function b2bMoney(bundle,ccy,now){
  const national={USD:['M2SL',null,'M2'],EUR:['ecb_m3',null,'M3'],CAD:['boc_money',null,'M2++'],
    AUD:['rba_money','DMABMS','Broad money'],CHF:['snb_money','GM3','M3']}[ccy];
  const assetPoints=bundle.feeds.bis_assets_gdp?.series?.find(s=>s.id==='cb_assets_gdp_'+ccy)?.points||[];
  const assets=b2bMetric(bundle,'bis_assets_gdp',now,assetPoints,'% GDP',240);
  const f=national&&b2bSeen(bundle,national[0],now);
  const component=national?.[1]&&f?.series?.find(s=>s.id===national[1]);
  const points=national?.[1]?component?.points||[]:f?.points;
  const nationalLevel=f?b2bMetric(bundle,national[0],now,points,component?.unit||f.unit,100):null;
  const nationalAsset={
    USD:['WALCL',null,'Millions USD'],EUR:['ecb_assets',null,'Millions EUR'],
    CAD:['boc_assets',null,'Millions CAD'],JPY:['JPNASSETS',null,'100 million JPY'],
    AUD:['rba_assets','ARBAATAW','Millions AUD']
  }[ccy];
  const bank=nationalAsset&&bundle.feeds[nationalAsset[0]];
  const bankPoints=nationalAsset?.[1]?bank?.series?.find(s=>s.id===nationalAsset[1])?.points||[]:bank?.points;
  const bankLevel=bank?b2bMetric(bundle,nationalAsset[0],now,bankPoints,nationalAsset[2],100):null;
  return {assets,bankLevel,assetsYearChange:b2bPeriodChange(assetPoints,assets,1,false),
    nationalLevel,nationalDefinition:national?.[2]||null,nationalGrowth:b2bPeriodChange(points,nationalLevel,1,true),
    broadMoneyGdp:b2bCurrencyMetric(bundle,'b2b_money_gdp',ccy,now),
    broadMoneyGrowth:b2bCurrencyMetric(bundle,'b2b_money_growth',ccy,now)};
}

const B2B_CURVES={
  USD:['curve_USD','UST_2Y','UST_10Y','curve_USD_real','UST_REAL_10Y','US Treasury par'],
  CAD:['curve_CAD','BD.CDN.2YR.DQ.YLD','BD.CDN.10YR.DQ.YLD',null,null,'Canada benchmark bonds'],
  EUR:['curve_EUR','ECB_SR_2Y','ECB_SR_10Y',null,null,'ECB AAA zero coupon'],
  AUD:['curve_AUD','FCMYGBAG2D','FCMYGBAG10D','curve_AUD','FCMYGBAGID','RBA government bond yields'],
  JPY:['curve_JPY','JGB_2Y','JGB_10Y',null,null,'Japan MOF constant maturity'],
  GBP:['boe_fitted_curves','BOE_GILT_NOM_2Y','BOE_GILT_NOM_10Y','boe_fitted_curves','BOE_GILT_REAL_10Y','BoE gilt zero coupon']
};

function b2bCurve(bundle,ccy,policy,now){
  const [id,two,ten,realId,real,basis]=B2B_CURVES[ccy]||[];
  const points=(feed,key)=>bundle.feeds[feed]?.series?.find(s=>s.id===key)?.points||[];
  const y2=b2bMetric(bundle,id,now,points(id,two),'%',12);
  const y10=b2bMetric(bundle,id,now,points(id,ten),'%',12);
  const real10=b2bMetric(bundle,realId,now,points(realId,real),'%',12);
  const policyAge=(Date.parse(y2?.d)-Date.parse(policy?.d))/86400000;
  const policySpread=y2?.current&&Number.isFinite(policy?.v)&&policyAge>=0&&policyAge<=12?y2.v-policy.v:null;
  return {y2,y10,real10,basis:basis||null,slope:y2?.current&&y10?.current&&y2.d===y10.d?y10.v-y2.v:null,
    policySpread,policySpreadLabel:'2Y government yield minus policy-rate observation (pp). Yield-spread proxy, not OIS.'};
}

function b2bTrade(bundle,ccy,now){
  const feed=b2bSeen(bundle,B2B_TRADE_FEED.id,now);
  const reporter=Object.keys(B2B_TRADE_REPORTERS).find(key=>B2B_TRADE_REPORTERS[key]===ccy);
  const rows=feed?.rows?.filter(r=>r.reporterCode===Number(reporter))||[];
  const read=(year,code,flow)=>rows.find(r=>r.period===year&&r.cmdCode===code&&r.flowCode===flow)?.primaryValue??null;
  const year=[...new Set(rows.map(r=>r.period))].sort((a,b)=>b-a).find(y=>rows.filter(r=>r.period===y).length>=2);
  const sum=(...a)=>a.every(Number.isFinite)?a.reduce((n,v)=>n+v,0):null;
  const oilExports=read(year,'2709','X'),oilImports=read(year,'2709','M');
  const gasExports=sum(read(year,'271111','X'),read(year,'271121','X'));
  const gasImports=sum(read(year,'271111','M'),read(year,'271121','M'));
  const matchedGdp=b2bMetric(bundle,'b2b_gdp_usd',now,(bundle.feeds.b2b_gdp_usd?.byCurrency?.[ccy]||[]).filter(p=>p.d.slice(0,4)===String(year)));
  const asPct=(x,m)=>Number.isFinite(x)&&Number.isFinite(m)&&matchedGdp?.v>0&&matchedGdp.d.slice(0,4)===String(year)
    ?100*(x-m)/matchedGdp.v:null;
  const exports=b2bCurrencyMetric(bundle,'b2b_trade_exports',ccy,now),imports=b2bCurrencyMetric(bundle,'b2b_trade_imports',ccy,now);
  const tot=b2bCurrencyMetric(bundle,'b2b_tot',ccy,now);
  const reportedExports=read(year,'TOTAL','X'), reportedImports=read(year,'TOTAL','M');
  return {year:year??null,reportedExports,reportedImports,normalizationGdp:matchedGdp,source:feed?.source||null,retrievedAt:feed?.retrievedAt||null,
    oilExports,oilImports,gasExports,gasImports,oilNetGdp:asPct(oilExports,oilImports),gasNetGdp:asPct(gasExports,gasImports),
    exports,imports,balance:exports&&imports&&exports.d===imports.d?exports.v-imports.v:null,
    reportedBalance:Number.isFinite(reportedExports)&&Number.isFinite(reportedImports)?reportedExports-reportedImports:null,
    tot,totGrowth:b2bPeriodChange(bundle.feeds.b2b_tot?.byCurrency?.[ccy],tot,1,true)};
}

function b2bForward(bundle,now){
  const releases=['fed_projections','ecb_sma'].flatMap(id=>{
    const f=b2bSeen(bundle,id,now);
    const datedEcbEdition=id==='ecb_sma' && f?.source==='https://www.ecb.europa.eu/stats/ecb_surveys/sma/shared/pdf/ecb.smar261030_october.en.csv';
    const publicationDate=f?.publicationDate || (datedEcbEdition?'2026-10-30':null);
    const knownBy=datedEcbEdition && !f.publicationDate?'2026-10-31T00:00:00Z':publicationDate;
    if(!f||!(Date.parse(knownBy)<=now)||!Array.isArray(f.projections))return [];
    return [{id,source:f.source,publicationDate,retrievedAt:f.retrievedAt,
      publicationSource:datedEcbEdition?'https://www.ecb.europa.eu/stats/ecb_surveys/sma/html/index.en.html':f.source,
      type:id==='fed_projections'?'Federal Reserve participant projections':'ECB analyst survey medians',
      values:f.projections.filter(p=>Number.isFinite(p.v)).slice(0,10)}];
  });
  const oisFeed=b2bSeen(bundle,'boe_fitted_curves',now);
  const ois=(oisFeed?.series||[]).filter(s=>/^BOE_OIS_(FWD|SPOT)_(3|6|12)M$/.test(s.id)).flatMap(s=>{
    const point=b2bMetric(bundle,'boe_fitted_curves',now,s.points,'%',12);
    return point?[{...point,series:s.id,type:s.curve}]:[];
  });
  const fixings=Object.keys(bundle.feeds).filter(id=>id.startsWith('fixing_')).flatMap(id=>{
    const f=b2bSeen(bundle,id,now),point=b2bMetric(bundle,id,now,f?.points,'%',12);
    return point?[{...point,id,benchmark:f.benchmark,ccy:f.ccy,basis:f.basis}]:[];
  });
  const calendar=b2bSeen(bundle,'calendar',now);
  const catalysts=(calendar?.events||[]).filter(e=>Date.parse(e.date)>now).slice(0,25);
  const news=b2bSeen(bundle,'news_un',now);
  return {releases,ois,fixings,catalysts,catalystSource:calendar?.source||null,catalystRetrievedAt:calendar?.retrievedAt||null,
    geopolitical:(news?.news||[]).filter(n=>Date.parse(n.publishedAt)<=now).slice(0,8),
    coverage:{ois:'Published BoE fitted curves where available',stir:'Exchange-implied STIR unavailable',
      surprises:'Existing Lab release ledger. Actuals require archived consensus and attestation. No assumed surprise.',
      funding:'Observed overnight fixings only'}};
}

function buildBatch2b(record,core,model,prior){
  const b=record.bundle, now=Date.parse(record.analysis.generatedAt), risk=batch2bRisk(record,core);
  const context=core.map(ccy=>{
    const e=record.analysis.economies.find(e=>e.ccy===ccy);
    const fiscal=b2bCurrencyMetric(b,'fiscal_debt',ccy,now);
    const interest=b2bCurrencyMetric(b,'fiscal_interest_lcu',ccy,now);
    const gdp=b2bMetric(b,'nominal_gdp_lcu',now,(b.feeds.nominal_gdp_lcu?.byCurrency?.[ccy]||[]).filter(p=>p.d===interest?.d));
    const ca=b2bMetric(b,'external_current',now,[b.feeds.external_current?.rows?.[ccy]].filter(Boolean),'% GDP');
    const fdi=b2bMetric(b,'external_fdi',now,[b.feeds.external_fdi?.rows?.[ccy]].filter(Boolean),'% GDP');
    return {ccy,money:b2bMoney(b,ccy,now),curve:b2bCurve(b,ccy,prior.policy.find(row=>row.ccy===ccy)?.freshness==='Policy differs from last verified decision'?null:e?.observations.policy,now),
      policy:e?.observations.policy??null,trade:b2bTrade(b,ccy,now),fiscal,interestGdp:interest&&gdp?.v>0&&interest.d===gdp.d
        ?{d:gdp.d,v:100*interest.v/gdp.v,unit:'% GDP',source:interest.source,denominatorSource:gdp.source}:null,ca,fdi,portfolio:b2bCurrencyMetric(b,'b2b_portfolio',ccy,now)};
  });
  for(const row of context){
    const current=row.money.broadMoneyGrowth;
    const peers=context.filter(other=>other!==row).map(other=>other.money.broadMoneyGrowth)
      .filter(p=>p?.current&&p.d===current?.d);
    row.money.relativeGrowth=current?.current&&peers.length>=3
      ? {value:current.v-b2bMean(peers.map(p=>p.v)),peers:peers.length,date:current.d}:null;
  }
  const scores=prior.currencies.map(p=>{
    const r=risk.rows.find(r=>r.ccy===p.ccy), pressure=record.analysis.regime?.riskPressure;
    const feature=record.analysis.economies.find(e=>e.ccy===p.ccy)?.factors.external.features.find(f=>f.name==='Global risk exposure proxy');
    const changed=r?.eligible&&Number.isFinite(pressure)&&Number.isFinite(feature?.score)&&p.coverage>0;
    const change=changed?(Math.max(0,Math.min(100,50+pressure*r.applied))-feature.score)*model.weights.external*feature.weight/(100*p.coverage):0;
    return {ccy:p.ccy,production:p.productionScore,shadow2a:p.candidateScore,
      shadow2b:Number.isFinite(p.candidateScore)?p.candidateScore+change:null,eligible:p.eligible,riskReplacement:!!changed};
  });
  return {runId:record.runId,asOf:record.analysis.generatedAt,modelVersion:record.analysis.modelVersion,
    version:'ICE-SHADOW-2B.1',validated:false,risk,context,scores,forward:b2bForward(b,now),
    energy:{brent:b2bMetric(b,'DCOILBRENTEU',now,null,'USD/barrel',12),
      henryHub:b2bMetric(b,'DHHNGSP',now,null,'USD/MMBtu',12),note:'Benchmark prices, not country retail or landed energy costs.'}};
}

const BATCH2B_FINGERPRINT="1f0cb6d7c65647e8c4faa85ea4a9342d76ebf17f7acc2eb038ac0de0eca5da89";
function batch2bForRecord(record){
  const prior=record.batch2a?.fingerprint===BATCH2A_FINGERPRINT?record.batch2a:batch2aForRecord(record);
  return {...buildBatch2b(record,ICE_CORE,ICE_MODEL,prior),fingerprint:BATCH2B_FINGERPRINT};
}

async function batch2bArchive(record,env){
  if(!record.batch2b||Date.parse(record.batch2b.asOf)<Date.parse('2026-11-09T02:00:00Z'))return;
  await labPutOnce(env.BUCKET,'validation/shadow-2b/'+BATCH2B_FINGERPRINT+'/'+record.batch2b.asOf.slice(0,10)+'.json',
    {...record.batch2b,recordedAt:new Date().toISOString(),consensusLedger:'validation/lab/consensus/',actualsLedger:'validation/lab/actuals/'});
}

async function batch2bApi(request,env){
  const headers={'Cache-Control':'no-store'};
  if(request.method!=='GET')return Response.json({error:'Use GET'},{status:405,headers});
  if(!env.BUCKET)return Response.json({error:'Saved evidence unavailable'},{status:503,headers});
  const record=await iceRead(env.BUCKET,'ice/latest.json');
  if(!record)return Response.json({version:'ICE-SHADOW-2B.1',status:'No saved run'},{headers});
  const recorded=record.batch2b?.fingerprint===BATCH2B_FINGERPRINT;
  const data=recorded?record.batch2b:batch2bForRecord(record);
  return Response.json({...data,recorded,status:recorded?'Recorded alongside the saved run':'Diagnostic from archived inputs'},{headers});
}

const B3_ALTERNATIVES=[
  [25,15,15,10,15,20],[35,15,10,10,15,15],[30,15,15,10,20,10],[35,20,15,10,20,0],Array(6).fill(100/6)
];
const B3_FACTORS=['rates','inflation','growth','labour','external','positioning'];
const B3_THRESHOLD=12;

function b3Weights(values){return Object.fromEntries(B3_FACTORS.map((id,i)=>[id,values[i]]));}

function b3Weighted(e,weights,change){
  let sum=0,total=0;
  for(const [id,f] of Object.entries(e.factors)){
    let {score,coverage}=f;
    if(change?.id===id){
      const features=f.features.map((x,i)=>i===change.index?{...x,score:change.score}:x);
      const used=features.filter(x=>Number.isFinite(x.score));
      const usedWeight=used.reduce((n,x)=>n+x.weight,0);
      const allWeight=features.reduce((n,x)=>n+x.weight,0);
      score=usedWeight?used.reduce((n,x)=>n+x.score*x.weight,0)/usedWeight:null;
      coverage=allWeight?100*usedWeight/allWeight:0;
    }
    if(!Number.isFinite(score))continue;
    const weight=weights[id]*coverage/100;
    sum+=score*weight;
    total+=weight;
  }
  return total?sum/total:null;
}

function b3Direction(n,threshold=B3_THRESHOLD){
  return !Number.isFinite(n)?null:n>=threshold?1:n<=-threshold?-1:0;
}

function b3Delta(a,b){return Number.isFinite(a)&&Number.isFinite(b)?a-b:null;}

function b3Classify(eligible,margin,proportion,n){
  if(!eligible||!Number.isFinite(margin))return 'Insufficient Evidence';
  if(n<8||!Number.isFinite(proportion))return 'Unclassified';
  if(margin<1.5||proportion<.70)return 'Fragile';
  return proportion>=.90?'Robust':'Moderate';
}

function b3CurrencyScenarios(record,e,model){
  const results={};
  const weights=model.weights;
  B3_ALTERNATIVES.forEach((v,i)=>{results['weights-'+(i+1)]=b3Weighted(e,b3Weights(v));});
  for(const id of B3_FACTORS)for(const f of [.8,1.2]){
    if(Number.isFinite(e.factors[id]?.score))results[id+'-weight-'+f]=b3Weighted(e,{...weights,[id]:weights[id]*f});
  }
  if(Number.isFinite(e.factors.positioning?.score)){
    results['positioning-half']=b3Weighted(e,{...weights,positioning:weights.positioning*.5});
    results['positioning-excluded']=b3Weighted(e,{...weights,positioning:0});
  }
  for(const [id,f] of Object.entries(e.factors))f.features.forEach((feature,index)=>{
    if((id==='external'||id==='positioning'||(id==='rates'&&index===3))&&Number.isFinite(feature.score)){
      results['missing-'+e.ccy+'-'+id+'-'+index]=b3Weighted(e,weights,{id,index,score:null});
    }
    if(feature.name==='Global risk exposure proxy'&&Number.isFinite(feature.score)&&Number.isFinite(record.analysis.regime?.riskPressure)){
      for(const f of [.75,1.25])results['risk-'+f]=b3Weighted(e,weights,{id,index,score:Math.max(0,Math.min(100,
        50+record.analysis.regime.riskPressure*feature.sensitivity*f))});
    }
  });
  const a=record.batch2a?.currencies.find(x=>x.ccy===e.ccy);
  const b=record.batch2b?.scores.find(x=>x.ccy===e.ccy);
  if(a?.eligible&&Number.isFinite(a.candidateScore))results['shadow-2a']=a.candidateScore;
  if(b?.eligible&&Number.isFinite(b.shadow2b))results['shadow-2b']=b.shadow2b;
  return results;
}

function buildBatch3Robustness(record,model,releaseEvidence,eligibleCurrency){
  const currencies=record.analysis.economies.map(e=>{
    const evidence=releaseEvidence.filter(x=>x.ccy===e.ccy&&x.mandatory);
    const reason=eligibleCurrency(e,releaseEvidence);
    const fundamental=b3Weighted(e,{...model.weights,positioning:0});
    const variants=b3CurrencyScenarios(record,e,model);
    const factors=Object.entries(e.factors).map(([id,f])=>({id,score:f.score,coverage:f.coverage,
      contribution:Number.isFinite(f.score)&&e.coverage>0?(f.score-50)*model.weights[id]*f.coverage/(100*e.coverage):null}));
    return {ccy:e.ccy,score:e.score,fundamental,positioningEffect:b3Delta(e.score,fundamental),factors,variants,
      evidence:{coverage:e.coverage,fresh:evidence.filter(r=>r.freshness==='Current').length,
        verified:evidence.filter(r=>r.evidence==='Verified').length,required:4,eligible:!reason,reason}};
  });
  const pairs=record.analysis.pairs.map(p=>{
    const a=currencies.find(e=>e.ccy===p.base),b=currencies.find(e=>e.ccy===p.quote);
    const eligible=!!(a?.evidence.eligible&&b?.evidence.eligible&&p.critical&&Number.isFinite(p.delta));
    const margin=Number.isFinite(p.delta)?Math.abs(Math.abs(p.delta)-model.pairThreshold):null;
    const original=b3Direction(p.delta,model.pairThreshold);
    const variants=[];
    if(eligible)for(const id of new Set([...Object.keys(a.variants),...Object.keys(b.variants)])){
      const oneSided=id.startsWith('missing-')||id.startsWith('risk-')||id.startsWith('positioning-')||id.includes('-weight-');
      if(id==='shadow-2b'&&a.variants[id]===a.variants['shadow-2a']&&b.variants[id]===b.variants['shadow-2a'])continue;
      if(!oneSided&&(!Object.hasOwn(a.variants,id)||!Object.hasOwn(b.variants,id)))continue;
      const delta=b3Delta(Object.hasOwn(a.variants,id)?a.variants[id]:a.score,
        Object.hasOwn(b.variants,id)?b.variants[id]:b.score);
      if(Number.isFinite(delta))variants.push({id,delta,preserves:b3Direction(delta,model.pairThreshold)===original});
    }
    const preservation=variants.length?variants.filter(x=>x.preserves).length/variants.length:null;
    return {base:p.base,quote:p.quote,delta:p.delta,bias:p.bias,threshold:model.pairThreshold,margin,eligible,
      fundamental:b3Delta(a?.fundamental,b?.fundamental),preservation,variants,
      robustness:b3Classify(eligible,margin,preservation,variants.length),
      range:variants.length?[Math.min(...variants.map(v=>v.delta)),Math.max(...variants.map(v=>v.delta))]:null};
  });
  return {currencies,pairs,withheldScenarios:[
    'Alternative vintages require independently verified like-for-like observations available at the decision time.',
    'Regime coefficient perturbations require independently supported regime fits. No regime estimate is imputed.'
  ],forecastReliability:null};
}

const B3_FREEZE='2026-11-09T02:00:00Z';
const B3_CURRENCIES=['USD','EUR','GBP','JPY','CHF','CAD','AUD','NZD'];
const B3_CANDIDATES=['weights-1','weights-2','weights-3','weights-4','weights-5','shadow-2a','shadow-2b'];
const B3_BENCHMARKS=['incumbent','carry','momentum','equal','neutral'];
const B3_HORIZONS=[10,20];
const B3_PAIR_ORDER=['EUR','GBP','AUD','NZD','USD','CAD','CHF','JPY'];
const B3_SHA=/^[a-f0-9]{64}$/;
const B3_ECB='https://data-api.ecb.europa.eu/service/data/EXR/D.USD+GBP+JPY+CHF+CAD+AUD+NZD.EUR.SP00.A';
const B3_DAY=86400000;
const b3Mean=a=>a.length?a.reduce((n,v)=>n+v,0)/a.length:null;
const b3Finite=x=>Number.isFinite(x);
const b3Iso=ms=>new Date(ms).toISOString().slice(0,10);
const b3Day=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&b3Finite(Date.parse(d))&&b3Iso(Date.parse(d))===d;
const b3Full=r=>B3_CURRENCIES.slice(1).every(c=>b3Finite(r?.[c])&&r[c]>0);
const b3Rate=(rates,c)=>c==='USD'?1:rates[c];
const b3Cross=(rates,p)=>b3Rate(rates,p.quote)/b3Rate(rates,p.base);

// ECB reference rates follow TARGET closing days.
function b3ReferenceDay(date){
  if(!b3Day(date))return false;
  const d=new Date(date+'T00:00:00Z'), year=d.getUTCFullYear(), weekday=d.getUTCDay();
  if(weekday===0||weekday===6||['01-01','05-01','12-25','12-26'].includes(date.slice(5)))return false;
  // Gregorian Easter Sunday (Meeus/Jones/Butcher computus).
  const a=year%19,b=Math.floor(year/100),c=year%100,h=(19*a+b-Math.floor(b/4)-Math.floor((b-Math.floor((b+8)/25)+1)/3)+15)%30;
  const l=(32+2*(b%4)+2*Math.floor(c/4)-h-c%4)%7,m=Math.floor((a+11*h+22*l)/451);
  const e=h+l-7*m+114;
  const easter=Date.UTC(year,Math.floor(e/31)-1,e%31+1);
  return +d!==easter-2*B3_DAY&&+d!==easter+B3_DAY;
}

function b3NoGap(from,to){
  for(let day=Date.parse(from)+B3_DAY;day<Date.parse(to);day+=B3_DAY)if(b3ReferenceDay(b3Iso(day)))return false;
  return true;
}

function b3TrustedFx(f){
  return f?.provider==='European Central Bank'&&typeof f.source==='string'
    && f.source.startsWith(B3_ECB+'?')&&b3Finite(Date.parse(f.retrievedAt));
}

function b3PriceKnown(date,retrievedAt){
  const day=retrievedAt.slice(0,10);
  return date<day || (date===day && Date.parse(retrievedAt)>=Date.parse(date+'T16:00:00Z'));
}

function b3PricePack(record){
  const f=record.bundle.feeds.fx, at=record.analysis.generatedAt;
  if(!b3TrustedFx(f)||record.bundle.status?.fx?.ok!==true||Date.parse(f.retrievedAt)>Date.parse(at))return null;
  const earliest=Math.max(Date.parse(B3_FREEZE.slice(0,10)),Date.parse(at)-10*B3_DAY);
  const rows=(f.history||[]).filter(r=>b3ReferenceDay(r.date)&&Date.parse(r.date)>=earliest&&b3PriceKnown(r.date,f.retrievedAt)).sort((a,b)=>a.date.localeCompare(b.date));
  if(!rows.length)return null;
  return {at,retrievedAt:f.retrievedAt,source:f.source,provider:f.provider,rows};
}

function b3Momentum(record,pairs){
  const f=record.bundle.feeds.fx, at=record.analysis.generatedAt;
  if(!b3TrustedFx(f)||record.bundle.status?.fx?.ok!==true||Date.parse(f.retrievedAt)>Date.parse(at))return {};
  const rows=(f.history||[]).filter(r=>b3ReferenceDay(r.date)&&r.date<at.slice(0,10)).sort((a,b)=>a.date.localeCompare(b.date)).slice(-21);
  if(rows.length!==21||new Set(rows.map(r=>r.date)).size!==21||rows.some((r,i)=>!b3Full(r.rates)||(i>0&&!b3NoGap(rows[i-1].date,r.date)))
    ||!b3NoGap(rows.at(-1).date,at.slice(0,10)))return {};
  const first=rows[0].rates,last=rows.at(-1).rates;
  return Object.fromEntries(pairs.map(p=>[p.base+p.quote,Math.sign(Math.log(b3Cross(last,p)/b3Cross(first,p)))]));
}

function b3Prices(packs,asOf){
  const known=new Map();
  for(const p of [...packs].filter(x=>b3TrustedFx(x)&&Date.parse(x.retrievedAt)<=Date.parse(x.at)&&Date.parse(x.at)<=Date.parse(x.recordedAt)
    && Date.parse(x.recordedAt)<=asOf && x.at.slice(0,10)===x.recordedAt.slice(0,10))
    .sort((a,b)=>a.at.localeCompare(b.at)||a.retrievedAt.localeCompare(b.retrievedAt))){
    const unique=new Map();
    for(const r of p.rows||[]){
      if(!b3ReferenceDay(r.date)||r.date<B3_FREEZE.slice(0,10)||!b3PriceKnown(r.date,p.retrievedAt))continue;
      unique.set(r.date,unique.has(r.date)?null:r.rates);
    }
    for(const [date,rates] of unique)if(!known.has(date))known.set(date,{date,rates:b3Full(rates)?rates:null,
      retrievedAt:p.retrievedAt,source:p.source,revision:'First archived publisher retrieval'});
  }
  return [...known.values()].sort((a,b)=>a.date.localeCompare(b.date));
}

function b3Windows(decisions,prices,horizon,cutoff){
  const windows=[];
  let lastExit='',excluded=0,pending=0;
  let startIndex=0;
  for(const d of decisions){
    const day=d.at.slice(0,10);
    while(startIndex<prices.length&&prices[startIndex].date<=day)startIndex++;
    const entry=prices[startIndex],exit=prices[startIndex+horizon];
    if(!entry||!exit||exit.date>cutoff||exit.retrievedAt.slice(0,10)>cutoff){pending++;continue;}
    if(entry.date<=lastExit)continue;
    const span=prices.slice(startIndex,startIndex+horizon+1);
    if(!span.every((p,i)=>p.rates&&b3NoGap(i?span[i-1].date:day,p.date))){excluded++;continue;}
    windows.push({decision:d,entry,exit});
    lastExit=exit.date;
  }
  return {windows,excluded,pending};
}

function b3MonthEnds(start,asOf){
  const d=new Date(Date.parse(start));
  const min=Date.UTC(d.getUTCFullYear()+1,d.getUTCMonth(),Math.min(d.getUTCDate(),
    new Date(Date.UTC(d.getUTCFullYear()+1,d.getUTCMonth()+1,0)).getUTCDate()));
  const ends=[];
  const t=new Date(min);
  for(let i=0;i<1200;i++){
    const end=Date.UTC(t.getUTCFullYear(),t.getUTCMonth()+i+1,0);
    if(end+B3_DAY>asOf)break;
    if(end>=min)ends.push(b3Iso(end));
  }
  return ends;
}

function b3Cohort(decisions,prices,strategy,asOf){
  const first=decisions.find(d=>d.pairs.some(p=>[-1,0,1].includes(p.actions?.[strategy])));
  if(!first)return {strategy,state:'Awaiting first eligible capture',start:null,horizons:[]};
  const eligible=decisions.filter(d=>d.at>=first.at);
  const today=b3Iso(asOf);
  const select=end=>B3_HORIZONS.map(horizon=>({horizon,...b3Windows(eligible.filter(d=>d.at.slice(0,10)<=end),prices,horizon,end)}));
  let end=null, partitions=select(today);
  for(const monthEnd of b3MonthEnds(first.at,asOf)){
    const split=select(monthEnd);
    const regimes=new Set(split.flatMap(h=>h.windows.map(w=>w.decision.regime)).filter(r=>['Low','Intermediate','High'].includes(r)));
    if(split.every(h=>h.windows.length>=30)&&regimes.size>=2){
      end=monthEnd;partitions=split;break;
    }
  }
  return {strategy,state:end?'Ready for one final evaluation':'Collecting prospective evidence',start:first.at,end,partitions,
    horizons:partitions.map(p=>({horizon:p.horizon,independentDates:p.windows.length,missingPanels:p.excluded,pending:p.pending,
      regimes:Object.fromEntries(['Low','Intermediate','High','Unclassified'].map(r=>[r,p.windows.filter(w=>w.decision.regime===r).length]))}))};
}

function b3BlockInference(values){
  if(values.length<30||values.some(x=>!b3Finite(x)))return null;
  const observed=b3Mean(values), draws=[], size=values.length, last=size-4;
  let seed=271026, exceeded=0;
  for(let n=0;n<10000;n++){
    let sum=0;
    for(let j=0;j<size;j+=4){
      seed=(1664525*seed+1013904223)>>>0;
      const begin=Math.floor(seed/4294967296*(last+1));
      for(let k=0;k<Math.min(4,size-j);k++)sum+=values[begin+k];
    }
    const average=sum/size;
    draws.push(average);
    if(average-observed>=observed)exceeded++;
  }
  draws.sort((a,b)=>a-b);
  return {low:draws[249],high:draws[9749],p:(exceeded+1)/10001,dates:size,blockLength:4,blocks:Math.floor(size/4),replicates:10000};
}

function b3Holm(values){
  const ranks=values.map((p,i)=>({p:p??1,i})).sort((a,b)=>a.p-b.p);
  let previous=0;
  const adjusted=[];
  ranks.forEach(({p,i},j)=>{previous=Math.min(1,Math.max(previous,p*(values.length-j)));adjusted[i]=previous;});
  return adjusted;
}

function b3Ranks(xs){return xs.map(x=>xs.filter(y=>y<x).length+(xs.filter(y=>y===x).length+1)/2);}
function b3RankCorrelation(a,b){
  if(a.length<5)return null;
  const x=b3Ranks(a),y=b3Ranks(b),center=(x.length+1)/2;
  const xx=x.reduce((n,v)=>n+(v-center)**2,0),yy=y.reduce((n,v)=>n+(v-center)**2,0);
  return xx&&yy?x.reduce((n,v,i)=>n+(v-center)*(y[i]-center),0)/Math.sqrt(xx*yy):null;
}
function b3Median(a){const s=a.filter(b3Finite).sort((x,y)=>x-y);return s.length?b3Mean(s.slice((s.length-1)>>1,(s.length>>1)+1)):null;}

function b3Outcomes(window,strategy){
  const {decision,entry,exit}=window;
  const currencyReturns=Object.fromEntries(B3_CURRENCIES.map(c=>{
    const outcome=b3Mean(B3_CURRENCIES.filter(q=>q!==c).map(q=>100*Math.log(b3Cross(exit.rates,{base:c,quote:q})/b3Cross(entry.rates,{base:c,quote:q}))));
    return [c,outcome];
  }));
  const pairs=decision.pairs.map(p=>{
    const gross=100*Math.log(b3Cross(exit.rates,p)/b3Cross(entry.rates,p));
    const action=p.actions?.[strategy];
    return {gross,action:[-1,0,1].includes(action)?action:null};
  });
  const currencies=B3_CURRENCIES.map(ccy=>({value:decision.currencies?.[strategy]?.[ccy],baseline:decision.currencies?.incumbent?.[ccy],actual:currencyReturns[ccy]}));
  const usable=currencies.filter(c=>b3Finite(c.value));
  const matched=usable.filter(c=>b3Finite(c.baseline));
  return {date:decision.at.slice(0,10),regime:decision.regime,pairs, currencies:usable,
    rankIC:b3RankCorrelation(usable.map(c=>c.value),usable.map(c=>c.actual)),
    rankStability:b3RankCorrelation(matched.map(c=>c.value),matched.map(c=>c.baseline))};
}

function b3DateNet(row,cost){
  return b3Mean(row.pairs.map(p=>p.action?p.gross*p.action-cost:0));
}

function b3Metrics(rows,inferenceReady){
  const pairs=rows.flatMap(r=>r.pairs), active=pairs.filter(p=>p.action), nonflat=active.filter(p=>p.gross!==0);
  const currency=rows.flatMap(r=>r.currencies).filter(c=>(c.value>52||c.value<48)&&c.actual!==0);
  const net=rows.map(r=>b3DateNet(r,.05));
  const sorted=[...net].sort((a,b)=>a-b);
  let total=0,peak=0,drawdown=0;
  for(const v of net){total+=v;peak=Math.max(total,peak);drawdown=Math.max(drawdown,100*(1-Math.exp((total-peak)/100)));}
  return {independentDates:rows.length,opportunities:pairs.length,active:active.length,
    eligible:pairs.filter(p=>p.action!==null).length,abstentions:pairs.filter(p=>p.action===null).length,
    long:pairs.filter(p=>p.action===1).length,short:pairs.filter(p=>p.action===-1).length,neutral:pairs.filter(p=>p.action===0).length,
    hitRate:nonflat.length?b3Mean(nonflat.map(p=>+(p.gross*p.action>0))):null,
    currencyHitRate:currency.length?b3Mean(currency.map(c=>+((c.value>52?1:-1)*c.actual>0))):null,
    rankIC:b3Median(rows.map(r=>r.rankIC)),rankStability:b3Median(rows.map(r=>r.rankStability)),
    meanGross:b3Mean(rows.map(r=>b3DateNet(r,0))),meanNet:b3Mean(net),interval:inferenceReady?b3BlockInference(net):null,
    costs:{zero:b3Mean(rows.map(r=>b3DateNet(r,0))),five:b3Mean(net),ten:b3Mean(rows.map(r=>b3DateNet(r,.10)))},
    distribution:{minimum:sorted[0],median:b3Median(sorted),maximum:sorted.at(-1)},drawdown,
    regimes:Object.fromEntries(['Low','Intermediate','High','Unclassified'].map(regime=>{
      const values=rows.filter(r=>r.regime===regime).map(r=>b3DateNet(r,.05));
      return [regime,{dates:values.length,meanNet:b3Mean(values)}];
    })), chronologicalHalves:[b3Mean(net.slice(0,net.length>>1)),b3Mean(net.slice(net.length>>1))]};
}

function batch3Evaluate(decisions,packs,asOf,{final=false,fingerprint}={}){
  const time=Date.parse(asOf);
  if(!b3Finite(time)||!/^[a-f0-9]{64}$/.test(fingerprint||''))throw Error('Trusted cohort fingerprint and evaluation timestamp required');
  const firsts=new Map();
  const expected=new Set(B3_PAIR_ORDER.flatMap((c,i)=>B3_PAIR_ORDER.slice(i+1).map(q=>c+'/'+q)));
  for(const d of [...decisions].sort((a,b)=>a.at.localeCompare(b.at))){
    if(d.fingerprint!==fingerprint||!b3Finite(Date.parse(d.at))||Date.parse(d.at)<Date.parse(B3_FREEZE)
      ||!(Date.parse(d.at)<=Date.parse(d.recordedAt)&&Date.parse(d.recordedAt)<=time)
      ||d.recordedAt.slice(0,10)!==d.at.slice(0,10)||!['ICE-RULES-1.0','ICE-RULES-1.1','ICE-RULES-1.2','ICE-RULES-1.3'].includes(d.modelVersion)
      ||![d.rulesSha256,d.bundleSha256,d.resultSha256].every(s=>B3_SHA.test(s||'')))continue;
    const keys=d.pairs?.map(p=>p.base+'/'+p.quote)||[];
    if(keys.length!==expected.size||new Set(keys).size!==expected.size||keys.some(k=>!expected.has(k)))continue;
    const day=d.at.slice(0,10);
    if(!firsts.has(day))firsts.set(day,d);
  }
  const prices=b3Prices(packs.filter(p=>p.fingerprint===fingerprint),time);
  const cohorts=B3_CANDIDATES.map(s=>b3Cohort([...firsts.values()],prices,s,time));
  const report={fingerprint,asOf,decisions:firsts.size,priceDates:prices.length, historical:{eligible:false,reason:'No approved historical holdout'},
    cohorts:cohorts.map(({partitions,...c})=>c),final:false,forecastReliability:'Insufficient prospective evidence'};
  const enrolled=cohorts.filter(c=>c.start);
  if(!final||!enrolled.length||enrolled.some(c=>!c.end))return report;
  const tests=[];
  const results=[];
  for(const cohort of cohorts){
    if(!cohort.end){
      for(const h of B3_HORIZONS)for(const benchmark of B3_BENCHMARKS)tests.push({strategy:cohort.strategy,horizon:h,benchmark,p:null});
      continue;
    }
    for(const p of cohort.partitions){
      const candidate=p.windows.map(w=>b3Outcomes(w,cohort.strategy));
      const inferenceReady=new Set(candidate.map(r=>r.regime).filter(r=>['Low','Intermediate','High'].includes(r))).size>=2;
      const primary=b3Metrics(candidate,inferenceReady);
      const baselines={};
      for(const benchmark of B3_BENCHMARKS){
        const rows=p.windows.map(w=>b3Outcomes(w,benchmark));
        baselines[benchmark]=b3Metrics(rows,inferenceReady);
        const diff=cost=>candidate.map((r,i)=>b3DateNet(r,cost)-b3DateNet(rows[i],cost));
        const interval=inferenceReady?b3BlockInference(diff(.05)):null;
        tests.push({strategy:cohort.strategy,horizon:p.horizon,benchmark,mean:b3Mean(diff(.05)),atTenBps:b3Mean(diff(.10)),
          interval,p:interval?.p??null});
      }
      results.push({strategy:cohort.strategy,horizon:p.horizon,start:cohort.start,end:cohort.end,primary,baselines,
        windows:p.windows.map(w=>({decision:w.decision.at,runId:w.decision.runId,entry:w.entry,exit:w.exit}))});
    }
  }
  const adjusted=b3Holm(tests.map(t=>t.p));
  tests.forEach((t,i)=>{t.adjustedP=t.p===null?null:adjusted[i];});
  const promotion=enrolled.map(c=>{
    const rows=results.filter(r=>r.strategy===c.strategy);
    const core=tests.filter(t=>t.strategy===c.strategy&&['incumbent','carry','momentum'].includes(t.benchmark));
    const gate=rows.every(r=>r.primary.eligible>=.95*r.baselines.incumbent.eligible&&r.primary.rankStability>=.80)
      &&core.length===6&&core.every(t=>t.interval?.low>0&&t.adjustedP<.05&&t.atTenBps>0);
    return {strategy:c.strategy,statisticalGate:gate,status:gate?'Eligible for human review and explicit approval':'A distinguishable advantage has not been established'};
  });
  return {...report,final:true,results,tests,promotion,forecastReliability:'See matched dates, confidence intervals and promotion gates'};
}

const BATCH3_FINGERPRINT="9e1cdef2d12740445fa61282af7f39bd0e5acc4b3ed1eb943486b804b2365691";
function batch3Diagnostics(record){
  const now=Date.parse(record.analysis.generatedAt);
  const evidence=iceScheduleEvidence(record,now);
  const enrichment={...record,batch2a:record.batch2a||batch2aForRecord(record),batch2b:record.batch2b||batch2bForRecord(record)};
  const details=buildBatch3Robustness(enrichment,ICE_MODEL,evidence,iceRankEligibility);
  const weights=B3_CANDIDATES.filter(s=>s.startsWith('weights-')).map((id,i)=>{
    const rows=details.currencies.filter(c=>Number.isFinite(c.score)&&Number.isFinite(c.variants[id]));
    return {id,weights:B3_ALTERNATIVES[i],count:rows.length,rankStability:b3RankCorrelation(rows.map(c=>c.score),rows.map(c=>c.variants[id]))};
  });
  return {runId:record.runId,asOf:record.analysis.generatedAt,version:'ICE-VALIDATION-3.1',modelVersion:record.analysis.modelVersion,
    fingerprint:BATCH3_FINGERPRINT,weights,...details,archivedInputAudit:evidence.filter(row=>row.mandatory).map(r=>({
      ccy:r.ccy,indicator:r.indicator,series:r.seriesId,reference:r.period,source:r.source,publishedAt:r.publishedAt,retrievedAt:r.retrievedAt,
      eligibleAtCapture:r.freshness==='Current'&&Date.parse(r.retrievedAt)<=now&&!!r.source
    }))};
}

function batch3Decision(record,diagnostics,recordedAt){
  const fresh=record.batch2a;
  const calibrated=record.batch2b;
  const strategies=['incumbent',...B3_CANDIDATES,'equal'];
  const currencies=Object.fromEntries(strategies.map(strategy=>[strategy,{}]));
  for(const c of diagnostics.currencies){
    if(!c.evidence.eligible)continue;
    const {ccy}=c;
    currencies.incumbent[ccy]=c.score;
    for(const id of B3_CANDIDATES.filter(s=>s.startsWith('weights-')))currencies[id][ccy]=c.variants[id];
    currencies.equal[ccy]=c.variants['weights-5'];
    const a=fresh?.currencies.find(x=>x.ccy===ccy),b=calibrated?.scores.find(x=>x.ccy===ccy);
    if(a?.eligible&&fresh.fingerprint===BATCH2A_FINGERPRINT)currencies['shadow-2a'][ccy]=a.candidateScore;
    if(b?.eligible&&calibrated.fingerprint===BATCH2B_FINGERPRINT)currencies['shadow-2b'][ccy]=b.shadow2b;
  }
  const momentum=b3Momentum(record,diagnostics.pairs);
  const entries=Object.fromEntries(record.analysis.economies.map(e=>[e.ccy,e]));
  const pairs=diagnostics.pairs.map(p=>{
    const actions=Object.fromEntries(strategies.map(id=>[id,p.eligible?b3Direction(b3Delta(currencies[id][p.base],currencies[id][p.quote])):null]));
    const carry=b3Delta(entries[p.base]?.observations?.policy?.v,entries[p.quote]?.observations?.policy?.v);
    return {base:p.base,quote:p.quote,actions:{...actions,carry:p.eligible&&carry!==null?Math.sign(carry):null,
      momentum:p.eligible?momentum[p.base+p.quote]??null:null,neutral:0}};
  });
  const now=Date.parse(record.analysis.generatedAt),vix=record.analysis.regime?.vix;
  const riskFeed=record.bundle.feeds.VIXCLS;
  const prior=Number.isFinite(vix?.v)&&Date.parse(vix.d)<Date.parse(record.analysis.generatedAt.slice(0,10))
    && Date.parse(riskFeed?.retrievedAt)<=now&&now-Date.parse(vix.d)<=10*86400000&&record.bundle.status?.VIXCLS?.ok===true;
  const regime=!prior?'Unclassified':vix.v<15?'Low':vix.v<25?'Intermediate':'High';
  return {fingerprint:BATCH3_FINGERPRINT,modelVersion:diagnostics.modelVersion,at:diagnostics.asOf,recordedAt,runId:record.runId,
    rulesSha256:record.replay?.rulesSha256||null,bundleSha256:record.replay?.bundleSha256||null,
    resultSha256:record.replay?.resultSha256||null,shadow2aFingerprint:fresh?.fingerprint||null,shadow2bFingerprint:calibrated?.fingerprint||null,
    regime,pairs,currencies,sourceAudit:{evidence:diagnostics.currencies.map(c=>({ccy:c.ccy,...c.evidence})),
      fxSource:record.bundle.feeds.fx?.source||null,fxRetrievedAt:record.bundle.feeds.fx?.retrievedAt||null}};
}

async function batch3Archive(record,env){
  const at=record.analysis.generatedAt, recordedAt=new Date().toISOString(), day=at.slice(0,10);
  if(Date.parse(at)<Date.parse(B3_FREEZE)||recordedAt.slice(0,10)!==day||recordedAt<at||!record.replay)return;
  const path='validation/batch3/'+BATCH3_FINGERPRINT+'/';
  const decisionKey=path+'decisions/'+day+'.json';
  if(!await env.BUCKET.get(decisionKey)){
    const decision=batch3Decision(record,batch3Diagnostics(record),recordedAt);
    await labPutOnce(env.BUCKET,decisionKey,decision);
  }
  const prices=b3PricePack(record);
  if(prices)await labPutOnce(env.BUCKET,path+'prices/'+prices.rows.at(-1).date+'.json',{...prices,recordedAt,fingerprint:BATCH3_FINGERPRINT});
}

async function batch3Api(request,env){
  const headers={'Cache-Control':'no-store'};
  if(request.method!=='GET')return Response.json({error:'Use GET'},{status:405,headers});
  if(!env.BUCKET)return Response.json({error:'Saved evidence unavailable'},{status:503,headers});
  const record=await iceRead(env.BUCKET,'ice/latest.json');
  const path='validation/batch3/'+BATCH3_FINGERPRINT+'/';
  const [decisions,prices,report]=await Promise.all([...['decisions','prices'].map(kind=>env.BUCKET.list({prefix:path+kind+'/',limit:1000})),iceRead(env.BUCKET,path+'report.json')]);
  const performance=report?.final===true&&report.fingerprint===BATCH3_FINGERPRINT&&Date.parse(report.asOf)<=Date.now()
    &&Array.isArray(report.results)&&Array.isArray(report.tests)&&Array.isArray(report.promotion)
    ? {asOf:report.asOf,results:report.results.map(({windows,...r})=>r),tests:report.tests,promotion:report.promotion}:null;
  const counts=[decisions,prices].map(x=>({count:x.objects.length,truncated:!!x.truncated}));
  const historical={status:'No eligible historical holdout',reason:'Verified point-in-time vintages across the common universe were unavailable at freeze'};
  return Response.json({diagnostics:record?batch3Diagnostics(record):null,fingerprint:BATCH3_FINGERPRINT,
    historical,performance,prospective:{decisions:counts[0],pricePacks:counts[1],freeze:B3_FREEZE,
      status:'Forecast performance is withheld pending a completed cohort and one final protocol evaluation'}},{headers});
}

async function replayHash(value) {
  const bytes = new TextEncoder().encode(JSON.stringify(value));
  const hash = await crypto.subtle.digest('SHA-256', bytes);
  return [...new Uint8Array(hash)].map(byte => byte.toString(16).padStart(2,'0')).join('');
}

function replayModelResult(analysis) {
  const {changes, pipelineFingerprint, iceTrend, attribution, ...result} = analysis;
  return result;
}

async function iceReplayManifest(record, rules, runtime) {
  return {
    schema:1, runId:record.runId, modelVersion:record.analysis.modelVersion,
    evaluatedAt:record.analysis.generatedAt, runtime,
    configuration:rules.model,
    rulesSha256:await replayHash(rules),
    bundleSha256:await replayHash(record.bundle),
    resultSha256:await replayHash(replayModelResult(record.analysis))
  };
}

async function verifyIceReplay(record, rules, evaluate) {
  const manifest = record.replay;
  if (!manifest || manifest.schema !== 1 || manifest.runId !== record.runId
      || manifest.evaluatedAt !== record.analysis.generatedAt
      || manifest.modelVersion !== rules.model.version) throw Error('Replay manifest does not match run');
  const expected = await iceReplayManifest(record, rules, manifest.runtime);
  for (const field of ['rulesSha256','bundleSha256','resultSha256']) {
    if (expected[field] !== manifest[field]) throw Error('Replay checksum mismatch: '+field);
  }
  if (await replayHash(manifest.configuration) !== await replayHash(rules.model)) {
    throw Error('Replay configuration mismatch');
  }
  const reproduced = evaluate(record.bundle, Date.parse(manifest.evaluatedAt));
  if (await replayHash(replayModelResult(reproduced)) !== manifest.resultSha256) {
    throw Error('Replayed result differs from saved result');
  }
  return reproduced;
}

