function parseEcbCurve(text,csv=parseCSV){const rows=csv(text),h=rows.shift(),ix=k=>h.indexOf(k);if(['KEY','TIME_PERIOD','OBS_VALUE','DATA_TYPE_FM'].some(k=>ix(k)<0))throw Error('ECB curve schema changed');const groups={};for(const r of rows){const key=r[ix('DATA_TYPE_FM')],d=r[ix('TIME_PERIOD')],v=extraNumber(r[ix('OBS_VALUE')]);if(!/^SR_\d+Y$/.test(key)||!extraDate(d)||v===null)continue;if(!r[ix('KEY')].startsWith('YC.B.U2.EUR.4F.G_N_A.SV_C_YM.'))throw Error('Unexpected ECB curve definition');(groups[key]??=[]).push({d,v,status:r[ix('OBS_STATUS')]||null});}const series=Object.entries(groups).map(([k,p])=>extraSeries('ECB_'+k,k.slice(3),'EUR',p,{maturity:k.slice(3),curve:'AAA zero-coupon spot, continuously compounded'}));if(!series.length)throw Error('No ECB yield observations');return{series};}
function parseRbaCurve(text,csv=parseCSV){const rows=csv(text),headers=rows.find(r=>r[0]==='Series ID'),titles=rows.find(r=>r[0]==='Title'),published=rows.find(r=>r[0]==='Publication date');if(!headers)throw Error('RBA series metadata missing');const specs={'FCMYGBAG2D':'2Y','FCMYGBAG3D':'3Y','FCMYGBAG5D':'5Y','FCMYGBAG10D':'10Y','FCMYGBAGID':'10Y real'};const series=[];for(let i=1;i<headers.length;i++){const maturity=specs[headers[i]];if(!maturity)continue;const points=rows.flatMap(r=>{const d=extraDate(r[0]),v=extraNumber(r[i]);return d&&d>='2024-01-01'&&v!==null?[{d,v}]:[];});if(points.length)series.push(extraSeries(headers[i],titles?.[i]||maturity,'AUD',points,{maturity,curve:maturity.includes('real')?'Indexed bond':'Interpolated government bond',publicationDate:extraDate(published?.[i]||''),note:'Daily observations published weekly by RBA; publication can lag the observation date.'}));}if(!series.length)throw Error('No RBA yield observations');return{series};}
function parseJgbCurve(text,csv=parseCSV){const rows=csv(text),h=rows.find(r=>r[0]==='Date');if(!h)throw Error('JGB maturity header missing');const series=[];for(let i=1;i<h.length;i++){if(!/^\d+Y$/.test(h[i]))continue;const points=rows.flatMap(r=>{const d=extraDate(r[0]),v=extraNumber(r[i]);return d&&v!==null?[{d,v}]:[];});if(points.length)series.push(extraSeries('JGB_'+h[i],h[i],'JPY',points,{maturity:h[i],curve:'Constant-maturity, semiannual compounding'}));}if(!series.length)throw Error('No JGB yields');return{series};}
