const ECONOMY_RANK_V2 = 'ICE-ECONOMY-COMPARISON-2.0';

function rankV2Points(value, step) {
  const count = Math.min(10, Math.round(Math.abs(value) / step));
  return count ? Math.sign(value) * count : 0;
}

function rankV2Input(factor, feature, label, input, step, center, evidence, unit) {
  const reason = !evidence?.last ? 'Missing observation'
    : evidence.retained ? 'Retained after source failure'
    : !evidence.timely ? 'Observation outside freshness limit'
    : !Number.isFinite(input) ? 'Missing comparable input' : null;
  const points = reason ? null : rankV2Points(input, step);
  return {
    factor, feature, label, unit, input:Number.isFinite(input)?input:null, points, step, center, reason,
    score:points===null?null:Math.max(0,Math.min(100,center + 5 * points)),
    date:evidence?.last?.d??null, retrievedAt:evidence?.retrievedAt??null, source:evidence?.source??null
  };
}

function rankV2Place(rows, key) {
  const sorted = rows.slice().sort((a,b)=>b[key]-a[key] || a.ccy.localeCompare(b.ccy));
  let rank = 0;
  for (let i=0; i<sorted.length; i++) {
    if (!i || Math.abs(sorted[i][key]-sorted[i-1][key]) > 1e-9) rank = i+1;
    sorted[i][key+'Rank'] = rank;
  }
}

function buildEconomyRankV2(analysis, explorer, model, bundle) {
  const evidence = new Map(explorer.series.map(row=>[row.id,row]));
  const rows = (analysis?.economies??[]).map(economy=>{
    const {ccy,factors} = economy;
    const inflation = factors.inflation.features.find(f=>f.name==='Inflation stability');
    const unemployment = factors.labour.features.find(f=>f.name==='Unemployment momentum');
    const growth = factors.growth.features.find(f=>f.name==='Real quarterly GDP growth');
    const check=economy.policyValidation;
    const official=bundle?.feeds?.['policy_check_'+ccy];
    const observedPolicy=economy.observations?.policy;
    const useOfficial=check?.independentlyChecked&&check.selected&&observedPolicy?.v===check.selected.v&&
      official?.points?.at(-1)?.d===check.selected.d&&official.points.at(-1).v===check.selected.v&&
      bundle.status?.['policy_check_'+ccy]?.ok===true;
    const policy = useOfficial?{last:observedPolicy,points:official.points,timely:true,
      source:official.source,retrievedAt:official.retrievedAt}:evidence.get('policy_'+ccy);
    const policyPrior = policy?.last ? usPointsBaseline(policy,'dailyRateDelta') : null;
    const rateChange = policyPrior ? policy.last.v-policyPrior.v : null;
    const inflationSeries = evidence.get(ccy==='AUD' && inflation?.observation?.d===evidence.get('cpi_AUD')?.last?.d
      && inflation?.observation?.v===evidence.get('cpi_AUD')?.last?.v ? 'cpi_AUD' : 'cpi_'+ccy);
    const reference = ccy==='AUD'?2.5:ccy==='CHF'?1:2;
    const inflationGap = Number.isFinite(inflation?.observation?.v) ? -Math.abs(inflation.observation.v-reference) : null;
    const inputs = [
      rankV2Input('growth','Real quarterly GDP growth','Real GDP growth',growth?.observation?.v,0.2,50,evidence.get('gdp_'+ccy),'% q/q'),
      rankV2Input('labour','Unemployment momentum','Falling unemployment',Number.isFinite(unemployment?.change)?-unemployment.change:null,0.15,50,evidence.get(unemployment?.observation?.feedId==='ons_jobs'?'ons_jobs':'jobs_'+ccy),'pp / 3 months'),
      rankV2Input('inflation','Inflation stability','Negative absolute CPI gap to '+reference+'%',inflationGap,0.5,70,inflationSeries,'pp'),
      rankV2Input('rates','Three-month policy change','Policy-rate change',rateChange,0.25,50,policy,'pp / 1 month')
    ];
    const liquidity = evidence.get('bis_assets_gdp_cb_assets_gdp_'+ccy);
    const liquidityPrior = liquidity?.last ? usPointsBaseline(liquidity,'quarterDelta') : null;
    const liquidityContext = rankV2Input(null,null,'Central-bank assets / GDP',
      liquidityPrior ? liquidity.last.v-liquidityPrior.v : null,0.5,50,liquidity,'pp q/q');
    const row = {ccy, baseline:economy.score, coverage:economy.coverage, inputs, liquidityContext,
      revised:null, reason:null, baselineRank:null, revisedRank:null};
    if (!economy.critical || !Number.isFinite(row.baseline) || !(row.coverage>0)) {
      row.reason = 'Core ICE readiness gate';
      return row;
    }
    for (const input of inputs) {
      const features = factors[input.factor].features;
      const original = features.find(f=>f.name===input.feature);
      const total = features.reduce((sum,f)=>sum+f.weight,0);
      if (!Number.isFinite(original?.score) || !total) input.reason ??= 'Matched baseline feature unavailable';
      if (!input.reason) {
        // Same existing factor and feature weight. Score change is normalized by the saved coverage.
        input.impact = (input.score-original.score) * original.weight / total *
          model.weights[input.factor] / row.coverage;
      }
    }
    if (inputs.some(input=>input.reason)) row.reason = 'One or more matched inputs are unavailable';
    else row.revised = row.baseline + inputs.reduce((sum,input)=>sum+input.impact,0);
    return row;
  });
  const eligible = rows.filter(row=>Number.isFinite(row.revised));
  rankV2Place(eligible,'baseline');
  rankV2Place(eligible,'revised');
  return {version:ECONOMY_RANK_V2, capturedAt:explorer.capturedAt, eligible:eligible.length,
    rows:rows.sort((a,b)=>(a.revisedRank??Infinity)-(b.revisedRank??Infinity) || a.ccy.localeCompare(b.ccy))};
}

