function forwardPredictions(data,day){
 const recent=Date.parse(day)-7*FORWARD_DAY;
 const candidates=['EUR','USD'].map(ccy=>data.surprises.find(r=>r.country===ccy&&Number.isFinite(r.standardisedSurprise)&&Date.parse(r.eventAt)>=recent&&/CPI|HICP|Payroll|Non-Farm|GDP|Retail Sales/i.test(r.title)&&!/Unemployment/i.test(r.title)));
 const ois=data.paths.find(r=>r.tenor==='6M')?.differentialBps;
 const spread=data.spread.stale||data.spread.retained?null:data.spread.change5Bps;
 const surprise=candidates.every(Boolean)?candidates[0].standardisedSurprise-candidates[1].standardisedSurprise:null;
 const signs=[ois,spread,surprise].map(labSign);
 return {baseline:data.baseline,ois:signs[0],curve:signs[1],surprise:signs[2],combined:signs.every(Number.isFinite)?Math.sign(signs.reduce((a,b)=>a+b,0)):null};
}
async function forwardCapture(env,record){
 const now=Date.now(),day=new Date(now).toISOString().slice(0,10),bucket=env.BUCKET;
 const key=FORWARD_MACRO_ROOT+'daily/'+day+'.json';
 if(await bucket.get(key))return;
 const fx=labCross(record.bundle.feeds.fx?.history,'EUR','USD',day+'T00:00:00Z');
 if(!fx.length||new Date(day).getUTCDay()%6===0)return;
 const [ois,calendar]=await Promise.all([iceRead(bucket,OIS_KEY),calActualsView(env,{savedOnly:true})]);
 const data=forwardMacroInputs(record,ois,calendar,now);
 const match=fx.at(-1);
 if(Date.parse(day)-Date.parse(match.d)>4*FORWARD_DAY)return;
 await labPutOnce(bucket,key,{day,observedAt:new Date(now).toISOString(),runId:record.runId,modelVersion:record.analysis.modelVersion,predictions:forwardPredictions(data,day),paths:data.paths,spread:data.spread,surprises:data.surprises});
}
function forwardEvaluate(rows,history,day){
 const prices=labCross(history,'EUR','USD',day),methods=['ois','curve','surprise','combined'];
 return [5,10,20].flatMap(horizon=>methods.map(method=>{
  let dates=0,baselineHits=0,signalHits=0;
  for(const row of rows){
   const base=row.predictions?.baseline,signal=row.predictions?.[method];
   if(!base||!signal)continue;
   const start=prices.findIndex(p=>p.d>row.day),end=start<0?null:prices[start+horizon];
   if(!end)continue;
   const result=Math.sign(end.v/prices[start].v-1);
   if(!result)continue;
   dates++;baselineHits+=Number(result===base);signalHits+=Number(result===signal);
  }
  return {method,horizon,dates,baselineAccuracy:dates?baselineHits/dates:null,signalAccuracy:dates?signalHits/dates:null};
 }));
}
async function forwardImf(){
 const r=await fetch(FORWARD_IMF,{signal:AbortSignal.timeout(4500),cf:{cacheTtlByStatus:{'200':43200,'400-599':0}}});
 if(!r.ok)throw Error('IMF forecast endpoint unavailable');
 const data=await r.json(),meta=data.indicators?.BCA_NGDPD,values=data.values?.BCA_NGDPD,year=Number(meta?.['projection-year']);
 if(meta?.dataset!=='WEO'||meta?.unit!=='Percent of GDP'||!/^World Economic Outlook \((April|October) 20\d{2}\)$/.test(meta.source||'')||!Number.isInteger(year)||!values)throw Error('IMF forecast metadata unavailable');
 const projections={};
 for(const [ccy,key] of [['EUR','EAQ'],['USD','USA']]){
  projections[ccy]=Object.entries(values[key]||{}).filter(([period,v])=>/^\d{4}$/.test(period)&&Number(period)>=year&&Number.isFinite(v)).sort().slice(0,3).map(([period,v])=>({year:period,percentGDP:v}));
 }
 return {edition:meta.source,projections};
}
async function forwardMacroApi(request,env){
 if(request.method!=='GET')return Response.json({error:'Use GET'},{status:405});
 if(!env.BUCKET)return Response.json({error:'Saved evidence unavailable'},{status:503});
 const now=Date.now(),day=new Date(now).toISOString().slice(0,10),evaluation=new URL(request.url).searchParams.get('view')==='evaluation';
 const [record,ois,calendar,archive,imf,usBalance]=await Promise.all([
  iceRead(env.BUCKET,'ice/latest.json'),iceRead(env.BUCKET,OIS_KEY),evaluation?null:calActualsView(env,{savedOnly:true}).catch(()=>null),
  Promise.all(Array.from({length:evaluation?63:12},(_,i)=>new Date(now-i*FORWARD_DAY).toISOString().slice(0,10)).filter(d=>new Date(d).getUTCDay()%6!==0).map(d=>iceRead(env.BUCKET,FORWARD_MACRO_ROOT+'daily/'+d+'.json'))),
  evaluation?null:forwardImf().catch(()=>null),evaluation?null:forwardUsBalance(now).catch(()=>null)
 ]);
 const rows=archive.filter(Boolean);
 if(evaluation)return Response.json({comparisons:forwardEvaluate(rows,record?.bundle?.feeds?.fx?.history,day),captures:rows.length},{headers:{'Cache-Control':'no-store'}});
 const data=forwardMacroInputs(record,ois,calendar,now);
 data.external.USD=usBalance;
 data.paths=data.paths.map(row=>{
  const prior=rows.filter(r=>r.day<(row.eur?.asOf||day)).map(r=>r.paths?.find(p=>p.tenor===row.tenor)).filter(p=>Number.isFinite(p?.differentialBps)&&p.eur.asOf<row.eur?.asOf);
  const distinct=[...new Map(prior.reverse().map(p=>[p.eur.asOf,p])).values()].reverse();
  const change=(n,key)=>{
   const previous=distinct[n-1];
   if(!Number.isFinite(row.differentialBps)||!previous||Date.parse(row.eur.asOf)-Date.parse(previous.eur.asOf)>(n===1?5:12)*FORWARD_DAY)return null;
   return key==='differentialBps'?row[key]-previous[key]:100*(row[key].rate-previous[key].rate);
  };
  return {...row,change1Bps:change(1,'differentialBps'),change5Bps:change(5,'differentialBps'),
   eurChange1Bps:change(1,'eur'),eurChange5Bps:change(5,'eur'),usdChange1Bps:change(1,'usd'),usdChange5Bps:change(5,'usd')};
 });
 return Response.json({...data,imf,scoringUnchanged:true},{headers:{'Cache-Control':'no-store'}});
}

