 const groups={};for(const r of capture?.rows||[]){if(r.status!=='COMPLETED'||Date.parse(r.endUTC)>now||![r.open,r.high,r.low,r.close].every(Number.isFinite))continue;(groups[r.symbol+'|'+r.timeframe]??=[]).push(r);}
 return Object.entries(groups).map(([key,rows])=>{
  const bars=[...new Map(rows.map(b=>[b.openUTC,b])).values()].sort((a,b)=>a.openUTC.localeCompare(b.openUTC)),last=bars.at(-1),ageHours=(now-Date.parse(last.endUTC))/3600000,captureAgeHours=(now-Date.parse(last.retrievedUTC))/3600000,conflictingBars=rows.filter((b,i)=>rows.slice(0,i).some(a=>a.openUTC===b.openUTC&&['open','high','low','close','endUTC'].some(k=>a[k]!==b[k]))).length,gapCount=bars.slice(1).filter((b,i)=>Date.parse(b.openUTC)-Date.parse(bars[i].endUTC)>60000).length,fresh=conflictingBars===0&&ageHours>=0&&ageHours<=({H1:6,H4:18}[last.timeframe]||0)&&Number.isFinite(captureAgeHours)&&captureAgeHours>=-2/60&&captureAgeHours<=({H1:6,H4:18}[last.timeframe]||0),prior=bars.slice(-21,-1),high=prior.length===20?Math.max(...prior.map(b=>b.high)):null,low=prior.length===20?Math.min(...prior.map(b=>b.low)):null;
  const atrBars=bars.slice(0,-1).slice(-15),ranges=atrBars.slice(1).map((b,i)=>Math.max(b.high-b.low,Math.abs(b.high-atrBars[i].close),Math.abs(b.low-atrBars[i].close))),atr=ranges.length===14?ranges.reduce((a,b)=>a+b,0)/14:null;
  const pivots=[];for(let i=Math.max(2,bars.length-60);i<bars.length-2;i++){const b=bars[i],neighbours=[bars[i-2],bars[i-1],bars[i+1],bars[i+2]];if(neighbours.every(n=>b.high>n.high))pivots.push({kind:'Swing high',price:b.high,time:b.endUTC,confirmedAfter:bars[i+2].endUTC});if(neighbours.every(n=>b.low<n.low))pivots.push({kind:'Swing low',price:b.low,time:b.endUTC,confirmedAfter:bars[i+2].endUTC});}
  const direction=fresh&&prior.length===20?(last.close>high?'Upward range break':last.close<low?'Downward range break':'Inside prior 20-bar range'):'Unassessed';
  return{symbol:last.symbol,broker:capture.broker||'HFM',timeframe:last.timeframe,bars:bars.length,patterns:fresh?iceSafePatterns(bars):[],mm:fresh?iceMmRead(last.timeframe,bars,atr,last):null,captureAgeHours,conflictingBars,gapCount,atrBasis:'14 prior completed true ranges; current bar excluded',reviewLevels:{buyInvalidation:fresh?pivots.filter(p=>p.kind==='Swing low'&&p.price<last.close).at(-1)?.price??null:null,sellInvalidation:fresh?pivots.filter(p=>p.kind==='Swing high'&&p.price>last.close).at(-1)?.price??null:null},latestBarEndUTC:last.endUTC,retrievedUTC:last.retrievedUTC,ageHours,fresh,atr14:atr,rangeHigh:high,rangeLow:low,lastClose:last.close,direction,displacement:fresh&&atr>0?Math.abs(last.close-last.open)>=1.5*atr:false,pivots:pivots.slice(-4),mmCycleConfirmed:false,executionReady:false,note:'Completed-bar facts; 2-left/2-right swing rule, 20-bar range and 14-bar mean true range. Conflicting duplicates block assessment. Gaps require session review (weekends, holidays or missing exports). Swing levels are review candidates, not approved stops. ATR excludes the current bar. No dealer-inventory or MM phase inference.'};
 });
