function buildResearch(bundle,baseline,catalog,brokerFeeds=[],now=Date.now()){
 const feed=id=>bundle.feeds[id],points=(id,c)=>c?feed(id)?.byCurrency?.[c]||[]:feed(id)?.points||[],src=id=>feed(id)?.source;
 const economies=catalog.map(e=>{
  const c=e.ccy,bisCpi=points('cpi',c),cpi=c==='AUD'&&points('cpi_AUD').at(-1)?.d>(bisCpi.at(-1)?.d||'')?points('cpi_AUD'):bisCpi,interest=points('fiscal_interest_lcu',c).flatMap(p=>{const g=points('nominal_gdp_lcu',c).find(q=>q.d===p.d);return g?.v>0?[{d:p.d,v:p.v/g.v*100}]:[];}),f=(name,w,p,freq,lag,rule,fn,source)=>researchFeature(name,w,p,freq,lag,rule,fn,source,now);
  const endogenous=researchFactor([
   f('Annual real GDP growth',30,points('annual_growth',c),'Annual',730,'clip(50 + 5 × annual real growth)',v=>50+5*v,src('annual_growth')),
   f('Unemployment versus own history',20,points('annual_jobs',c),'Annual',730,'100 minus own-history percentile; modelled ILO rates', (v,p)=>{const rank=researchPercentile(v,p.slice(0,-1).map(p=>p.v));return rank===null?null:100-rank;},src('annual_jobs')),
   f('Central-government debt burden',20,points('fiscal_debt',c),'Annual',730,'clip(100 − 0.5 × debt/GDP); government coverage differs',v=>100-.5*v,src('fiscal_debt')),
   f('Matched-year interest burden',10,interest,'Annual',730,'clip(100 − 8 × interest/GDP); same-year LCU denominator',v=>100-8*v,src('fiscal_interest_lcu')),
   f('Headline inflation momentum',20,cpi,'Monthly',95,'clip(50 − 10 × three-month CPI y/y change); stability rule, not rate prediction',(v,p)=>{const date=new Date(p.at(-1).d+'T00:00:00Z');date.setUTCMonth(date.getUTCMonth()-3);const q=p.find(q=>q.d===date.toISOString().slice(0,10));return q?50-10*(v-q.v):null;},src(c==='AUD'&&cpi!==bisCpi?'cpi_AUD':'cpi'))
  ]);
  const tff=points('cot',c),legacy=feed('legacy_cot')?.series?.find(s=>s.ccy===c),cot=tff.length?tff:legacy?.points||[];
  const euroAnnual=c==='EUR'?annualCurrentAccount(points('euro_current_balance'),points('euro_nominal_gdp')):[];
  const externalRow=id=>c==='EUR'&&id==='external_current'&&euroAnnual.length?euroAnnual:points(id==='external_current'?'annual_current':'annual_fdi',c).length?points(id==='external_current'?'annual_current':'annual_fdi',c):feed(id)?.rows?.[c]?[feed(id).rows[c]]:[];const externalSource=id=>c==='EUR'&&id==='external_current'&&euroAnnual.length?src('euro_current_balance'):src(id==='external_current'?'annual_current':'annual_fdi')||src(id);
  const exogenous=researchFactor([
   f(c==='EUR'&&euroAnnual.length?'Annual current account/GDP, derived from four matched EA21 quarters':'Current account / GDP',50,externalRow('external_current'),'Annual',730,'clip(50 + 5 × current account/GDP)',v=>50+5*v,externalSource('external_current')),
   f('FDI inflows / GDP',25,externalRow('external_fdi'),'Annual',730,'clip(50 + 4 × FDI/GDP); volatile annual context',v=>50+4*v,externalSource('external_fdi')),
   f(tff.length?'TFF leveraged-fund positioning':'Legacy non-commercial positioning',25,cot,'Weekly',14,'clip(50 + 1.5 × net/open-interest %); category disclosed, procyclical research assumption',v=>50+1.5*v,src(tff.length?'cot':'legacy_cot'))
  ]);
  const domestic=baseline?.economies?.find(b=>b.ccy===c),tactical=domestic?researchFactor(['rates','inflation','growth','labour'].map(k=>({name:k,weight:{rates:30,inflation:15,growth:10,labour:10}[k],score:domestic.factors[k].score,coverage:domestic.factors[k].coverage}))):null;
  for(const feature of [...endogenous.features,...exogenous.features]){const entry=Object.entries(bundle.feeds).find(([id,f])=>f.source===feature.source);feature.retrievedAt=entry?.[1]?.retrievedAt||null;feature.retained=entry?bundle.status[entry[0]]?.ok===false:false;}
  if(c==='EUR'&&euroAnnual.length){exogenous.features[0].secondarySource=src('euro_nominal_gdp');exogenous.features[0].secondaryRetrievedAt=feed('euro_nominal_gdp')?.retrievedAt;exogenous.features[0].retained=exogenous.features[0].retained||bundle.status.euro_nominal_gdp?.ok===false;exogenous.features[0].rule+='; 100 × sum of four ECB current-account quarters / same four Eurostat nominal GDP quarters, both millions EUR and fixed EA21';}
  const eligible=endogenous.coverage>=60&&exogenous.coverage>=60;
  return{ccy:c,name:e.name,endogenous,exogenous,combined:eligible ? .5*endogenous.score+.5*exogenous.score : null,eligible,tacticalDomestic:tactical?.score??null,tacticalCoverage:domestic?.coverage??null,scope:'Structural comparison; annual fundamentals plus monthly CPI and weekly positioning',validated:false};
 });
 const news=Object.entries(bundle.feeds).flatMap(([id,f])=>(f.news||[]).map(n=>({...n,feedId:id,source:f.source,retrievedAt:f.retrievedAt,retained:bundle.status[id]?.ok===false}))).sort((a,b)=>b.publishedAt.localeCompare(a.publishedAt));
 return{version:RESEARCH_VERSION,checkedAt:new Date(now).toISOString(),capturedAt:bundle.capturedAt,economies,releaseComparisons:matchReleaseEvidence(bundle,now),structures:assessBrokerStructure(brokerFeeds,now),patternsD1:iceDailyPatterns(brokerFeeds,now),news,projections:feed('fed_projections')||null,
  validated:false,baselineModel:baseline?.modelVersion,notes:['Structural scores are explicit provisional rules; annual scores do not establish a 2–4 week trade bias.','Missing features stay missing; coverage is shown and at least 60% of each lens is required for a combined score.','Fiscal definitions and publication lags differ. Latest or computed release comparisons are not first-vintage surprises.','Official projections differ from market-implied OIS paths. Official headlines require interpretation; keyword matches do not validate geopolitical direction.','No execution approval or calibrated win probability is produced.']};
}


export function iceParseAbsCpi(html){
 const tables=html.match(/<table\b[^>]*>[\s\S]*?<\/table>/gi)||[];
 const table=tables.find(t=>/<caption>All groups CPI, Australia, monthly and annual movement \(%\)<\/caption>/.test(t));
 if(!table||!table.includes('Annual change (%)'))throw Error('ABS CPI table schema changed');
 const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 const points=[];for(const row of table.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)){
 const cells=[...row[1].matchAll(/<t[hd]\b[^>]*>([\s\S]*?)<\/t[hd]>/gi)].map(m=>m[1].replace(/<[^>]*>/g,'').trim());
 const d=cells[0]?.match(/^([A-Z][a-z]{2})-(\d{2})$/);if(!d||cells.length!==3||!cells[2]||!/^[-+]?\d+(?:\.\d+)?$/.test(cells[2]))continue;
 const month=months.indexOf(d[1]);if(month<0)continue;points.push({d:'20'+d[2]+'-'+String(month+1).padStart(2,'0')+'-01',v:Number(cells[2])});}
 if(points.length<4)throw Error('Insufficient ABS CPI history');return points.sort((a,b)=>a.d.localeCompare(b.d));
}
async function iceFetchFredBatch(defs,fredKey){
 const start=new Date(Date.now()-(defs[0].frequency==='Quarterly'?3000:defs[0].frequency==='Monthly'?1500:800)*86400000).toISOString().slice(0,10);const source='https://fred.stlouisfed.org/graph/fredgraph.csv?id='+defs.map(d=>d.series).join(',')+'&cosd='+start;
 if(defs.length===1){
  const [def]=defs,points=await fredAuthenticatedHistory(def.series,fredKey,start);
  if(points)return {[def.id]:{...def,points,source:def.source,retrievedAt:new Date().toISOString(),releaseDate:null,transport:'FRED API'}};
 }
 const rows=parseCSV(await remote(source,false)),headers=rows.shift(),retrievedAt=new Date().toISOString(),out={};
 for(const def of defs){const index=headers.indexOf(def.series);if(index<1)throw Error('FRED batch schema changed: '+def.series);const points=rows.flatMap(r=>{const raw=r[index],v=Number(raw);return /^\d{4}-\d{2}-\d{2}$/.test(r[0])&&r[0]>='1950-01-01'&&raw&&raw!=='.'&&Number.isFinite(v)?[{d:r[0],v}]:[];});if(!points.length)throw Error('No FRED observations: '+def.series);out[def.id]={...def,points,source:def.source,retrievedAt,releaseDate:null};}return out;
}
function iceDate(period){if(/^\d{4}-Q[1-4]$/.test(period))return period.slice(0,4)+'-'+String((Number(period.at(-1))-1)*3+1).padStart(2,'0')+'-01';if(/^\d{4}-\d{2}$/.test(period))return period+'-01';if(/^\d{4}$/.test(period))return period+'-01-01';return period;}
export function iceParseEurostat(data){if(data.error)throw Error('Eurostat returned an error');const time=data.dimension?.time?.category?.index;if(!time||data.id.filter(id=>id!=='time').some(id=>data.size[data.id.indexOf(id)]!==1))throw Error('Ambiguous Eurostat dimensions');const entries=Object.entries(time).sort((a,b)=>a[1]-b[1]);return entries.flatMap(([period,index])=>{const v=Array.isArray(data.value)?data.value[index]:data.value?.[String(index)];return v!==null&&v!==undefined&&Number.isFinite(v)?[{d:iceDate(period),v,period,status:data.status?.[String(index)]||null}]:[];});}
async function fetchNationalMoney(def){
 const text=await remote(def.source,false);
 let points=[];
 if(def.kind==='boe-m4'){
  const rows=parseCSV(text),header=rows.findIndex(row=>row.includes(def.series));
  if(header<0)throw Error('Bank of England M4 CSV schema changed');
  const column=rows[header].indexOf(def.series);
  points=rows.slice(header+1).flatMap(row=>{
   const date=new Date(row[0]),value=Number(row[column]);
   return Number.isFinite(+date)&&value>0?[{d:date.toISOString().slice(0,7)+'-01',v:value}]:[];
  });
 }else{
  const rows=[...text.matchAll(/<tr\b[^>]*>([\s\S]*?)<\/tr>/gi)].map(match=>
   [...match[1].matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)].map(cell=>policyText(cell[1])));
  const header=rows.find(row=>row.includes('Series code'));
  const column=header?.indexOf("MD01'MABS1AN11")??-1;
  if(column<1)throw Error('Bank of Japan monetary base table schema changed');
  points=rows.flatMap(row=>{
   const match=row[0]?.match(/^(\d{4})[/-](0[1-9]|1[0-2])$/),value=Number(row[column]?.replaceAll(',',''));
   return match&&value>0?[{d:match[1]+'-'+match[2]+'-01',v:value}]:[];
  });
 }
 const retrievedAt=new Date().toISOString();
 points.sort((a,b)=>a.d.localeCompare(b.d));
 if(points.length<13||new Set(points.map(p=>p.d)).size!==points.length||points.at(-1).d>retrievedAt.slice(0,10))
  throw Error('Invalid national monetary stock history');
 return {...def,points,retrievedAt,releaseDate:null};
}
