 if(['alfred-initial','ilostat-context'].includes(def.kind)&&f.unchanged&&prior[def.id]?.source===f.source&&JSON.stringify(prior[def.id]?.points)===JSON.stringify(f.points)){bundle.feeds[def.id]={...f,retrievedAt:prior[def.id].retrievedAt};bundle.status[def.id]={ok:true,name:def.name,checkedAt:input.capturedAt,metadataVerified:true};continue;}
 if(def.id==='snb_money'&&f.unchanged&&prior[def.id]?.publisherEdition===f.publisherEdition&&prior[def.id]?.publisherPublicSince===f.publisherPublicSince&&prior[def.id]?.source===f.source){bundle.feeds[def.id]={...prior[def.id],unchanged:true,checkedAt:input.capturedAt};bundle.status[def.id]={ok:true,name:def.name,checkedAt:input.capturedAt,metadataVerified:true};continue;}
