 if(!Number.isFinite(Date.parse(f.retrievedAt))||Math.abs(Date.now()-Date.parse(f.retrievedAt))>86400000)throw Error('Invalid retrieval timestamp');
 if(def.kind==='policy-check'&&(f.source!==def.source||f.ccy!==def.ccy||!Array.isArray(f.points)||f.points.some(p=>p.d>new Date().toISOString().slice(0,10)||p.v < -10||p.v>50)))throw Error('Invalid official policy check');
