function rdEligibility(record,asOf){
 const a=record?.analysis;
 if(!Array.isArray(a?.economies)||!Array.isArray(a.pairs))return {};
 const evidence=iceScheduleEvidence(record,asOf);
 const economies=new Map(a.economies.map(e=>[e.ccy,e]));
 const pairs=a.pairs.map(p=>{
  const reasons=[p.base,p.quote].flatMap(ccy=>{
   const reason=iceRankEligibility(economies.get(ccy),evidence);
   const gaps=evidence.filter(r=>r.ccy===ccy&&r.mandatory&&!RANK_CURRENT_STATES.includes(r.freshness)&&!iceRankAged(r));
   return reason?[ccy+' '+reason,...gaps.map(r=>ccy+' '+r.indicator+' — '+r.freshness)]:[];
  });
  if(!p.critical)reasons.push('Mandatory pair inputs unavailable');
  return {...p,reasons,rank:null};
 });
 pairs.filter(p=>!p.reasons.length&&rdFinite(p.delta)).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)||rdPair(a).localeCompare(rdPair(b)))
  .forEach((p,i)=>p.rank=i+1);
 return Object.fromEntries(pairs.map(p=>[rdPair(p),{rank:p.rank,coverage:p.coverage,reasons:p.reasons}]));
}
function rdConsensus(a,b){
 const left=iceFactorPoints(a),right=iceFactorPoints(b);
 return Object.keys(ICE_MODEL.weights).flatMap(id=>rdFinite(left?.[id])&&rdFinite(right?.[id])?
  [{factor:id,points:left[id]-right[id]}]:[]);
}
function rdScenario(analysis,currency,bp){
 const selected=analysis.economies.find(e=>e.ccy===currency);
 const f=selected?.factors?.rates;
 const index=f?.features?.findIndex(x=>x.name==='Three-month policy change');
 const feature=index>=0?f.features[index]:null;
 if(!rdFinite(feature?.change)||!rdFinite(feature.score))return null;
 const original=b3Weighted(selected,ICE_MODEL.weights);
 const stressed=b3Weighted(selected,ICE_MODEL.weights,{id:'rates',index,score:Math.max(0,Math.min(100,50+(feature.change+bp/100)*30))});
 if(!rdFinite(original)||!rdFinite(stressed))return null;
 const change=stressed-original;
 return {currency,bp,change,pairs:analysis.pairs.filter(p=>p.base===currency||p.quote===currency).map(p=>({
  pair:rdPair(p),change:p.base===currency?change:-change}))};
}
async function researchDiagnosticsApi(request,env){
 if(request.method!=='GET')return Response.json({error:'Use GET'},{status:405});
 if(!env.BUCKET)return Response.json({error:'Saved evidence unavailable'},{status:503});
 const url=new URL(request.url),bp=Number(url.searchParams.get('bp')??-25),currency=url.searchParams.get('currency')||'USD';
 if(!ICE_CORE.includes(currency)||!Number.isInteger(bp)||bp<-200||bp>200)return Response.json({error:'Use a core currency and a whole shock from −200 to +200 bp'},{status:400});
 if(url.searchParams.get('scenarioOnly')==='1'){
  const saved=activeIceAnalysis(await iceRead(env.BUCKET,'ice/latest.json'));
  return Response.json({capturedAt:saved?.capturedAt||null,scenario:saved?rdScenario(saved,currency,bp):null},{headers:{'Cache-Control':'no-store'}});
 }
 const [record,listed,shadow]=await Promise.all([
  iceRead(env.BUCKET,'ice/latest.json'),env.BUCKET.list({prefix:'ice/daily/',limit:42}).catch(()=>({objects:[]})),
  iceRead(env.BUCKET,S15_LOG_KEY).catch(()=>null)]);
 const a=activeIceAnalysis(record);
 if(!a?.pipelineFingerprint)return Response.json({error:'No fingerprinted saved assessment'},{status:503});
 const saved=(await Promise.all(listed.objects.map(o=>iceRead(env.BUCKET,o.key).catch(()=>null)))).filter(r=>r?.capturedAt);
 const current={capturedAt:a.capturedAt,pipelineFingerprint:a.pipelineFingerprint,regimeLabel:a.globalRegime?.label||null,
  economies:a.economies.map(e=>({...e,factorPoints:iceFactorPoints(e)}))};
 const history=rdHistory(saved,current);
 const prev=history.slice(0,-1).at(-1);
 const prior=prev?.runId?await iceRead(env.BUCKET,'ice/runs/'+prev.runId+'.json').catch(()=>null):null;
 const now=Date.now(),elig=rdEligibility(record,now);
 const old=prior?.analysis?.pipelineFingerprint===a.pipelineFingerprint?rdEligibility(prior,Date.parse(prior.analysis.capturedAt)):null;
 const economies=new Map(a.economies.map(e=>[e.ccy,e]));
 const evidence=iceScheduleEvidence(record,now);
 const pairs=a.pairs.map(p=>{
  const pair=rdPair(p),before=old?.[pair]||null,current=elig[pair],direction=Math.sign(p.delta||0);
  const factor=rdConsensus(economies.get(p.base),economies.get(p.quote));
  return {pair,bias:p.bias,delta:p.delta,coverage:p.coverage,before,current,
   support:factor.filter(x=>Math.abs(x.points)>=.25&&Math.sign(x.points)===direction),
   oppose:factor.filter(x=>Math.abs(x.points)>=.25&&Math.sign(x.points)===-direction&&direction!==0)};
 });
 const versions=(Array.isArray(shadow)?shadow:[]).filter(x=>x?.d&&Array.isArray(x.rows)).slice(-14).map(x=>({
  date:x.d,referenceDate:x.pxDate,rows:x.rows.map(r=>({pair:r[0],live:r[2],variants:r.slice(3,7),eligible14:!!r[7],blocked15:!!r[8]}))}));
 const debts=evidence.filter(r=>r.mandatory&&!RANK_CURRENT_STATES.includes(r.freshness)).map(r=>({
  currency:r.ccy,input:r.indicator,status:r.freshness,reason:r.freshnessReason||null,
  release:r.expectedReleaseAt||r.nextReleaseDate||null}));
 const age=evidence.filter(r=>r.mandatory).map(r=>{
  const published=r.publishedAt||r.publishedDate;
  const days=Date.parse(published)<=now?Math.floor((now-Date.parse(published))/rdDay):null;
  const halfLife=r.frequency==='Quarterly'?90:r.frequency==='Annual'?365:r.frequency==='Daily'?7:30;
  return {currency:r.ccy,input:r.indicator,status:r.freshness,days,halfLife,weight:days===null?null:100*2**(-days/halfLife)};
 });
 return Response.json({capturedAt:a.capturedAt,fingerprint:a.pipelineFingerprint,modelVersion:a.modelVersion,
  comparisonAt:prior?.analysis?.capturedAt||null,marketRegime:a.globalRegime?.label||null,
  economies:a.economies.map(e=>({...rdEconomy(history,e),coverage:e.coverage,proxy:e.confidenceBreakdown?.proxyDependence??null})),
  pairs,versions,debts,age,scenario:rdScenario(a,currency,bp)},{headers:{'Cache-Control':'no-store'}});
}

async function iceTrendHistory(bucket,analysis,previousBasis={}){
 const day=86400000,now=Date.parse(analysis.capturedAt);
 const readDay=async date=>{
  const entry=await iceRead(bucket,iceDailyKey(date));
  return entry?.capturedAt?.slice(0,10)===date?entry:null;
 };
 const findComparison=async (days,qualifies)=>{
  const target=now-days*day;
  for(let offset=0;offset<=7;offset++){
   const date=iceUtcDay(target-offset*day),entry=await readDay(date);
   if(!entry)continue;
   const elapsed=target-Date.parse(entry.capturedAt);
   if(elapsed>=0&&elapsed<=7*day&&qualifies(entry))return entry;
  }
  return null;
 };
 const hasCore=run=>run.economies?.some(e=>Number.isFinite(e.legacyScore??(run.modelVersion==='ICE-RULES-1.0'?e.score:null)));
 const sameRules=run=>run.pipelineFingerprint===analysis.pipelineFingerprint;
 const [week,fourWeeks,twelveWeeks,attributionDay,attributionWeek,attributionMonth]=await Promise.all([
  findComparison(7,hasCore),findComparison(28,hasCore),findComparison(84,hasCore),
  iceComparisonBaseline(bucket,analysis,1),findComparison(7,sameRules),findComparison(30,sameRules)
 ]);
 const trend=analysis.economies.map(e=>{
  const [weekChange,fourWeekChange,twelveWeekChange]=[week,fourWeeks,twelveWeeks].map(run=>{
   const old=run?.economies?.find(x=>x.ccy===e.ccy);
   const past=old?.legacyScore??(run?.modelVersion==='ICE-RULES-1.0'?old?.score:null);
   return {change:Number.isFinite(past)&&Number.isFinite(e.legacyScore)?e.legacyScore-past:null,asOf:run?.capturedAt||null};
  });
  const weekDays=(now-Date.parse(weekChange.asOf))/day,monthDays=(now-Date.parse(fourWeekChange.asOf))/day;
  const acceleration=weekChange.change!==null&&fourWeekChange.change!==null&&monthDays>weekDays
   ?7*(weekChange.change/weekDays-(fourWeekChange.change-weekChange.change)/(monthDays-weekDays)):null;
  return {ccy:e.ccy,week:weekChange,fourWeeks:fourWeekChange,twelveWeeks:twelveWeekChange,acceleration,state:acceleration===null?'Insufficient history':acceleration>.5?'Improving':acceleration<-.5?'Deteriorating':'Stable'};
 });
 const periods=[['Daily',attributionDay],['Weekly',attributionWeek],['Monthly',attributionMonth]];
 const basis={};
 for(const [,run] of periods){
  if(!run?.runId||run.pipelineFingerprint!==analysis.pipelineFingerprint||run.economies?.some(e=>e.factorPoints)||Object.hasOwn(basis,run.runId))continue;
  if(Object.hasOwn(previousBasis,run.runId)){basis[run.runId]=previousBasis[run.runId];continue;}
  const saved=await iceRead(bucket,'ice/runs/'+run.runId+'.json');
  basis[run.runId]=saved?.analysis?.pipelineFingerprint===analysis.pipelineFingerprint
   ?Object.fromEntries(saved.analysis.economies.map(e=>[e.ccy,iceFactorPoints(e)])):null;
 }
 const attribution=analysis.economies.map(e=>{
  const current=iceFactorPoints(e);
  const comparisons=periods.map(([period,run])=>{
   const past=run?.pipelineFingerprint===analysis.pipelineFingerprint?(run.economies?.find(x=>x.ccy===e.ccy)?.factorPoints??basis[run.runId]?.[e.ccy]):null;
   if(!current||!past)return {period,asOf:null,change:null,drivers:[],explanation:!run
    ?(period==='Daily'?'No comparable saved snapshot on or before the previous UTC day':'No same-rules snapshot in the comparison window')
    :!sameRules(run)?'Previous snapshot used a different rules fingerprint':'Comparable factor contributions unavailable'};
   const drivers=Object.keys(ICE_MODEL.weights).map(id=>({name:ICE_MODEL.factorNames[id],change:(current[id]||0)-(past[id]||0)}))
    .sort((a,b)=>Math.abs(b.change)-Math.abs(a.change));
   const change=drivers.reduce((sum,d)=>sum+d.change,0),format=n=>(n>=0?'+':'')+n.toFixed(2);
   const material=drivers.filter(d=>Math.abs(d.change)>=.005);
   return {period,asOf:run.capturedAt,change,drivers,
    explanation:material.length?e.ccy+' '+format(change)+' points. '+material.map(d=>d.name+' '+format(d.change)).join(', ')+'.':e.ccy+' score was unchanged to two decimal places.'};
  });
  return {currency:e.ccy,periods:comparisons};
 });
 return {trend,attribution,basis};
}
function tradingScoreIds(){
 return new Set(['policy','cpi','cpi_AUD','gdp_EUR','jobs_EUR','ons_jobs','cot','metals_cot','external_current','external_fdi','VIXCLS','SP500',
  'DCOILBRENTEU','DFII10',...ICE_LIQUIDITY_FEEDS,...ICE_SERIES.filter(d=>d.factor!=='context').map(d=>d.id),
  ...OFFICIAL_MACRO_FEEDS.map(d=>d.id),...POLICY_CHECK_FEEDS.map(d=>d.id)]);
}
const EXTERNAL_ROW_FEEDS=new Set(['external_current','external_fdi']);
const SCORE_FEED_HEALTH=new Set([...EXTERNAL_ROW_FEEDS,'policy_check_CHF']);
function externalRowEntries(feed){
 return Object.entries(feed?.rows||{}).filter(([,p])=>p&&/^\d{4}-\d{2}-\d{2}$/.test(p.d)&&Number.isFinite(p.v)).sort(([a],[b])=>a.localeCompare(b));
}
// A successful recheck can change release freshness without changing a CPI value.
// Compare the retrieval boundary, never the raw timestamp of each successful poll.
function tradingCpiVerification(bundle){
 const feed=bundle?.feeds?.cpi,status=bundle?.status?.cpi;
 const releases=iceReleaseRegistry({bundle});
 return JSON.stringify(ICE_CORE.map(ccy=>{
  const release=releases[ccy+'/cpi'];
  const primary=feed?.['national'+ccy];
  const retained=status?.retained===true||status?.retainedKeys?.includes(ccy)||primary?.fallbackUsed===true;
  const retrieval=primary?.retrievedAt||feed?.retrievedAt;
  const afterPublication=release?.precision==='date'
   ? !!retrieval&&retrieval.slice(0,10)>release.publishedDate
   : Number.isFinite(Date.parse(retrieval))&&Date.parse(retrieval)>=Date.parse(release?.publishedAt);
  return [ccy,status?.ok===true&&!retained&&afterPublication];
 }));
}
function tradingScoreInputs(bundle){
 const points=rows=>rows?.map(({d,v,period})=>[d,v,period]);
 return JSON.stringify([...tradingScoreIds()].sort().map(id=>{
  const feed=bundle?.feeds?.[id];
  const series=Array.isArray(feed?.series)?feed.series.map(s=>[s.id,points(s.points)]):null;
  return [id,points(feed?.points),series,(ICE_LIQUIDITY_FEEDS.includes(id)||SCORE_FEED_HEALTH.has(id))?bundle?.status?.[id]?.ok:null,EXTERNAL_ROW_FEEDS.has(id)?externalRowEntries(feed).map(([ccy,p])=>[ccy,p.d,p.v]):null,Object.entries(feed?.byCurrency||{}).sort(([a],[b])=>a.localeCompare(b))
    .map(([ccy,rows])=>[ccy,points(rows)])];
 }));
}
async function tradingSaveCheck(env,slot,bundle,old,changed,runId,previous){
 const mode=slot.startsWith('full-')?'full':'incremental';
 const checks=Object.entries(bundle.status).filter(([,s])=>s.checkedAt===bundle.capturedAt);
 const feeds=Object.fromEntries(ICE_FEEDS.filter(d=>d.kind==='news-desk'||d.id==='calendar')
  .filter(d=>bundle.feeds[d.id]).map(d=>[d.id,bundle.feeds[d.id]]));
 const status=Object.fromEntries(Object.keys(feeds).map(id=>[id,bundle.status[id]]));
 await env.BUCKET.put('ops/trading-context.json',JSON.stringify({feeds,status}));
 const checkedAt=new Date().toISOString();
 const id=runId||old?.runId||null;
 try{await env.BUCKET.put(POLICY_VERIFICATION_KEY,JSON.stringify({runId:id,checks:bundle.policyVerification||{}}));}
 catch(error){console.error('Policy verification receipt write failed',error.message);}
 const result={slot,mode,checkedAt,changed,runId:id,
  lastInputChangeAt:changed?checkedAt:previous?.lastInputChangeAt||(previous?.changed?previous.checkedAt:null),
  successful:checks.filter(([,s])=>s.ok).length,failed:checks.filter(([,s])=>!s.ok).map(([id])=>id)};
 await env.BUCKET.put('ops/trading-'+mode+'.json',JSON.stringify(result));
 return result;
}
// ---- Calendar actuals (CAL-ACTUALS-1) -------------------------------------------------------
// Context only. Nothing in scoring, ranking, pair bias, Model Lab or LAB_RULE_SOURCES reads these
// records, so the rules fingerprint is unchanged. calActualsRecord runs inside the import
// evaluation, which the staged import performs on the collector PC: the matching happens there
// and the Worker only stores the small objects it writes (one state object, one row per event).
const CAL_ACTUALS_ROOT='market-context/calendar-actuals/v1/';
const CAL_ACTUALS_PROTOCOL='CAL-ACTUALS-1';
// [currency, calendar title, collected official series, calculation, calendar unit, default decimals, divisor to calendar unit]
const CAL_ACTUAL_MAPPINGS=[
 ['USD','CPI m/m','CPIAUCSL','mom','%',1,1],
 ['USD','CPI y/y','CPIAUCNS','yoy','%',1,1],
 ['USD','Core CPI m/m','CPILFESL','mom','%',1,1],
 ['USD','PPI m/m','PPIFIS','mom','%',1,1],
 ['USD','Core PPI m/m','PPIFES','mom','%',1,1],
 ['USD','Non-Farm Employment Change','PAYEMS','change','K',0,1],
 ['USD','Unemployment Rate','jobs_USD','level','%',1,1],
 ['USD','Average Hourly Earnings m/m','CES0500000003','mom','%',1,1],
 ['USD','Unemployment Claims','ICSA','level','K',0,1000],
 ['USD','Advance GDP q/q','gdp_USD','annualized','%',1,1],
 ['USD','Retail Sales m/m','RSAFS','mom','%',1,1],
 ['USD','Core PCE Price Index m/m','PCEPILFE','mom','%',1,1],
 ['USD','Industrial Production m/m','INDPRO','mom','%',1,1],
 ['USD','JOLTS Job Openings','JTSJOL','level','M',2,1000],
 ['USD','Building Permits','PERMIT','level','M',2,1000],
 ['USD','Housing Starts','HOUST','level','M',2,1000],
 ['USD','Federal Funds Rate','policy_check_USD','policy','%',2,1],
 ['GBP','CPI y/y','ons_cpi','level','%',1,1],
 ['GBP','Unemployment Rate','ons_jobs','level','%',1,1],
 ['GBP','Prelim GDP q/q','gdp_GBP','level','%',1,1],
 ['GBP','Official Bank Rate','policy_check_GBP','policy','%',2,1]
].map(([currency,eventName,seriesId,calculation,unit,decimals,divisor])=>({key:currency+'|'+eventName,currency,eventName,seriesId,calculation,unit,decimals,divisor}));
const CAL_UNIT_SCALE={'%':1,K:1e3,M:1e6};
const calActualMapping=(country,title)=>CAL_ACTUAL_MAPPINGS.find(m=>m.currency===country&&m.eventName===title)||null;
const calUnitClass=m=>m.unit==='%'?'percent':'count';
function calRound(v,d){const f=10**d;return Math.round((v+Math.sign(v)*1e-12)*f)/f;}
function calActualPoints(bundle,m){
 const f=bundle?.feeds?.[m.seriesId];
 return (Array.isArray(f?.points)?f.points:[]).filter(p=>p&&typeof p.d==='string'&&Number.isFinite(p.v)).toSorted((a,b)=>a.d.localeCompare(b.d));
}
function calShiftMonths(d,months){const t=new Date(d+'T00:00:00Z');return Number.isFinite(+t)?new Date(Date.UTC(t.getUTCFullYear(),t.getUTCMonth()-months,t.getUTCDate())).toISOString().slice(0,10):null;}
// Value of one period in the calendar's unit, unrounded. null when the comparison period is missing.
function calActualValue(points,m,period){
 const p=points.find(x=>x.d===period);if(!p)return null;let v;
 if(m.calculation==='level'||m.calculation==='policy')v=p.v/m.divisor;
 else{
  const months={mom:1,change:1,yoy:12,annualized:3}[m.calculation];if(!months)return null;
  const prior=points.find(x=>x.d===calShiftMonths(p.d,months));if(!prior)return null;
  if(m.calculation==='change')v=(p.v-prior.v)/m.divisor;
  else{if(!(prior.v>0&&p.v>0))return null;v=m.calculation==='annualized'?100*((p.v/prior.v)**4-1):100*(p.v/prior.v-1);}
 }
 return Number.isFinite(v)?v:null;
}
// Decimals as the calendar prints them ("0.3%" -> 1, "4.00%" -> 2, "189K" -> 0).
function calActualDecimals(text,fallback){const s=String(text??'').trim(),m=s.match(/^[+-]?\d[\d,]*(?:\.(\d+))?\s*[%KMB]?$/i);return m?(m[1]||'').length:fallback;}
// Self-check: the series' latest period before the release must reproduce the calendar's Previous.
function calActualCheck(m,points,event){
 const base=points.at(-1),decimals=calActualDecimals(event.previous,m.decimals);
 if(!base)return {accepted:false,reason:'Official series not collected',decimals};
 const previous=labReleaseNumber(event.previous);
 if(!previous)return {accepted:false,reason:'Calendar Previous is not numeric',baselinePeriod:base.d,decimals};
 if(previous.unit!==calUnitClass(m))return {accepted:false,reason:'Calendar Previous unit differs from the mapping',baselinePeriod:base.d,decimals};
 const raw=calActualValue(points,m,base.d);
 if(raw===null)return {accepted:false,reason:'Previous period cannot be computed from the official series',baselinePeriod:base.d,decimals};
 const computed=calRound(raw,decimals),expected=previous.value/CAL_UNIT_SCALE[m.unit],accepted=Math.abs(computed-expected)<=10**-decimals+1e-9;
 return {accepted,reason:accepted?'Reproduces calendar Previous within one rounding step':'Does not reproduce calendar Previous ('+computed.toFixed(decimals)+m.unit+' vs '+String(event.previous)+')',computed,previousValue:expected,baselinePeriod:base.d,decimals};
}
async function calActualsRecord(env,bundle,now=Date.now()){
 const bucket=env.BUCKET,stamp=new Date(now).toISOString(),stateKey=CAL_ACTUALS_ROOT+'state.json';
 const state=(await iceRead(bucket,stateKey))||{},pending=state.pending||{},mappings=state.mappings||{},closed=state.closed||{};
 const feed=bundle?.feeds?.calendar,retrieved=Date.parse(feed?.retrievedAt);
 const seriesOk=m=>bundle?.status?.[m.seriesId]?.ok===true&&!!bundle?.feeds?.[m.seriesId];
 let captured=0,written=0;
 // 1. Pre-release captures: forecast, Previous self-check and the series' latest period.
 if(bundle?.status?.calendar?.ok===true&&Number.isFinite(retrieved)&&retrieved<=now+120000&&Array.isArray(feed?.events))
  for(const e of feed.events){
   const m=calActualMapping(e?.country,e?.title),eventAt=Date.parse(e?.date);
   if(!m||!Number.isFinite(eventAt)||eventAt<=now||retrieved>=eventAt||!seriesOk(m))continue;
   const eventIso=new Date(eventAt).toISOString(),eventId=await labHash(m.currency+'|'+m.eventName+'|'+eventIso);
   if(closed[eventId])continue;
   const check=calActualCheck(m,calActualPoints(bundle,m),e),old=pending[eventId],forecast=String(e.forecast??'').trim();
   mappings[m.key]={accepted:check.accepted,reason:check.reason,checkedAt:stamp,eventAt:eventIso,computed:check.computed??null,previous:e.previous??null,baselinePeriod:check.baselinePeriod??null};
   pending[eventId]={eventId,country:m.currency,title:m.eventName,eventAt:eventIso,seriesId:m.seriesId,
    // The latest pre-release forecast wins; a blank one never replaces a captured forecast.
    forecast:forecast||old?.forecast||'',forecastRecordedAt:forecast?feed.retrievedAt:old?.forecastRecordedAt||null,
    previous:String(e.previous??''),decimals:check.decimals,baselinePeriod:check.baselinePeriod??null,capturedAt:stamp,
    calendarSource:feed.source||null,accepted:check.accepted,checkReason:check.reason};
   captured++;
  }
 // 2. First-seen matching: the first collection after the scheduled time with a new period.
 for(const p of Object.values(pending)){
  const eventAt=Date.parse(p.eventAt);if(!(eventAt<=now))continue;
  const m=calActualMapping(p.country,p.title);
  const close=reason=>{delete pending[p.eventId];closed[p.eventId]={reason,at:stamp,country:p.country,title:p.title,eventAt:p.eventAt};};
  if(!m){close('Mapping withdrawn');continue;}
  if(!p.accepted){close('Mapping self-check failed before release: '+p.checkReason);continue;}
  if(!p.baselinePeriod){close('No pre-release series period');continue;}
  if(now-eventAt>45*86400000){close('No new official period within 45 days of the release');continue;}
  if(!seriesOk(m))continue;
  const f=bundle.feeds[m.seriesId];if(!(Date.parse(f.retrievedAt)>=eventAt))continue;
  const points=calActualPoints(bundle,m);let period;
  if(m.calculation==='policy'){period=points.find(x=>x.d>p.eventAt.slice(0,10)&&x.d>p.baselinePeriod)?.d;if(!period)continue;}
  else{
   const fresh=points.filter(x=>x.d>p.baselinePeriod);if(!fresh.length)continue;
   if(fresh.length>1){close('More than one new period appeared; the first-seen release cannot be identified');continue;}
   period=fresh[0].d;
  }
  const raw=calActualValue(points,m,period);if(raw===null){close('Actual cannot be computed from the official series');continue;}
  const value=calRound(raw,p.decimals),forecast=labReleaseNumber(p.forecast);
  const comparable=!!forecast&&forecast.unit===calUnitClass(m)&&Date.parse(p.forecastRecordedAt)<eventAt;
  const row={protocol:CAL_ACTUALS_PROTOCOL,id:'official-'+p.eventId,eventId:p.eventId,country:p.country,title:p.title,eventAt:p.eventAt,
   actual:value.toFixed(p.decimals)+m.unit,value,unit:m.unit,decimals:p.decimals,referencePeriod:period,
   forecast:comparable?p.forecast:null,forecastRecordedAt:comparable?p.forecastRecordedAt:null,
   surprise:comparable?calRound(value-forecast.value/CAL_UNIT_SCALE[m.unit],p.decimals):null,
   previous:p.previous,baselinePeriod:p.baselinePeriod,baselineCapturedAt:p.capturedAt,seriesId:m.seriesId,calculation:m.calculation,
   source:f.source||null,sourceRetrievedAt:f.retrievedAt||null,firstSeenAt:stamp,
   method:'Official first-seen: first collection after the scheduled time showing a new period',scored:false};
  // Put-once: a stored actual is frozen; later revisions never overwrite it.
  if(await labPutOnce(bucket,CAL_ACTUALS_ROOT+'rows/'+p.eventId+'.json',row))written++;
  delete pending[p.eventId];closed[p.eventId]={matched:true,at:stamp,country:p.country,title:p.title,eventAt:p.eventAt};
 }
 const kept=Object.fromEntries(Object.entries(closed).sort((a,b)=>String(b[1].at).localeCompare(String(a[1].at))).slice(0,400));
 await bucket.put(stateKey,JSON.stringify({protocol:CAL_ACTUALS_PROTOCOL,updatedAt:stamp,pending,mappings,closed:kept}),{httpMetadata:{contentType:'application/json'}});
 return {captured,written,pending:Object.keys(pending).length};
}

