function mfgStats(points){
 const p=(points||[]).slice(-60);if(p.length<3)throw Error('Too few observations');
 const n=p.length,last=p[n-1],prev=p[n-2];
 const mom=(last.v/prev.v-1)*100;
 const yo=p.find(x=>x.d===(Number(last.d.slice(0,4))-1)+last.d.slice(4)),yoy=yo?(last.v/yo.v-1)*100:null;
 const ch=[];for(let i=1;i<n;i++)ch.push((p[i].v/p[i-1].v-1)*100);
 const base=ch.slice(0,-1).slice(-36),m=base.reduce((s,x)=>s+x,0)/base.length,sd=Math.sqrt(base.reduce((s,x)=>s+(x-m)*(x-m),0)/Math.max(1,base.length-1));
 const z=sd>0?(mom-m)/sd:null;
 const three=n>=4?(last.v/p[n-4].v-1)*100:null;
 const trend=three==null?'flat':three>0.3?'rising':three<-0.3?'falling':'flat';
 return{period:last.d.slice(0,7),latest:Number(last.v.toFixed(2)),previous:Number(prev.v.toFixed(2)),momPct:Number(mom.toFixed(2)),yoyPct:yoy==null?null:Number(yoy.toFixed(2)),threeMonthPct:three==null?null:Number(three.toFixed(2)),z:z==null?null:Number(z.toFixed(2)),trend,observations:n};
}

