 const obs=ds.series[keys[0]].observations,pts=Object.keys(obs).flatMap(i=>{const t=tv[i]&&tv[i].id,raw=obs[i][0],v=Number(raw);return raw!=null&&/^\d{4}-\d{2}$/.test(t||'')&&Number.isFinite(v)?[{d:t+'-01',v}]:[];}).sort((a,b)=>a.d.localeCompare(b.d));
