async function storageApi(request,env){
  const headers={'Cache-Control':'no-store'};
  if(request.method!=='GET')return Response.json({error:'Use GET'},{status:405,headers});
  if(!env.BUCKET)return Response.json({error:'Saved evidence unavailable'},{status:503,headers});
  const groups=new Map();let bytes=0,objects=0,cursor,truncated=false;
  for(let page=0;page<40;page++){
    const listed=await env.BUCKET.list({limit:1000,...(cursor?{cursor}:{})});
    for(const o of listed.objects||[]){const parts=String(o.key).split('/'),p=parts.length>2?parts[0]+'/'+parts[1]:parts[0],g=groups.get(p)||{p,bytes:0,n:0};const size=Number(o.size)||0;g.bytes+=size;g.n++;groups.set(p,g);bytes+=size;objects++;}
    if(!listed.truncated){cursor=null;break;}
    cursor=listed.cursor;if(page===39)truncated=true;
  }
  return Response.json({bytes,objects,truncated,groups:[...groups.values()].sort((a,b)=>b.bytes-a.bytes).slice(0,12),checkedAt:new Date().toISOString()},{headers});
}
async function tradeCompareApi(request,env){
  const headers={'Cache-Control':'no-store'};
  if(request.method!=='GET')return Response.json({error:'Use GET'},{status:405,headers});
  if(!env.BUCKET)return Response.json({error:'Saved evidence unavailable'},{status:503,headers});
  const params=new URL(request.url).searchParams,broker=params.get('broker')==='PU Prime'?'PU Prime':'HFM';
  const items=String(params.get('q')||'').split(',').slice(0,60).map(x=>x.split('@')).filter(x=>/^[A-Z]{6}$/.test(x[0]||'')&&Number.isFinite(Date.parse(x[1]||'')));
  if(!items.length)return Response.json({error:'No valid trades supplied'},{status:400,headers});
  try{
    const feed=await iceRead(env.BUCKET,'broker/'+(broker==='HFM'?'HFM':'PUPrime')+'_H1H4.json');
    const bySym=new Map();
    for(const r of feed?.rows||[]){if(r.timeframe!=='H4'||r.status!=='COMPLETED')continue;(bySym.get(r.symbol)||bySym.set(r.symbol,[]).get(r.symbol)).push(r);}
    const trades=items.map(([sym,at])=>{
      const now=Date.parse(at),bars=(bySym.get(sym)||[]).filter(b=>Date.parse(b.endUTC)<=now).map(b=>({...b,retrievedUTC:b.endUTC}));
      if(bars.length<30)return{sym,at,ok:false,reason:'Stored H4 bars do not reach back to this time'};
      const [s]=assessStructureCapture({rows:bars,broker},now);
      if(!s||!s.fresh||!(s.atr14>0))return{sym,at,ok:false,reason:'H4 data around this time is incomplete'};
      const closes=[...new Map(bars.map(b=>[b.openUTC,b])).values()].sort((a,b)=>a.openUTC.localeCompare(b.openUTC)).map(b=>b.close);
      return{sym,at,ok:true,asOf:s.latestBarEndUTC,atr:s.atr14,close:s.lastClose,direction:s.direction,swingBuy:s.reviewLevels.buyInvalidation,swingSell:s.reviewLevels.sellInvalidation,move1d:closes.length>6?s.lastClose-closes[closes.length-7]:null};
    });
    return Response.json({broker,trades},{headers});
  }catch{return Response.json({error:'Could not load saved price history'},{status:502,headers});}
}

const REVIEW_QUOTE_MAX=120000;
const REVIEW_SPEC_FIELDS=['tickSize','pipSize','point','tickValueProfit','tickValueLoss','contractSize','minLot','lotStep','maxLot'];
const REVIEW_SPEC_MAX=24*3600000;

function executionQuote(feeds,broker,symbol,contract,now){
  const rows=feeds.filter(f=>f.broker===broker&&f.kind==='quotes').flatMap(f=>
    (f.rows||[]).filter(q=>q.symbol===symbol&&q.brokerSymbol===contract&&Number.isFinite(Date.parse(q.retrievedUTC)))
      .map(q=>({q,feed:f}))).sort((a,b)=>Date.parse(b.q.retrievedUTC)-Date.parse(a.q.retrievedUTC));
  const selected=rows[0];
  if(!selected)return {quote:null,specification:null,reason:'No registered broker quote'};
  const {q,feed}=selected;
  const conflict=rows.some(r=>r!==selected&&Date.parse(r.q.retrievedUTC)===Date.parse(q.retrievedUTC)
    && ['bid','ask','quoteUTC',...REVIEW_SPEC_FIELDS].some(k=>r.q[k]!==q[k]));
  const valid=!conflict&&q.clockValid===true&&q.terminalConnected===true&&q.sourceStatus==='OK'
    &&Number.isFinite(q.bid)&&Number.isFinite(q.ask)&&q.bid>0&&q.ask>=q.bid
    &&[q.quoteUTC,q.retrievedUTC,feed.receivedAt,feed.sourceModifiedUTC].every(t=>diDated(t,now,REVIEW_QUOTE_MAX))
    &&Date.parse(q.quoteUTC)<=Date.parse(q.retrievedUTC)&&Date.parse(q.retrievedUTC)<=Date.parse(feed.receivedAt);
  const quote={broker,symbol,brokerSymbol:contract,bid:Number.isFinite(q.bid)?q.bid:null,ask:Number.isFinite(q.ask)?q.ask:null,
    quoteUTC:q.quoteUTC||null,retrievedUTC:q.retrievedUTC,receivedAt:feed.receivedAt||null,source:feed.feedId,current:valid};
  const specsCurrent=diDated(q.specRetrievedUTC,now,REVIEW_SPEC_MAX)&&Date.parse(q.specRetrievedUTC)<=Date.parse(q.retrievedUTC);
  const specification=specsCurrent&&q.priceUnitType==='fx-pip'&&/^[A-Z]{3}$/.test(q.valueCurrency||'')
    &&REVIEW_SPEC_FIELDS.every(k=>Number.isFinite(q[k])&&q[k]>0)&&q.minLot<=q.maxLot
    ?{...Object.fromEntries(REVIEW_SPEC_FIELDS.map(k=>[k,q[k]])),valueCurrency:q.valueCurrency,specRetrievedUTC:q.specRetrievedUTC}:null;
  return {quote,specification,reason:conflict?'Conflicting broker quote or specification':valid?null:'Broker quote stale or unverified'};
}

function reviewObservedLevels(quote,spec,structure,move){
  if(!quote?.current||!spec||structure.status!=='Native H1/H4 agreement'||!move.ok)return null;
  if([structure.h1.barEnd,structure.h4.barEnd].some(t=>Date.parse(t)>Date.parse(quote.quoteUTC)))return null;
  const side=move.direction==='Higher'?1:-1;
  const {tickSize}=spec, h4=structure.h4;
  const entry=side===1?quote.ask:quote.bid,exitSide=side===1?quote.bid:quote.ask;
  const invalidation=side===1?h4.invalidation.buyInvalidation:h4.invalidation.sellInvalidation;
  const target=side===1?h4.rangeHigh:h4.rangeLow;
  if(![entry,exitSide,invalidation,target].every(n=>Number.isFinite(n)&&n>0&&topGrid(n/tickSize)))return null;
  const stop=Number(((Math.round(invalidation/tickSize)-side)*tickSize).toPrecision(14));
  const risk=side*(entry-stop),reward=side*(target-entry);
  if(!(stop>0&&risk>0&&reward>0&&side*(exitSide-stop)>0&&side*(target-exitSide)>0))return null;
  return {side:side===1?'Buy':'Sell',entry,invalidation,stop,target,rewardRisk:reward/risk,risk,
    stopTicks:side*(exitSide-stop)/tickSize,targetTicks:side*(target-exitSide)/tickSize,
    method:'Current quote, observed H4 swing invalidation and prior H4 range boundary'};
}

const REVIEW_MIN_ADJUSTED_R=1.5;

function reviewAdjustedRewardRisk(scenario,quote,cost){
  if(!scenario||!quote?.current||!cost)return null;
  const {entry,stop,target}=scenario;
  const side=scenario.side==='Buy'?1:scenario.side==='Sell'?-1:0;
  const {commissionBps,slippageBps}=cost;
  const spread=quote.ask-quote.bid;
  if(![entry,stop,target].every(v=>Number.isFinite(v)&&v>0)
    ||![spread,commissionBps,slippageBps].every(v=>Number.isFinite(v)&&v>=0))return null;
  const grossRisk=side*(entry-stop),grossReward=side*(target-entry);
  if(grossRisk<=0||grossReward<=0)return null;
  const commission=entry*commissionBps/10000,slippage=entry*slippageBps/10000;
  const allowance=spread+commission+slippage;
  if(!Number.isFinite(allowance))return null;
  const netRisk=grossRisk+allowance,netReward=grossReward-allowance;
  return {spread,commission,slippage,commissionBps,slippageBps,netRisk,netReward,ratio:netReward/netRisk,
    minimum:REVIEW_MIN_ADJUSTED_R,verifiedAt:cost.verifiedAt};
}

function reviewChecklistGrade(robustness,checks){
  if(robustness==='Insufficient Evidence')return 'Ungraded';
  if(!['Robust','Moderate'].includes(robustness)||checks.some(c=>c.mandatory&&c.status!=='Pass'))return 'C';
  const remaining=checks.filter(c=>!c.mandatory&&c.status!=='Pass').length;
  if(remaining===0&&robustness==='Robust')return 'A+';
  return remaining<=1?'A':'B';
}

function reviewChecklist(pair,structure,quote,adjusted,now){
  const check=(label,status,detail,mandatory=false)=>({label,status,detail,mandatory});
  const assess=x=>x===true?'Pass':x===false?'Conflict':'Unavailable';
  const robustness=pair?.macro?.robustness||'Insufficient Evidence';
  const macro=pair?.macro, direction=macro?.eligible?diSign(macro.bias):null;
  const cross=(pair?.context?.crossAsset?.rows||[]).filter(r=>r.relevant);
  const crossState=cross.some(r=>r.verdict==='Conflicts')?'Conflict':
    !cross.length||cross.some(r=>r.verdict==='Unavailable')?'Unavailable':assess(cross.some(r=>r.verdict==='Supports'));
  const frames=[structure.h1,structure.h4,structure.d1];
  const structureState=![-1,1].includes(direction)||frames.some(f=>!f?.ok)?null:
    frames.every(f=>f.direction===(direction===1?'Upward range break':'Downward range break'));
  const event=pair?.context?.event;
  const alignment=pair?.alignment?.mediumTerm;
  const microCurrent=diDated(pair?.micro?.volatility?.barEnd,now,72*DI_HOUR);
  const checks=[
    check('Frozen robustness class',assess(['Robust','Moderate'].includes(robustness)?true:robustness==='Fragile'?false:null),robustness,true),
    check('Mandatory macro evidence',assess(macro?.eligible||null),macro?.eligible?'Both economies eligible':'Evidence gate incomplete',true),
    check('Macro and broker freshness',assess(macro?.eligible&&quote?.current&&structure.h1.ok&&structure.h4.ok?true:null),
      'Saved macro assessment, quote and native H1/H4',true),
    check('48-hour event risk',assess(event?.state==='No covered event within 48h'?true:event?.event?false:null),event?.state||'Unavailable',true),
    ...(pair?.context?.signal?[check('H1/H4 signal review','Unavailable',pair.context.signal.reason,true)]:[]),
    check('Macro/Micro alignment',assess(microCurrent&&alignment==='Aligned'?true:microCurrent&&alignment==='Countertrend'?false:null),
      microCurrent?alignment:'Current native micro input unavailable'),
    check('Cross-asset confirmation',crossState,cross.map(r=>r.label+' '+r.verdict).join(' / ')||'No applicable inputs'),
    check('Native H1/H4/D1 confirmation',assess(structureState),frames.map(f=>f?.frame+' '+(f?.direction||'Unavailable')).join(' / ')),
    check('Cost-adjusted reward-to-risk',assess(adjusted?adjusted.ratio>=REVIEW_MIN_ADJUSTED_R:null),'Minimum '+REVIEW_MIN_ADJUSTED_R+' R')
  ];
  return {grade:reviewChecklistGrade(robustness,checks),checks,direction};
}

function reviewResearchCandidate(checklist,brokerEvidenceEligible,scenario,quote,adjusted){
  const side=scenario?.side==='Buy'?1:scenario?.side==='Sell'?-1:0;
  if(!brokerEvidenceEligible||!quote?.current||!side||checklist.direction!==side
    ||!['A+','A'].includes(checklist.grade)||!(adjusted?.ratio>=REVIEW_MIN_ADJUSTED_R))return null;
  return {side:scenario.side,entry:scenario.entry,entryZone:[quote.bid,quote.ask],stop:scenario.stop,target:scenario.target,
    ratio:adjusted.ratio,quoteUTC:quote.quoteUTC};
}

function buildExecutionReview(record,feeds,universe,symbol,broker,now,costs=[],tradingContext=null,microInputs=null){
  const base=symbol.slice(0,3),quoteCurrency=symbol.slice(3);
  const bundle=tradingContextBundle(record?.bundle||{feeds:{},status:{}},tradingContext);
  const group=diBrokerGroups(feeds,broker,universe,now).get(symbol);
  const signal=tradingSignalRisk(bundle,[base,quoteCurrency],now);
  const evidence=executionQuote(feeds,broker,symbol,group?.contract,now);
  const move=diBrokerMove(group,'1H',now),structure=diExecution(group,now,broker,move,'1H');
  const scenario=reviewObservedLevels(evidence.quote,evidence.specification,structure,move);
  const cost=costs.find(p=>p?.broker===broker&&p.contract===group?.contract&&typeof p.evidence==='string'&&p.evidence.trim()
    &&diDated(p.verifiedAt,now,30*86400000)&&[p.minStopTicks,p.roundTripBps].every(n=>Number.isFinite(n)&&n>=0));
  const calendar=diCatalysts(bundle,base,quoteCurrency,'24H',now);
  const highImpact=calendar.current?horizonEvents(bundle.feeds.calendar.events,[base,quoteCurrency],24,now)
    .filter(x=>String(x.impact).toLowerCase()==='high'): [];
  const gates=[
    {label:'Fresh registered quote',passed:!!evidence.quote?.current,detail:evidence.reason},
    {label:'Verified contract specifications',passed:!!evidence.specification},
    {label:'Independent native H1/H4 structure',passed:structure.status==='Native H1/H4 agreement',detail:structure.status},
    {label:'Observed entry, stop and target',passed:!!scenario},
    {label:'Verified broker stop distance and cost assumptions',passed:!!(scenario&&cost
      &&scenario.stopTicks+1e-6>=cost.minStopTicks&&scenario.targetTicks+1e-6>=cost.minStopTicks)},
    {label:'Current calendar without a listed high-impact event in 24h',passed:calendar.current&&!highImpact.length},
    {label:'No pending release or geopolitical alert',passed:!signal,detail:signal?.reason}
  ];
  const brokerEvidenceEligible=gates.every(g=>g.passed);
  const adjusted=reviewAdjustedRewardRisk(scenario,evidence.quote,cost);
  const pair=Array.isArray(record?.analysis?.economies)
    ?buildDirectionIntelligence(record,feeds,universe,'1H',broker,now,symbol,tradingContext,microInputs).rows[0]:null;
  const checklist=reviewChecklist(pair,structure,evidence.quote,adjusted,now);
  const candidate=reviewResearchCandidate(checklist,brokerEvidenceEligible,scenario,evidence.quote,adjusted);
  return {symbol,broker,contract:group?.contract||null,checkedAt:new Date(now).toISOString(),currency:quoteCurrency,
    ...evidence,move,structure,scenario,calendar,highImpact,gates,brokerEvidenceEligible,
    adjusted,checklist:{grade:checklist.grade,checks:checklist.checks},candidate,
    cost:cost?{verifiedAt:cost.verifiedAt,minStopTicks:cost.minStopTicks,roundTripBps:cost.roundTripBps}:null,
    executionReady:false};
}

async function executionReviewApi(request,env){
  const headers={'Cache-Control':'no-store'};
  if(request.method!=='GET')return Response.json({error:'Use GET'},{status:405,headers});
  if(!env.BUCKET)return Response.json({error:'Saved evidence unavailable'},{status:503,headers});
  const query=new URL(request.url).searchParams,symbol=query.get('symbol'),broker=query.get('broker');
  if(!Object.hasOwn(BROKER_UNIVERSE,broker)||!BROKER_UNIVERSE[broker].some(m=>m.core&&m.asset==='fx'&&m.symbol===symbol))
    return Response.json({error:'Unknown broker or core FX symbol'},{status:400,headers});
  try{
    const ids=Object.entries(BROKER_FEEDS).filter(([,f])=>f.kind==='daily'||(f.broker===broker&&['quotes','history'].includes(f.kind))).map(([id])=>id);
    const [record,context,microInputs,...feeds]=await Promise.all([iceRead(env.BUCKET,'ice/latest.json'),iceRead(env.BUCKET,'ops/trading-context.json'),iceRead(env.BUCKET,'ops/micro-inputs.json'),...ids.map(id=>iceRead(env.BUCKET,'broker/'+id+'.json'))]);
    let costs=[];
    try{const configured=JSON.parse(env.TOP_MARKETS_VERIFIED_COSTS||'[]');if(Array.isArray(configured))costs=configured;}catch{}
    return Response.json(buildExecutionReview(record,feeds.filter(Boolean),BROKER_UNIVERSE,symbol,broker,Date.now(),costs,context,microInputs),{headers});
  }catch{return Response.json({error:'Could not read saved broker review evidence'},{status:502,headers});}
}








const dataCache=new Map();
async function cached(request,ctx,seconds,fn){
 const key=request.url,now=Date.now(),hit=dataCache.get(key);
 if(hit&&hit.expires>now)return new Response(hit.body,{headers:hit.headers});
 try{
  const body=JSON.stringify({...await fn(),retrievedAt:new Date().toISOString()});
  const headers={'Content-Type':'application/json','Cache-Control':'private, max-age='+seconds,'X-Content-Type-Options':'nosniff'};
  if(dataCache.size>250)dataCache.delete(dataCache.keys().next().value);
  dataCache.set(key,{body,headers,expires:Date.now()+seconds*1000});
  return new Response(body,{headers});
 }catch(e){return Response.json({error:e.safe||'Source unavailable. No value has been substituted.',retrievedAt:new Date().toISOString()},{status:502,headers:{'Cache-Control':'no-store'}});}
}
async function remote(url,json=true,accept=null){
 const target=new URL(url),headers={Accept:accept||(json?'application/json':'text/csv'),'User-Agent':'Mozilla/5.0 (compatible; MacroICE/1.0)'}; const guardian=target.hostname.endsWith('theguardian.com');if(guardian){headers['User-Agent']='MacroICE/1.0 (personal research RSS reader)';headers['Accept-Language']='en-GB,en;q=0.9';headers['Accept-Encoding']='gzip, deflate, br';}
 if(target.hostname==='comtradeapi.un.org'){
 const key=globalThis.process?.env?.COMTRADE_KEY;if(key)headers['Ocp-Apim-Subscription-Key']=key;
 target.searchParams.delete('subscription-key');target.searchParams.delete('api_key');target.searchParams.set('cmdCode','TOTAL,27');target.searchParams.set('flowCode','X,M');
 if(!key&&!target.pathname.includes('/preview/'))target.pathname=target.pathname.replace('/public/v1/','/public/v1/preview/');
 }
 for(let attempt=0;attempt<4;attempt++)try{
 const r=await fetch(target,{signal:AbortSignal.timeout(30000),headers});
 if(!r.ok){if(r.status===400){const safe=new URL(target);for(const k of [...safe.searchParams.keys()])if(/key|secret|token/i.test(k))safe.searchParams.set(k,'[REDACTED]');console.error('HTTP 400',safe.href,Object.fromEntries(safe.searchParams));}throw Object.assign(Error('Data source returned HTTP '+r.status+'. No value was substituted.'),{status:r.status});}
 return await (json?r.json():r.text());
 }catch(e){if(e.status===400||(e.status&&e.status!==429&&e.status<500&&!(guardian&&e.status===403&&attempt<2))||attempt===3)throw e;await new Promise(resolve=>setTimeout(resolve,[2000,5000,12000][attempt]));}
}
export function parseFred(text,id){const lines=text.trim().split(/\r?\n/);if(!lines[0]?.toLowerCase().includes('date'))throw Error('format');return lines.slice(1).flatMap(line=>{const [d,raw]=line.split(',');const v=Number(raw);return /^\d{4}-\d{2}-\d{2}$/.test(d)&&raw&&raw!=='.'&&Number.isFinite(v)?[{d,v}]:[];}).sort((a,b)=>a.d.localeCompare(b.d));}
export function parseWorldBank(data){if(!Array.isArray(data)||!Array.isArray(data[1]))throw Error('format');const rows={};for(const r of data[1]){if(!r.countryiso3code||r.value===null||!Number.isFinite(r.value))continue;const id=r.countryiso3code;if(!rows[id]||r.date>rows[id].date)rows[id]={value:r.value,date:r.date};}return rows;}
export function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if(c==='\n'&&!quoted){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field='';}else field+=c;}if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row);}return rows;}
async function savedFredSeries(bucket,overview=false){
 const bundle=bucket?(await iceRead(bucket,'ice/latest.json'))?.bundle:null;
 const series={};
 if(!bundle)return {series};
 for(const d of FRED){
  if(overview&&!['DGS2','DGS10','DFII10','DTWEXBGS'].includes(d.id))continue;
  const candidates=Object.entries(bundle.feeds||{}).filter(([,f])=>
   f.series===d.id&&f.points?.length);
  // Multiple consumers may collect the same FRED series. Prefer the newest actual retrieval.
  candidates.sort(([,a],[,b])=>Date.parse(b.retrievedAt)-Date.parse(a.retrievedAt));
  const [key,feed]=candidates[0]||[];
  if(!feed)continue;
  const status=bundle.status?.[key],retained=status?.ok===false;
  series[d.id]={...d,points:feed.points.slice(overview?-24:-800),source:feed.source,retrievedAt:feed.retrievedAt,
   saved:true,retained,fallback:retained,failure:retained?(status.error||'Latest source request failed.'):null};
 }
 const feeds=bundle.feeds||{},macro={};
 for(const d of INDICATORS.filter(d=>d.code)){
  const entry=ICE_FEEDS.filter(f=>f.code===d.code).map(f=>feeds[f.id]).find(f=>f?.byCurrency||f?.rows);
  if(!entry)continue;
  const rows={};
  for(const e of ECONOMIES){
   const p=entry.byCurrency?.[e.ccy]?.at(-1)||entry.rows?.[e.ccy]||entry.rows?.[e.iso];
   if(p?.d&&Number.isFinite(p.v))rows[e.iso]={date:p.d.slice(0,4),value:p.v};
  }
  if(Object.keys(rows).length)macro[d.id]={rows,source:entry.source,retrievedAt:entry.retrievedAt};
 }
 const latestByCurrency=(feed,convert)=>Object.fromEntries(Object.entries(feed?.byCurrency||{}).flatMap(([ccy,points])=>{const p=points.at(-1);return p?[[ccy,convert(p)]]:[];}));
 const policy=feeds.policy?{rows:latestByCurrency(feeds.policy,p=>({date:p.d,value:p.v})),source:feeds.policy.source,retrievedAt:feeds.policy.retrievedAt}:null;
 const cot=feeds.cot?{rows:latestByCurrency(feeds.cot,p=>({date:p.d,netPct:p.v,net:p.net,long:p.long,short:p.short,oi:p.oi})),source:feeds.cot.source,retrievedAt:feeds.cot.retrievedAt}:null;
 const collection={sourceSuccess:Object.values(bundle.status||{}).filter(s=>s.ok).length,sourceTotal:Object.keys(bundle.status||{}).length,capturedAt:bundle.capturedAt};
 return {series,macro,policy,cot,fx:feeds.fx||null,collection};
}

const HKMA_POLICY_URL='https://api.hkma.gov.hk/public/market-data-and-statistics/daily-monetary-statistics/daily-figures-interbank-liquidity?sortby=end_of_date&sortorder=desc&pagesize=10';
const MNB_POLICY_URL='https://www.mnb.hu/en/jegybanki_alapkamat_alakulasa';
const MAS_POLICY={date:'2026-10-14',stance:'Appreciation pace maintained',definition:'MAS maintained the slope, width and centre of its SGD nominal effective exchange-rate policy band. Singapore uses an exchange-rate policy target.',
 sourceBank:'Monetary Authority of Singapore',source:'https://www.mas.gov.sg/news/monetary-policy-statements/2026/mas-monetary-policy-statement-14oct26'};
const PUBLISHER_POLICY_CAPTURE={"HKD":{"date":"2026-11-13","value":4.25,"definition":"Discount Window Base Rate, daily observation.","sourceBank":"Hong Kong Monetary Authority","source":"https://api.hkma.gov.hk/public/market-data-and-statistics/daily-monetary-statistics/daily-figures-interbank-liquidity?sortby=end_of_date&sortorder=desc&pagesize=10"},"HUF":{"date":"2026-08-26","value":5.5,"currentTable":true,"checkedAt":"2026-11-16T02:47:20.441Z","definition":"Central bank base rate. Observation date is when the current rate took effect.","sourceBank":"Magyar Nemzeti Bank","source":"https://www.mnb.hu/en/jegybanki_alapkamat_alakulasa"}};
let publisherPolicyCache=null,publisherPolicyRequest=null;
function parseHkmaPolicy(data,today){
 const rows=(data?.result?.records||[]).filter(r=>/^\d{4}-\d{2}-\d{2}$/.test(r.end_of_date)&&r.end_of_date<=today&&
  Number.isFinite(r.disc_win_base_rate)&&r.disc_win_base_rate>=0&&r.disc_win_base_rate<=30);
 const current=rows.sort((a,b)=>b.end_of_date.localeCompare(a.end_of_date))[0];
 return current?{date:current.end_of_date,value:current.disc_win_base_rate,definition:'Discount Window Base Rate, daily observation.',
  sourceBank:'Hong Kong Monetary Authority',source:HKMA_POLICY_URL}:null;
}
function parseMnbPolicy(html,stamp){
 const table=html.match(/Central bank base rate history[\s\S]{0,1800}?<tbody>([\s\S]*?)<\/tbody>/i)?.[1];
 const match=table?.match(/<tr>\s*<td>\s*(\d{1,2} [A-Za-z]+ \d{4})\s*<\/td>\s*<td>\s*(-?\d+(?:\.\d+)?)%\s*<\/td>/i);
 if(!match)return null;
 const effective=Date.parse(match[1]+' UTC'),value=Number(match[2]);
 if(!Number.isFinite(effective)||effective>Date.parse(stamp)||value<-5||value>50)return null;
 return {date:new Date(effective).toISOString().slice(0,10),value,currentTable:true,checkedAt:stamp,
  definition:'Central bank base rate. Observation date is when the current rate took effect.',
  sourceBank:'Magyar Nemzeti Bank',source:MNB_POLICY_URL};
}
async function publisherPolicyRows(){
 if(publisherPolicyCache?.expires>Date.now())return publisherPolicyCache.rows;
 if(publisherPolicyRequest)return publisherPolicyRequest;
 const get=async (url,json)=>{
  const r=await fetch(url,{signal:AbortSignal.timeout(4000),redirect:'error'});
  if(!r.ok)throw Error('Publisher HTTP '+r.status);
  return json?r.json():r.text();
 };
 publisherPolicyRequest=(async()=>{
  const [hk,hu]=await Promise.allSettled([get(HKMA_POLICY_URL,true),get(MNB_POLICY_URL,false)]);
  const stamp=new Date().toISOString(),rows={...PUBLISHER_POLICY_CAPTURE,SGD:MAS_POLICY};
  const hkd=hk.status==='fulfilled'?parseHkmaPolicy(hk.value,stamp.slice(0,10)):null;
  const huf=hu.status==='fulfilled'?parseMnbPolicy(hu.value,stamp):null;
  if(hkd)rows.HKD=hkd;
  if(huf)rows.HUF=huf;
  publisherPolicyCache={rows,expires:Date.now()+(hkd&&huf?3600000:300000)};
  return rows;
 })();
 try{return await publisherPolicyRequest;}finally{publisherPolicyRequest=null;}
}

async function api(request,env,ctx){const u=new URL(request.url);if(u.pathname==='/api/config')return Response.json({economies:ECONOMIES,indicators:INDICATORS,fred:FRED,market:MARKET,pending:PENDING,reference:REFERENCE,snapshots:SNAPSHOTS,unattendedHistory:await unattendedHistory(env.BUCKET),twelveData:!!env.TWELVE_DATA_API_KEY,dxyConfigured:!!env.TWELVE_DXY_SYMBOL});
 if(u.pathname==='/api/policy')return cached(request,ctx,21600,async()=>{const start=new Date(Date.now()-90*86400000).toISOString().slice(0,10);const source='https://stats.bis.org/api/v1/data/WS_CBPOL/D.US+XM+GB+JP+CH+CA+AU+NZ+NO+SE+MX+ZA+TR+CN+SG+HK+PL+HU+CZ+IN+BR+TH?startPeriod='+start+'&format=csv';const csv=parseCSV(await remote(source,false));const h=csv.shift();const ix=n=>h.indexOf(n);if(ix('OBS_VALUE')<0)throw Error('format');const rows={};for(const r of csv){const area=r[ix('REF_AREA')],date=r[ix('TIME_PERIOD')],raw=r[ix('OBS_VALUE')],value=Number(raw);if(!raw||!Number.isFinite(value)||!/^\d{4}-\d{2}-\d{2}$/.test(date))continue;const ccy=area==='XM'?'EUR':ECONOMIES.find(e=>e.flag===area)?.ccy;if(ccy&&(!rows[ccy]||date>rows[ccy].date))rows[ccy]={date,value,definition:r[ix('COMPILATION')],sourceBank:r[ix('SOURCE_REF')]};}if(!Object.keys(rows).length)throw Error('empty');return{rows,source,frequency:'Daily policy-rate observations',classification:'BIS series definitions vary across monetary regimes'};});
 if(u.pathname==='/api/cot/flip'){
  if(request.method!=='GET')return new Response(null,{status:405,headers:{Allow:'GET'}});
  const market=u.searchParams.get('market')||'fx';
  if(!['fx','fx-combined'].includes(market)&&!Object.hasOwn(COT_PHYSICAL_MARKETS,market))return Response.json({error:'Unknown COT market'},{status:400});
  return cached(request,ctx,1800,async()=>{
   const today=new Date().toISOString().slice(0,10);
   const mapping={...COT_CODES,...(market==='fx-combined'?COT_FX_COMBINED_CROSSES:COT_FX_CROSSES)};
   const source=cotFlipSource(mapping,today,market);
   return {...buildCotFlips(await remote(source),mapping,today,market),source};
  });
 }
 if(u.pathname==='/api/cot')return cached(request,ctx,21600,async()=>{const params=new URLSearchParams({'$where':"cftc_contract_market_code in ("+Object.keys(COT_CODES).map(c=>"'"+c+"'").join(',')+")",'$select':'cftc_contract_market_code,market_and_exchange_names,report_date_as_yyyy_mm_dd,lev_money_positions_long,lev_money_positions_short,open_interest_all','$order':'report_date_as_yyyy_mm_dd DESC','$limit':'600'});const source='https://publicreporting.cftc.gov/resource/gpe5-46if.json?'+params;const data=await remote(source);if(!Array.isArray(data)||!data.length)throw Error('empty');const rows={};for(const r of data){const ccy=COT_CODES[r.cftc_contract_market_code];if(!ccy||rows[ccy])continue;const long=Number(r.lev_money_positions_long),short=Number(r.lev_money_positions_short),oi=Number(r.open_interest_all);if(!Number.isFinite(long)||!Number.isFinite(short)||!Number.isFinite(oi)||oi<=0)continue;rows[ccy]={date:r.report_date_as_yyyy_mm_dd.slice(0,10),long,short,net:long-short,oi,netPct:(long-short)/oi*100,market:r.market_and_exchange_names,contract:r.cftc_contract_market_code};}return{rows,source,frequency:'Weekly; Tuesday positions, typically released Friday',classification:'TFF futures only; leveraged funds. No spot dealer-inventory inference.'};});
 if(u.pathname==='/api/public-market'){const d=MARKET.find(d=>d.id===u.searchParams.get('id'));if(!d)return Response.json({error:'Unknown symbol'},{status:400});return cached(request,ctx,3600,async()=>{const data=await remote('https://query1.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(d.symbol)+'?range=1y&interval=1d');const r=data.chart?.result?.[0],close=r?.indicators?.quote?.[0]?.close;if(!r?.timestamp||!close)throw Error('format');const points=r.timestamp.flatMap((t,i)=>Number.isFinite(close[i])?[{d:new Date(t*1000).toISOString().slice(0,10),v:close[i]}]:[]).sort((a,b)=>a.d.localeCompare(b.d));if(!points.length)throw Error('empty');return{id:d.id,points,source:'https://finance.yahoo.com/quote/'+encodeURIComponent(d.symbol)+'/',symbol:d.symbol,classification:d.note+'; daily bars may include the current partial session; unofficial endpoint can change',quoteTime:r.meta?.regularMarketTime?new Date(r.meta.regularMarketTime*1000).toISOString():null,delay:r.meta?.exchangeDataDelayedBy??null};});}
 if(u.pathname==='/api/macro'){const def=INDICATORS.find(d=>d.id===u.searchParams.get('id')&&d.code);if(!def)return Response.json({error:'Unknown indicator'},{status:400});return cached(request,ctx,21600,async()=>{const year=new Date().getUTCFullYear();const source='https://api.worldbank.org/v2/country/'+ECONOMIES.map(e=>e.iso).join(';')+'/indicator/'+def.code+'?format=json&date='+(year-5)+':'+year+'&per_page=500';return {id:def.id,frequency:'Annual',source,rows:parseWorldBank(await remote(source)),classification:'Structural context; not a current macro release'};});}
 if(u.pathname==='/api/us-interest')return cached(request,ctx,900,()=>loadUSInterestSources(env));
 if(u.pathname==='/api/fred/saved'&&u.searchParams.get('view')==='overview'){
  const saved=await savedFredSeries(env.BUCKET,true);
  return Response.json({series:saved.series,collection:saved.collection},{headers:{'Cache-Control':'no-store'}});
 }
 if(u.pathname==='/api/fred/saved'){const [saved,publisherPolicy]=await Promise.all([savedFredSeries(env.BUCKET),publisherPolicyRows()]);return Response.json({...saved,publisherPolicy},{headers:{'Cache-Control':'no-store'}});}
 if(u.pathname==='/api/fred'){const d=FRED.find(d=>d.id===u.searchParams.get('id'));if(!d)return Response.json({error:'Unknown series'},{status:400});return cached(request,ctx,3600,async()=>{const start=new Date(Date.now()-800*86400000).toISOString().slice(0,10);const url='https://fred.stlouisfed.org/graph/fredgraph.csv?id='+d.id+'&cosd='+start;const points=parseFred(await remote(url,false),d.id);if(!points.length)throw Error('empty');return {id:d.id,points,source:'https://fred.stlouisfed.org/series/'+d.id,unit:d.unit,frequency:d.frequency};});}
 if(u.pathname==='/api/fx'&&env.BUCKET){const saved=await iceRead(env.BUCKET,'ice/latest.json'),fx=saved?.bundle?.feeds?.fx;if(fx?.history?.length)return Response.json({history:fx.history,source:fx.source,retrievedAt:fx.retrievedAt,retained:saved.bundle.status?.fx?.ok===false,fallback:saved.bundle.status?.fx?.ok===false,classification:'Saved official daily central-bank reference history; not executable quotes.'},{headers:{'Cache-Control':'no-store'}});}
 if(u.pathname==='/api/fx')return cached(request,ctx,3600,async()=>{const start=new Date(Date.now()-220*86400000).toISOString().slice(0,10);const source='https://api.frankfurter.dev/v2/rates?base=USD&from='+start+'&quotes='+ECONOMIES.filter(e=>e.ccy!=='USD').map(e=>e.ccy).join(',');const data=await remote(source);if(!Array.isArray(data))throw Error('format');const grouped={};for(const r of data){if(r.base!=='USD'||!Number.isFinite(r.rate)||r.rate<=0)continue;(grouped[r.date]??={})[r.quote]=r.rate;}const history=Object.entries(grouped).map(([date,rates])=>({date,rates})).sort((a,b)=>a.date.localeCompare(b.date));if(!history.length)throw Error('empty');return {history,source:'https://frankfurter.dev/',classification:'Daily blended central-bank reference rates. Not executable broker quotes.'};});
 if(u.pathname==='/api/market'){const d=MARKET.find(d=>d.id===u.searchParams.get('id'));if(!d)return Response.json({error:'Unknown symbol'},{status:400});if(!env.TWELVE_DATA_API_KEY)return Response.json({error:'Twelve Data is not connected. A server-side API key and appropriate data entitlements are required.'},{status:503});const symbol=d.symbol||(d.id==='DXY'?env.TWELVE_DXY_SYMBOL:env['TWELVE_'+d.id+'_SYMBOL']);if(!symbol)return Response.json({error:'Provider symbol and entitlement not configured.'},{status:503});return cached(request,ctx,3600,async()=>{const data=await remote('https://api.twelvedata.com/time_series?symbol='+encodeURIComponent(symbol)+'&interval=1day&outputsize=230&apikey='+encodeURIComponent(env.TWELVE_DATA_API_KEY));if(!Array.isArray(data.values))throw Error('source');const points=data.values.flatMap(r=>Number.isFinite(Number(r.close))?[{d:r.datetime.slice(0,10),v:Number(r.close)}]:[]).sort((a,b)=>a.d.localeCompare(b.d));return {id:d.id,points,source:'https://twelvedata.com',classification:'Daily closes; provider entitlements and delay apply',symbol};});}
 return Response.json({error:'Not found'},{status:404});}
async function spotApi(request,ctx){const symbol=new URL(request.url).searchParams.get('id');if(!['XAU','XAG'].includes(symbol))return Response.json({error:'Unknown spot metal'},{status:400});return cached(request,ctx,30,async()=>{const d=await remote('https://api.gold-api.com/price/'+symbol);if(d.symbol!==symbol||d.currency!=='USD'||!Number.isFinite(d.price)||d.price<=0||!Number.isFinite(Date.parse(d.updatedAt)))throw Error('format');return {id:symbol,value:d.price,updatedAt:d.updatedAt,source:'https://gold-api.com/docs',frequency:'Vendor updates approximately every 30 seconds',classification:'Indicative spot USD / troy ounce. Not a broker bid/ask quote.'};});}


async function loadUSInterestSources(env){
 const [core,funding]=env.BUCKET?await Promise.all([iceRead(env.BUCKET,'ice/latest.json'),iceRead(env.BUCKET,'funding/latest.json')]):[];
 const prior=mergeOvernightEvidence(core?.bundle,funding?.bundle);
 const effr=OVERNIGHT_FEEDS.find(d=>d.id==='fixing_effr');
 const fred=ICE_FEEDS.find(d=>d.id==='A091RC1Q027SBEA');
 const feeds=await Promise.all([effr,...US_FISCAL_FEEDS,fred].map(async def=>{
  let feed=prior.feeds[def.id],status,error;
  const savedStatus=prior.status[def.id];
  // The external collector is the primary path for Treasury and FRED when evidence exists.
  if(feed&&(def===fred||def.source.startsWith(TREASURY_DEBT_API))){
   status=savedStatus?.ok===false?'Saved observation retained':'Saved collector observation';
   error=savedStatus?.error;
  }else try{
   if(def===fred){
    const url='https://fred.stlouisfed.org/graph/fredgraph.csv?id='+def.id+'&cosd=2024-01-01';
    const points=parseFred(await remote(url,false),def.id);
    if(!points.length)throw Error('No BEA observations returned');
    feed={...def,points,retrievedAt:new Date().toISOString()};
   }else feed=await fetchExtraFeed(def);
   status='Direct retrieval';
  }catch(e){
   status=feed?'Saved observation retained':'Unavailable';
   error=e.safe||e.message;
  }
  const source=def.reference||def.source;
  const note=def===effr?'Volume-weighted median of overnight unsecured federal funds trades.':def===fred?'BEA national accounts, seasonally adjusted annual rate.':def.note;
  const entries=Array.isArray(feed?.series)?feed.series:[{label:def.name,unit:def.unit,points:feed?.points}];
  return entries.map(s=>({name:s.label,source,note,frequency:def.frequency,unit:s.unit||'—',last:s.points?.at(-1)||null,retrievedAt:feed?.retrievedAt||null,status,error}));
 }));
 return {rows:feeds.flat()};
}

BROKER_FEEDS.HFM_legacy_history={broker:'HFM',kind:'history'};


async function fredAuthenticatedHistory(id,key,start='1950-01-01'){
 if(typeof key!=='string'||!/^[a-z0-9]{32}$/.test(key))return null;
 const url=new URL('https://api.stlouisfed.org/fred/series/observations');
 url.search=new URLSearchParams({series_id:id,api_key:key,file_type:'json',observation_start:start});
 try{
  const response=await fetch(url,{headers:{Accept:'application/json'},redirect:'error',signal:AbortSignal.timeout(20000)});
  if(!response.ok)return null;
  const data=await response.json();
  if(!Array.isArray(data.observations)||!Number.isInteger(data.count)||data.count!==data.observations.length)return null;
  const points=data.observations.flatMap(({date,value})=>typeof value==='string'&&value.trim()&&value!=='.'&&
   /^\d{4}-\d{2}-\d{2}$/.test(date)&&date>=start&&Number.isFinite(Number(value))?[{d:date,v:Number(value)}]:[]);
  return points.length?points:null;
 }catch{return null;}
}
async function repairFred(def){
 const national=NATIONAL_PRIMARY[def.id];if(national&&!def.nationalFallback){try{return await nationalPrimary(def);}catch(error){const fallback=await repairFred({...def,series:national.mirror,nationalFallback:true});return {...fallback,series:national.series,sourceRole:'FRED mirror failure-only fallback',fallbackUsed:true,primaryError:error.message,primarySource:national.source};}}

 const id=def.series||def.id,key=globalThis.process?.env?.FRED_API_KEY,attempts=[];let last;
 const finish=(points,source)=>{points=points.filter(p=>p.d>='1950-01-01');if(!points.length)throw Error('No observations: '+id);return {...def,points:points.sort((a,b)=>a.d.localeCompare(b.d)),source,retrievedAt:new Date().toISOString(),releaseDate:null,sourcesTried:attempts};};
 const attempt=async(source,parser,json=false)=>{attempts.push(source.replace(/(api_key=)[^&]+/g,'$1[REDACTED]'));try{return finish(parser(await remote(source,json)),source.replace(/(api_key=)[^&]+/g,'$1[REDACTED]'));}catch(e){last=e;return null;}};
 const apiPoints=await fredAuthenticatedHistory(id,key);
 if(apiPoints)return {...finish(apiPoints,'https://fred.stlouisfed.org/series/'+id),transport:'FRED API'};
 let result;
 result=await attempt('https://fred.stlouisfed.org/graph/fredgraph.csv?id='+id,text=>parseFred(text,id));if(result)return result;
 if(['DGS10','DFII5','T10Y3M'].includes(id)){
 const real=id==='DFII5',year=new Date().getUTCFullYear(),source='https://home.treasury.gov/resource-center/data-chart-center/interest-rates/daily-treasury-rates.csv/'+year+'/all?type=daily_treasury_'+(real?'real_':'')+'yield_curve&field_tdr_date_value='+year+'&page&_format=csv';
 result=await attempt(source,text=>{const rows=parseCSV(text),h=rows.shift().map(x=>x.trim().toUpperCase()),ix=n=>h.indexOf(n.toUpperCase());return rows.flatMap(r=>{const raw=r[ix(real?'5 YR':'10 YR')],short=r[ix('3 MO')],date=new Date(r[ix('Date')]),v=Number(raw)-(id==='T10Y3M'?Number(short):0);return raw?.trim()&&(id!=='T10Y3M'||short?.trim())&&Number.isFinite(v)&&Number.isFinite(date.getTime())?[{d:date.toISOString().slice(0,10),v}]:[];});});if(result)return result;
 }
 if(id==='LRHUTTTTAUM156S'){
 result=await attempt('https://data.api.abs.gov.au/rest/data/ABS,LF,1.0.0/M13.3.1599.20.AUS.M?startPeriod=2020-01&format=csvfile',text=>repairSdmx(text));if(result)return result;
 result=await attempt('https://sdmx.oecd.org/public/rest/v1/data/OECD.SDD.TPS,DSD_LFS@DF_IALFS_UNE_M,1.0/AUS.M.UNE_LF..._T.Y._T._T?startPeriod=2020-01&format=csvfile',text=>repairSdmx(text));if(result)return result;
 }
 // BIS US policy measures are not interchangeable with either target bound.
 if(['DFEDTARU','DFEDTARL'].includes(id)){attempts.push('https://stats.bis.org/api/v2/data/dataflow/BIS/WS_CBPOL/1.0/D.US?lastNObservations=5&format=csv');try{await remote(attempts.at(-1),false);}catch(e){last=e;}last=Error('FRED target bound unavailable; BIS policy midpoint cannot replace a target bound');}
 throw Object.assign(last||Error('Feed unavailable'),{sources_tried:attempts});
}
