function oecdXmlAttributes(tag){
 const attributes={};
 for(const match of tag.matchAll(/\b([A-Za-z_][A-Za-z0-9_.:-]*)\s*=\s*(["'])(.*?)\2/g)){
  const value=match[3].replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&amp;/g,'&');
  if(Object.hasOwn(attributes,match[1]))throw Error('Duplicate OECD XML attribute');
  attributes[match[1]]=value;
 }
 return attributes;
}
function oecdXmlSection(xml,name){
 return xml.match(new RegExp('<(?:[\\w.-]+:)?'+name+'\\b[^>]*>([\\s\\S]*?)<\\/(?:[\\w.-]+:)?'+name+'>'))?.[1]||'';
}
function oecdXmlValues(xml){
 const values={};
 for(const match of xml.matchAll(/<(?:[\w.-]+:)?Value\b[^>]*\/>/g)){
  const attributes=oecdXmlAttributes(match[0]);
  if(!attributes.id||attributes.value===undefined||Object.hasOwn(values,attributes.id))throw Error('Invalid OECD SDMX value');
  values[attributes.id]=attributes.value;
 }
 return values;
}
function parseOecdXml(xml,flow,version){
 if(/<!DOCTYPE|<!ENTITY/i.test(xml)||!xml.includes('http://www.sdmx.org/resources/sdmxml/schemas/v2_1/data/generic'))throw Error('Unexpected OECD XML format');
 const header=oecdXmlSection(xml,'Header');
 const structures=[...header.matchAll(/<(?:[\w.-]+:)?Ref\b[^>]*\/>/g)].map(match=>oecdXmlAttributes(match[0]));
 if(!structures.some(ref=>ref.agencyID==='OECD.SDD.NAD'&&ref.id===flow&&ref.version===version))throw Error('Unexpected OECD dataflow identity');
 const rows=[];
 for(const match of xml.matchAll(/<(?:[\w.-]+:)?Series\b[^>]*>([\s\S]*?)<\/(?:[\w.-]+:)?Series>/g)){
  const block=match[1],key=oecdXmlValues(oecdXmlSection(block,'SeriesKey'));
  const beforeObservations=block.split(/<(?:[\w.-]+:)?Obs\b/)[0];
  const attributes=oecdXmlValues(oecdXmlSection(beforeObservations,'Attributes'));
  for(const observation of block.matchAll(/<(?:[\w.-]+:)?Obs\b[^>]*>([\s\S]*?)<\/(?:[\w.-]+:)?Obs>/g)){
   const body=observation[1];
   const dimension=oecdXmlAttributes(body.match(/<(?:[\w.-]+:)?ObsDimension\b[^>]*\/>/)?.[0]||'');
   const value=oecdXmlAttributes(body.match(/<(?:[\w.-]+:)?ObsValue\b[^>]*\/>/)?.[0]||'');
   if(dimension.id!=='TIME_PERIOD'||!dimension.value)throw Error('Unexpected OECD observation dimension');
   const row={...key,...attributes,...oecdXmlValues(oecdXmlSection(body,'Attributes')),TIME_PERIOD:dimension.value,OBS_VALUE:value.value,DATAFLOW:'OECD.SDD.NAD:'+flow+'('+version+')'};
   if(row.OBS_VALUE===undefined&&row.OBS_STATUS==='M')continue;
   if(row.UNIT_MULT!=='0'||row.CONF_STATUS!=='F')throw Error('Unexpected OECD scale or confidentiality status');
   officialNumber(row.OBS_VALUE);
   rows.push(row);
  }
 }
 if(!rows.length)throw Error('No OECD observations');
 return rows;
}
function parseOecdFeed(xml,def,now=Date.now()){
 const rows=parseOecdXml(xml,def.flow,def.version),groups=new Map();
 const names={OTES13:'Government expenditure',OTRS13:'Government revenue',B9S13:'Government net lending (+) / borrowing (-)',LES13_FD4:'Government gross debt',P3:'Final consumption',P51G:'Gross fixed capital formation',P6:'Exports',P7:'Imports',P5M:'Changes in inventories',B11:'External balance',S1:'Total economy',S1M:'Households and NPISH',S13:'General government'};
 for(const row of rows){
  if(Object.entries(def.dimensions).some(([key,values])=>!values.includes(row[key])))throw Error('Unexpected OECD series dimensions');
  const period=row.TIME_PERIOD;
  if(!(def.frequency==='Annual'?/^\d{4}$/:/^\d{4}-Q[1-4]$/).test(period))throw Error('Unexpected OECD observation period');
  const d=def.frequency==='Annual'?period+'-01-01':officialQuarterDate(period);
  const end=def.frequency==='Annual'?Date.UTC(Number(period),12,0):Date.UTC(Number(period.slice(0,4)),Number(period.at(-1))*3,0);
  if(end>now)continue;
  const ccy=OECD_SOURCE_AREAS[row.REF_AREA];
  if(!ccy)throw Error('Unexpected OECD economy');
  const components=def.seriesDimensions.map(key=>row[key]);
  const id=[def.id,ccy,...components].join('_');
  if(!groups.has(id))groups.set(id,{id,ccy,label:[ccy,...components.filter(value=>!['_Z','_T'].includes(value)).map(value=>names[value]||value)].join(' · '),frequency:def.frequency,unit:def.unit,source:def.source,dimensions:Object.fromEntries(Object.keys(def.dimensions).map(key=>[key,row[key]])),points:new Map()});
  const series=groups.get(id),point={d,v:officialNumber(row.OBS_VALUE),period,status:row.OBS_STATUS||null};
  const previous=series.points.get(d);
  if(previous&&(previous.v!==point.v||previous.status!==point.status))throw Error('Conflicting OECD observations');
  series.points.set(d,point);
 }
 const series=[...groups.values()].map(group=>({...group,points:[...group.points.values()].sort((a,b)=>a.d.localeCompare(b.d))})).filter(group=>group.points.length);
 if(!series.length)throw Error('No released OECD observations');
 const coverage=[...new Set(series.map(group=>group.ccy))];
 if(!def.seriesDimensions.length)return {byCurrency:Object.fromEntries(series.map(group=>[group.ccy,group.points])),coverage};
 return {series,coverage};
}
async function fetchOecdFeed(def){
 const xml=await remote(def.source,false,OECD_XML_ACCEPT);
 return {...def,...parseOecdFeed(xml,def),retrievedAt:new Date().toISOString(),releaseDate:null};
}
