 const path=/balance-of-payments-and-international-investment-position-(march|june|september|december)-(20\d{2})-quarter/ig;
 const releases=[...index.matchAll(path)].map(m=>({slug:m[0].toLowerCase(),quarter:statsNzQuarter(m[1].slice(0,3)+' '+m[2])})).filter(x=>x.quarter&&Date.parse(x.quarter.d)<=now).sort((a,b)=>b.quarter.d.localeCompare(a.quarter.d));
 const release=releases[0];
 if(!release)throw Error('Stats NZ quarterly release link unavailable');
 const reference='https://www.stats.govt.nz/information-releases/'+release.slug+'/';
 const html=accessibleXML(await(await official(reference)).text()).replace(/\\\//g,'/');
 const asset=html.match(/\/assets\/[A-Za-z0-9_./%-]+\.xlsx/gi)?.find(link=>link.toLowerCase().endsWith('/'+release.slug+'.xlsx'));
 if(!asset)throw Error('Stats NZ release workbook link unavailable');
 const source='https://www.stats.govt.nz'+asset;
 const workbook=await(await official(source)).arrayBuffer();
