 const points=[...index].flatMap(([d,v])=>{const base=index.get(String(Number(d.slice(0,4))-1)+d.slice(4));return base?[{d,v:(v/base-1)*100}]:[];}).sort((a,b)=>a.d.localeCompare(b.d));
 if(points.length<6)throw Error('FRED CP0000EZ19M086NEST insufficient observations');
