function iceScheduleEvidence(record,now=Date.now()){
 const s=record?.bundle?.officialSchedules,rows=nationalEvidence(record,ICE_FEEDS,now,iceReleaseRegistry(record,now));
 return rows.map(r=>{
  const key=r.ccy+'/'+r.feedId;
  if(key==='USD/cpi'&&r.period==='2026-09-01'&&now>=Date.parse('2026-11-10T13:30:00Z')&&
    now<Date.parse('2026-12-10T13:30:00Z')&&r.freshness==='Superseded'){
   return {...r,freshnessReason:'BLS published October month-on-month CPI but could not calculate headline year-on-year CPI because the October 2025 index is missing. September remains the saved year-on-year input.',
    scheduleSource:'https://www.bls.gov/news.release/archives/cpi_11102026.htm'};
  }
  if(!s?.entries)return r;
  if((key==='CAD/cpi'&&r.freshnessReason)||!r.mandatory||!ICE_SCHEDULE_KEYS.has(key)||[...RANK_CURRENT_STATES,'Superseded','Fallback - recheck'].includes(r.freshness))return r;
  const e=s.entries[key];
  return {...r,freshnessReason:'Schedule unverified: '+(e?r.freshness+' against the '+e.reader+' schedule (period '+e.period+', published '+(e.publishedAt||e.publishedDate)+', next '+(e.nextDueAt||e.nextReleaseDate)+')':'schedule reader failed: '+s.failures[key])};
 });
}

// OECD real GDP growth arrives with its CAD history replaced by Statistics Canada (national feeds).
// The OECD edition is accepted against the previous OECD edition, using the OECD's own CAD history
// kept as nationalCAD.oecdCAD; the Statistics Canada history is then checked and put back. When
// the Statistics Canada request failed, CAD stays the OECD history (labelled fallback).
function nationalOecdImport(f,def,prior,now){
 const n=f.nationalCAD,oecdCAD=n?.oecdCAD;
 if(!Array.isArray(oecdCAD)||!oecdCAD.length)throw Error('OECD CAD history missing from the national routing');
 const {nationalCAD,...feed}=f,previous=prior?.nationalCAD?.oecdCAD?{...prior,byCurrency:{...prior.byCurrency,CAD:prior.nationalCAD.oecdCAD}}:prior;
 const accepted=acceptOfficialMacro({...feed,byCurrency:{...feed.byCurrency,CAD:oecdCAD}},def,previous,now);
 if(n.fallbackUsed)return {...accepted,nationalCAD:{...n}};
 const cad=feed.byCurrency?.CAD;
 if(!Array.isArray(cad)||cad.length<9||cad.length>500||cad.some((p,i)=>!p||p.period!==officialQuarterPeriod(p.d)||p.status!=='A'||!Number.isFinite(p.v)||p.v<=-100||Date.parse(p.d)>now||
  (i&&officialQuarterIndex(p.d)-officialQuarterIndex(cad[i-1].d)!==1)))throw Error('Invalid Statistics Canada CAD history');
 if(!/^https:\/\/(www150\.statcan\.gc\.ca\/|api\.db\.nomics\.world\/v22\/series\/STATCAN\/36100104\/1\.1\.1\.30\?)/.test(n.source||''))throw Error('Unexpected Statistics Canada GDP source');
 return {...accepted,byCurrency:{...accepted.byCurrency,CAD:cad},nationalCAD:{...n}};
}

// Storage-only import transport. All collection parsing/evaluation runs on the PC.
const IMPORT_STAGE='ice/import-staging/';
// One import may write the live snapshot at a time. The lock names the owning run and is
// refreshed by every request of that run; a lock not refreshed for IMPORT_LOCK_TTL_MS
// (a crashed or abandoned run) expires and may be taken over by the next run.
const IMPORT_LOCK=IMPORT_STAGE+'lock.json',IMPORT_LOCK_TTL_MS=10*60*1000;
const importKey=k=>typeof k==='string'&&k.length<500&&!k.includes('..')&&!k.startsWith('/')&&!k.startsWith(IMPORT_STAGE)&&/^(ice|ops|validation|research|crossasset|experiments|market-context)\//.test(k);
async function importLockRead(bucket){
 const o=await bucket.get(IMPORT_LOCK);if(!o)return {lock:null,etag:null};
 let lock=null;try{lock=await o.json();}catch{}return {lock,etag:o.etag};
}
const importLockActive=lock=>!!lock?.run&&Date.now()-Date.parse(lock.heartbeatAt)<IMPORT_LOCK_TTL_MS;
const importLockRetry=lock=>Math.max(1,Math.ceil((IMPORT_LOCK_TTL_MS-(Date.now()-Date.parse(lock.heartbeatAt)))/1000));
const importLockPut=(bucket,lock,etag)=>bucket.put(IMPORT_LOCK,JSON.stringify(lock),{httpMetadata:{contentType:'application/json'},onlyIf:etag?{etagMatches:etag}:{etagDoesNotMatch:'*'}});
// Returns null when acquired, otherwise the active lock of a different run.
async function importLockAcquire(bucket,run){
 for(let attempt=0;attempt<3;attempt++){
  const {lock,etag}=await importLockRead(bucket);
  if(importLockActive(lock)&&lock.run!==run)return lock;
  const now=new Date().toISOString();
  const next={run,startedAt:now,heartbeatAt:now,...(lock?.run&&lock.run!==run?{replacedExpired:lock.run}:{})};
  if(await importLockPut(bucket,next,etag)!==null)return null;
 }
 const {lock}=await importLockRead(bucket);return lock||{run:'unknown',heartbeatAt:new Date().toISOString()};
}
// Refreshes the lock for its own run. False means the run no longer holds a live lock.
async function importLockHeartbeat(bucket,run){
 for(let attempt=0;attempt<3;attempt++){
  const {lock,etag}=await importLockRead(bucket);
  if(!importLockActive(lock)||lock.run!==run)return false;
  // Batch 39: refreshed within the last 30 seconds (TTL is 10 minutes): nothing to write, so simultaneous reads do not race.
  if(Date.now()-Date.parse(lock.heartbeatAt)<30000)return true;
  if(await importLockPut(bucket,{...lock,heartbeatAt:new Date().toISOString()},etag)!==null)return true;
 }
 // Batch 39: losing every race to this run's own simultaneous requests is not a lost lock; re-check who holds it.
 const {lock:current}=await importLockRead(bucket);
 return importLockActive(current)&&current.run===run;
}
async function importLockRelease(bucket,run){
 for(let attempt=0;attempt<3;attempt++){
  const {lock,etag}=await importLockRead(bucket);
  if(!lock||lock.run!==run)return false;
  if(await importLockPut(bucket,{run:null,releasedBy:run,releasedAt:new Date().toISOString()},etag)!==null)return true;
 }
 return false;
}
// Used by the single-request import and refresh routes: refuse while a staged run is live.
async function importLockBusy(bucket){
 const {lock}=await importLockRead(bucket);if(!importLockActive(lock))return null;
 return Response.json({error:'Import in progress',code:'import-in-progress',retryAfterSeconds:importLockRetry(lock)},{status:409,headers:{'Cache-Control':'no-store','Retry-After':String(importLockRetry(lock))}});
}
async function importCleanup(bucket){
 let cursor;
 do{const page=await bucket.list({prefix:IMPORT_STAGE,limit:1000,...(cursor?{cursor}:{})});
  for(const o of page.objects)if(o.key!==IMPORT_LOCK&&o.uploaded&&Date.now()-new Date(o.uploaded).getTime()>86400000){
   if(o.key.includes('/uploads/')){try{const u=await iceRead(bucket,o.key);await bucket.resumeMultipartUpload(u.key,u.uploadId).abort();}catch{}}
   await bucket.delete(o.key);
  }
  cursor=page.truncated?page.cursor:null;
 }while(cursor);
}
async function stagedImportApi(request,env){
 const bucket=env.BUCKET,url=new URL(request.url),op=url.pathname.split('/').at(-1),headers={'Cache-Control':'no-store'};
 const answer=(v,status=200,extra={})=>Response.json(v,{status,headers:{...headers,...extra}});
 if(request.headers.get('origin')&&request.headers.get('origin')!==url.origin)return answer({error:'Cross-origin write rejected'},403);
 // These endpoints are service-authenticated by the outer request handler.
 const run=url.searchParams.get('run');
 if(run!==null&&!/^[a-f0-9-]{36}$/.test(run))return answer({error:'Invalid run'},400);
 const lost=()=>answer({error:'Import lock not held by this run',code:'import-lock-lost'},409);
 if((op==='read'||op==='head'||op==='list')&&request.method==='GET'){
  // Reads made during the PC evaluation keep that run's lock alive.
  if(run&&!await importLockHeartbeat(bucket,run))return lost();
  if(op==='list'){
   const prefix=url.searchParams.get('prefix');if(!importKey(prefix))return answer({error:'Invalid prefix'},400);
   return answer(await bucket.list({prefix,limit:Math.min(1000,Number(url.searchParams.get('limit'))||1000)}));
  }
  const key=url.searchParams.get('key');if(!importKey(key))return answer({error:'Invalid key'},400);
  if(op==='head'){const o=await bucket.head(key);return o?answer({key,etag:o.etag,size:o.size}):answer(null,404);}
  // The version tag is also sent as X-Ice-Etag: proxies may drop or rewrite a standard ETag header.
  const o=await bucket.get(key);return o?new Response(o.body,{headers:{...headers,'Content-Type':'application/json','ETag':'"'+o.etag+'"','X-Ice-Etag':o.etag}}):answer(null,404);
 }
 if(!run)return answer({error:'Invalid run'},400);
 const prefix=IMPORT_STAGE+run+'/';
 if(op==='begin'&&request.method==='POST'){
  if(await bucket.head(prefix+'state'))return answer({error:'Run already exists'},409);
  const holder=await importLockAcquire(bucket,run);
  if(holder)return answer({error:'Import in progress',code:'import-in-progress',retryAfterSeconds:importLockRetry(holder)},409,{'Retry-After':String(importLockRetry(holder))});
  await importCleanup(bucket);
  const latest=await bucket.head('ice/latest.json');
  await bucket.put(prefix+'state',JSON.stringify({createdAt:new Date().toISOString(),etag:latest?.etag||null}));return answer({run,etag:latest?.etag||null});
 }
 const state=await iceRead(bucket,prefix+'state');if(!state||Date.now()-Date.parse(state.createdAt)>86400000)return answer({error:'Expired staging run'},410);
 if(await bucket.head(prefix+'committed'))return answer({error:'Run already committed'},409);
 if(op==='abort'&&request.method==='POST'){
  // Releases this run's lock early after a client-side failure. Never touches the live snapshot.
  return answer({released:await importLockRelease(bucket,run)});
 }
 if(!await importLockHeartbeat(bucket,run))return lost();
 if(op==='part'&&request.method==='POST'){
  const index=url.searchParams.get('index'),size=Number(request.headers.get('content-length'));
  if(!/^\d{1,5}$/.test(index||'')||!Number.isInteger(size)||size<1||size>6*1024*1024)return answer({error:'Invalid part size/index'},400);
  const key=prefix+'parts/'+index;
  if(await bucket.head(prefix+'done/'+index))return answer({error:'Part already processed'},409);
  await bucket.put(key,request.body,{httpMetadata:{contentType:'application/octet-stream'}});return answer({received:true});
 }
 if(op==='batch'&&request.method==='POST'){
  if(Number(request.headers.get('content-length'))>4096)return answer({error:'Batch too large'},413);
  const b=await request.json();
  if(!Number.isInteger(b.index)||b.index<0||b.index>99999||!importKey(b.key)||!Number.isInteger(b.part)||b.part<1||b.part>10000||!Number.isInteger(b.size)||b.size<1||b.size>6*1024*1024)return answer({error:'Invalid batch'},400);
  const done=await iceRead(bucket,prefix+'done/'+b.index);if(done)return JSON.stringify(done.batch)===JSON.stringify(b)?answer(done):answer({error:'Batch conflict'},409);
  const source=await bucket.get(prefix+'parts/'+b.index);if(!source||source.size!==b.size)return answer({error:'Missing or incomplete part'},409);
  const objectKey=prefix+'objects/'+encodeURIComponent(b.key),uploadKey=prefix+'uploads/'+encodeURIComponent(b.key);
  let upload=await iceRead(bucket,uploadKey);
  if(!upload){const m=await bucket.createMultipartUpload(objectKey);upload={key:objectKey,uploadId:m.uploadId};await bucket.put(uploadKey,JSON.stringify(upload));}
  const m=bucket.resumeMultipartUpload(upload.key,upload.uploadId),part=await m.uploadPart(b.part,source.body);
  const receipt={batch:b,part};await bucket.put(prefix+'done/'+b.index,JSON.stringify(receipt));return answer(receipt);
 }
 if(op==='commit'&&request.method==='POST'){
  if(Number(request.headers.get('content-length'))>200000)return answer({error:'Manifest too large'},413);
  const manifest=await request.json();
  if(!Array.isArray(manifest.objects)||manifest.objects.length>1000||!Number.isInteger(manifest.count)||manifest.count<1||manifest.count>10000)return answer({error:'Invalid manifest'},400);
  // The PC states which live snapshot version its evaluation read; it must be the one seen at begin.
  if(manifest.base!==undefined&&manifest.base!==state.etag)return answer({error:'Live snapshot changed'},409);
  const seen=new Set(),keys=new Set(),objects=[];
  // Validate every receipt before completing or publishing any object.
  for(const o of manifest.objects){
   if(!importKey(o.key)||keys.has(o.key)||!Array.isArray(o.indices)||!o.indices.length)return answer({error:'Invalid object'},400);keys.add(o.key);
   const parts=[];
   for(let i=0;i<o.indices.length;i++){
    const index=o.indices[i];if(!Number.isInteger(index)||seen.has(index))return answer({error:'Duplicate part'},400);seen.add(index);
    const r=await iceRead(bucket,prefix+'done/'+index);
    if(!r||r.batch.key!==o.key||r.batch.part!==i+1||!await bucket.head(prefix+'parts/'+index))return answer({error:'Missing or failed batch'},409);
    parts.push(r.part);
   }
   const upload=await iceRead(bucket,prefix+'uploads/'+encodeURIComponent(o.key));if(!upload)return answer({error:'Missing upload'},409);
   objects.push({key:o.key,upload,parts,options:o.options});
  }
  if(seen.size!==manifest.count||!keys.has('ice/latest.json'))return answer({error:'Incomplete collection'},409);
  const latest=await bucket.head('ice/latest.json');if((latest?.etag||null)!==state.etag)return answer({error:'Live snapshot changed'},409);
  for(const o of objects)await bucket.resumeMultipartUpload(o.upload.key,o.upload.uploadId).complete(o.parts);
  // Auxiliary records first; the conditional latest write is the sole live commit.
  objects.sort((a,b)=>(a.key==='ice/latest.json')-(b.key==='ice/latest.json'));
  for(const o of objects){const source=await bucket.get(o.upload.key);
   const saved=await bucket.put(o.key,source.body,{httpMetadata:{contentType:'application/json'},...(o.options||{}),...(o.key==='ice/latest.json'?{onlyIf:state.etag?{etagMatches:state.etag}:{etagDoesNotMatch:'*'}}:{})});
   if(o.key==='ice/latest.json'&&saved===null)return answer({error:'Concurrent live commit rejected'},409);
  }
  await bucket.put(prefix+'committed',JSON.stringify({at:new Date().toISOString()}));
  await importLockRelease(bucket,run);
  return answer({saved:true,objects:objects.length});
 }
 return answer({error:'Unknown staged import operation'},404);
}
